import * as Sentry from "@sentry/react";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { RouterProvider } from "@tanstack/react-router";
import React, { Suspense } from "react";

import { ErrorBoundary } from "./components/common/error-boundary";
import { NewVersionBanner } from "./components/common/new-version-banner";
import { DarkModeProvider } from "./context/dark-mode-context";
import { DebugProvider } from "./context/debug-context";
import { useVersionCheck } from "./hooks/use-version-check";
import { createAppRouter } from "./router";



const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      retry: 1,
      staleTime: 1000 * 60 * 5, // 5 minutes
      gcTime: 1000 * 60 * 10,   // GC inactive cache after 10 minutes
    },
  },
});

const router = createAppRouter(queryClient);

function AppContent() {
  const { hasNewVersion, dismiss } = useVersionCheck();

  return (
    <>
      {!!hasNewVersion && (
        <NewVersionBanner
          onDismiss={dismiss}
          onRefresh={() => { window.location.reload(); }}
        />
      )}
      <RouterProvider router={router} />
    </>
  );
}

function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <DebugProvider>
        <DarkModeProvider>
          { }
          <Sentry.ErrorBoundary fallback={(_error: unknown) => <ErrorBoundary>{null}</ErrorBoundary>}>
            <Suspense fallback={<div className="flex h-screen items-center justify-center">Loading...</div>}>
              <AppContent />
            </Suspense>
          </Sentry.ErrorBoundary>
        </DarkModeProvider>
      </DebugProvider>
    </QueryClientProvider>
  );
}

export default App;

import type { TFunction } from "i18next";

import * as Dialog from "@radix-ui/react-dialog";
import { X, Upload, FileText, Calendar } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { format } from "date-fns";

import { EmployeeSearch } from "@/components/common/employee-search";
import { useEnterPaperOt } from "@/hooks/use-attendance";
import { getCurrentWorkspaceId } from "@/lib/api/helpers";

interface Props {
  onOpenChange: (open: boolean) => void;
  onSuccess?: () => void;
  open: boolean;
}

interface EnterPaperOtFormProps {
  date: string;
  employeeId: string;
  error: string | null;
  handleSubmit: (e: React.SyntheticEvent) => void;
  isSubmitting: boolean;
  minutes: number;
  onCancel: () => void;
  reason: string;
  setDate: (date: string) => void;
  setEmployeeId: (id: string) => void;
  setMinutes: (minutes: number) => void;
  setReason: (reason: string) => void;
  t: TFunction;
  wsId: string;
}

function EnterPaperOtForm({
  employeeId,
  setEmployeeId,
  date,
  setDate,
  minutes,
  setMinutes,
  reason,
  setReason,
  error,
  isSubmitting,
  handleSubmit,
  onCancel,
  wsId,
  t
}: EnterPaperOtFormProps) {
  return (
    <form className="mt-6 space-y-5" onSubmit={handleSubmit}>
      {/* Employee Selector */}
      <div className="space-y-2">
        <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-[0.2em]">
          {t("common.employee") || "Employee"}
        </label>
        <EmployeeSearch
          onChange={(value) => { setEmployeeId(Array.isArray(value) ? value[0] || "" : value); }}
          placeholder={t("approvals.paper_ot.select_employee") || "Search employee..."}
          value={employeeId}
          workspaceId={wsId}
        />
      </div>

      {/* Date Picker */}
      <div className="space-y-2">
        <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-[0.2em]">
          {t("common.date") || "Date"}
        </label>
        <div className="relative">
          <Calendar className="absolute left-3 top-3 h-4 w-4 text-slate-400 dark:text-slate-500" />
          <input
            className="w-full pl-10 h-10 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 px-3 text-sm focus:ring-2 focus:ring-primary-600"
            max={format(new Date(), "yyyy-MM-dd")}
            onChange={(e) => { setDate(e.target.value); }}
            type="date"
            value={date}
          />
        </div>
      </div>

      {/* Minutes Input */}
      <div className="space-y-2">
        <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-[0.2em]">
          {t("approvals.paper_ot.minutes") || "OT Minutes"}
        </label>
        <input
          className="w-full h-10 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 px-3 text-sm font-mono focus:ring-2 focus:ring-primary-600"
          min={1}
          onChange={(e) => { setMinutes(parseInt(e.target.value) || 0); }}
          placeholder="120"
          type="number"
          value={minutes || ""}
        />
      </div>

      {/* Reason Textarea */}
      <div className="space-y-2">
        <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-[0.2em]">
          {t("common.reason") || "Reason"}
        </label>
        <textarea
          className="w-full rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 px-3 py-2 text-sm resize-none focus:ring-2 focus:ring-primary-600"
          onChange={(e) => { setReason(e.target.value); }}
          placeholder={t("approvals.paper_ot.reason_placeholder") || "Paper form #1234 - Production line"}
          rows={3}
          value={reason}
        />
      </div>

      {/* Photo Upload Placeholder (Optional) */}
      <div className="space-y-2">
        <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-[0.2em]">
          {t("approvals.paper_ot.photo") || "Paper Form Photo (Optional)"}
        </label>
        <div className="border-2 border-dashed border-slate-200 dark:border-slate-700 rounded-xl p-4 text-center hover:border-primary-400 transition-colors cursor-not-allowed opacity-50">
          <Upload className="w-8 h-8 text-slate-400 dark:text-slate-500 mx-auto mb-2" />
          <p className="text-xs text-slate-500 dark:text-slate-400">{t("approvals.paper_ot.photo_coming_soon") || "Photo upload coming soon"}</p>
        </div>
      </div>

      {/* Error Message */}
      {!!error && (
        <div className="text-xs font-bold text-rose-500 uppercase tracking-wide bg-rose-50 dark:bg-rose-950 p-3 rounded-lg">
          {error}
        </div>
      )}

      {/* Action Buttons */}
      <div className="flex justify-end gap-3 pt-2">
        <button
          className="px-4 py-2 rounded-xl text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700"
          onClick={onCancel}
          type="button"
        >
          {t("common.cancel") || "Cancel"}
        </button>
        <button
          className="px-6 py-2 rounded-xl bg-primary-600 text-white text-xs font-bold uppercase tracking-wider shadow-lg hover:bg-primary-700 disabled:opacity-50"
          disabled={isSubmitting}
          type="submit"
        >
          {isSubmitting ? (t("common.saving") || "Saving...") : (t("common.submit") || "Submit")}
        </button>
      </div>
    </form>
  );
}

export function EnterPaperOtDialog({ open, onOpenChange, onSuccess }: Props) {
  const { t } = useTranslation();
  const wsId = getCurrentWorkspaceId() ?? "";
  const { enterPaperOt, isSubmitting } = useEnterPaperOt();

  // Form state
  const [employeeId, setEmployeeId] = useState<string>("");
  const [date, setDate] = useState(format(new Date(), "yyyy-MM-dd"));
  const [minutes, setMinutes] = useState(0);
  const [reason, setReason] = useState("");
  const [photoUrl] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const resetForm = () => {
    setEmployeeId("");
    setDate(format(new Date(), "yyyy-MM-dd"));
    setMinutes(0);
    setReason("");
    setError(null);
  };

  const handleSubmit = async (e: React.SyntheticEvent) => {
    e.preventDefault();
    setError(null);

    // Validation
    if (!employeeId) {
      setError(t("approvals.paper_ot.error_no_employee") || "Select an employee");
      return;
    }
    if (minutes <= 0) {
      setError(t("approvals.paper_ot.error_minutes") || "Minutes must be > 0");
      return;
    }
    if (!reason.trim()) {
      setError(t("approvals.paper_ot.error_reason") || "Reason is required");
      return;
    }

    try {
      await enterPaperOt({
        employeeId,
        date,
        claimed_minutes: minutes,
        reason,
        paper_form_photo_url: photoUrl ?? undefined,
      });
      resetForm();
      onOpenChange(false);
      onSuccess?.();

    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : "Failed to submit";
      setError(message);
    }
  };

  return (
    <Dialog.Root onOpenChange={(o) => { if (!o) resetForm(); onOpenChange(o); }} open={open}>
      <Dialog.Portal>
        <Dialog.Overlay className="fixed inset-0 bg-black/40 z-50 backdrop-blur-sm" />
        <Dialog.Content className="fixed left-1/2 top-1/2 z-50 w-full max-w-lg -translate-x-1/2 -translate-y-1/2 border border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900 p-6 shadow-xl rounded-[2rem]">
          <Dialog.Title className="text-xl font-bold text-slate-800 dark:text-slate-100 uppercase tracking-tight flex items-center gap-2">
            <FileText className="w-5 h-5" />
            {t("approvals.paper_ot.title") || "Enter Paper OT Form"}
          </Dialog.Title>
          <Dialog.Description className="text-sm text-slate-500 dark:text-slate-400 mt-1">
            {t("approvals.paper_ot.description") || "Enter overtime claim from signed paper form"}
          </Dialog.Description>

          <button className="absolute right-4 top-4 p-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-700" onClick={() => { onOpenChange(false); }}>
            <X className="h-4 w-4" />
          </button>

          <EnterPaperOtForm
            date={date}
            employeeId={employeeId}
            error={error}
            handleSubmit={handleSubmit}
            isSubmitting={isSubmitting}
            minutes={minutes}
            onCancel={() => { onOpenChange(false); }}
            reason={reason}
            setDate={setDate}
            setEmployeeId={setEmployeeId}
            setMinutes={setMinutes}
            setReason={setReason}
            t={t}
            wsId={wsId}
          />
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

import { QueryClient, QueryClientProvider, useQuery  } from "@tanstack/react-query";
import { render, screen, fireEvent, waitFor } from "@testing-library/react";

import { describe, it, expect, vi, beforeEach } from "vitest";

import { EmployeeSearch } from "../employee-search";

// Create a simpler mock for the query hook
vi.mock("@tanstack/react-query", async () => {
  const actual = await vi.importActual("@tanstack/react-query");
  return {
    ...actual,
    useQuery: vi.fn(),
  };
});


const queryClient = new QueryClient({
  defaultOptions: { queries: { retry: false } },
});

const wrapper = ({ children }: { children: React.ReactNode }) => (
  <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>
);

describe("EmployeeSearch Component", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  const mockEmployees = [
    { id: "1", full_name: "John Doe", employee_id_number: "E001" },
    { id: "2", full_name: "Jane Smith", employee_id_number: "E002" },
  ];

  it("calls onChange when an employee is selected", async () => {

    vi.mocked(useQuery).mockReturnValue({
      data: { data: mockEmployees },
      isLoading: false,
    } as unknown as never);

    const onChange = vi.fn();
    // We test the internal handleSelect by bypassing the complex Radix UI
    // and just checking if the component passes correct data to Combobox
    render(<EmployeeSearch onChange={onChange} workspaceId="ws-1" />, { wrapper });

    // Fallback select is used when Radix trigger is not fully rendered in JSDOM
    expect(screen.getByRole("combobox")).toBeDefined();
  });

  it("renders chips in multiple mode", async () => {
    vi.mocked(useQuery).mockReturnValue({
      data: { data: mockEmployees },
      isLoading: false,
    } as unknown as never);

    const onChange = vi.fn();
    const value = ["1"];
    render(<EmployeeSearch multiple onChange={onChange} value={value} workspaceId="ws-1" />, { wrapper });

    // With the new useEffect, it should find '1' in mockEmployees and show 'John Doe'
    await waitFor(() => {
      expect(screen.getAllByText("John Doe").length).toBeGreaterThanOrEqual(1);
    });
  });

  it("preserves server-side relevance order (exact match > prefix > contains)", () => {
    // Simulate server returning results in relevance-ranked order:
    // #16 (exact) > #161 (prefix) > #1649 (prefix) > #416 (contains)
    const rankedEmployees = [
      { id: "a", full_name: "Nguyen Van A", employee_id_number: "16" },
      { id: "b", full_name: "Tran Van B", employee_id_number: "161" },
      { id: "c", full_name: "Le Van C", employee_id_number: "1649" },
      { id: "d", full_name: "Pham Van D", employee_id_number: "416" },
    ];


    vi.mocked(useQuery).mockReturnValue({
      data: { data: rankedEmployees },
      isLoading: false,
    } as unknown as never);

    const onChange = vi.fn();
    render(<EmployeeSearch onChange={onChange} workspaceId="ws-1" />, { wrapper });

    // The combobox should be rendered with options in the exact order from the API
    const combobox = screen.getByRole("combobox");
    expect(combobox).toBeDefined();

    // Verify the component did NOT re-sort the data alphabetically
    // by checking the first option is still the exact match employee
    const allOptions = screen.queryAllByText(/16|161|1649|416/);
    if (allOptions.length > 0) {
      // First visible option should be the exact match "16", not "1649" or "416"
      expect(allOptions[0].textContent).toContain("16");
    }
  });

  it("passes keyboardShortcut prop to Combobox", () => {

    vi.mocked(useQuery).mockReturnValue({
      data: { data: mockEmployees },
      isLoading: false,
    } as unknown as never);

    const onChange = vi.fn();
    render(
      <EmployeeSearch keyboardShortcut="/" onChange={onChange} workspaceId="ws-1" />,
      { wrapper }
    );

    // Should render without crashing with the keyboardShortcut prop
    expect(screen.getByRole("combobox")).toBeDefined();
  });

  it("calls onSelectEmployee with the full Employee object when selected via hidden select", () => {

    vi.mocked(useQuery).mockReturnValue({
      data: { data: mockEmployees },
      isLoading: false,
    } as unknown as never);

    const onChange = vi.fn();
    const onSelectEmployee = vi.fn();

    render(
      <EmployeeSearch
        onChange={onChange}
        onSelectEmployee={onSelectEmployee}
        workspaceId="ws-1"
      />,
      { wrapper }
    );

    // Use the hidden select element (sr-only) to simulate selection
    const hiddenSelect = screen.getByRole("combobox");
    fireEvent.change(hiddenSelect, { target: { value: "1" } });

    // onChange should have been called with just the id
    expect(onChange).toHaveBeenCalledWith("1");

    // onSelectEmployee should have been called with the full employee object
    expect(onSelectEmployee).toHaveBeenCalledWith(
      expect.objectContaining({
        id: "1",
        full_name: "John Doe",
        employee_id_number: "E001",
      })
    );
  });

  it("does NOT call onSelectEmployee when employee is not found in data", () => {

    vi.mocked(useQuery).mockReturnValue({
      data: { data: mockEmployees },
      isLoading: false,
    } as unknown as never);

    const onChange = vi.fn();
    const onSelectEmployee = vi.fn();

    render(
      <EmployeeSearch
        onChange={onChange}
        onSelectEmployee={onSelectEmployee}
        workspaceId="ws-1"
      />,
      { wrapper }
    );

    // Try selecting an ID that does not exist in mockEmployees
    const hiddenSelect = screen.getByRole("combobox");
    fireEvent.change(hiddenSelect, { target: { value: "non-existent-id" } });

    // onChange is still called (to update the value), but with empty string since it's not found
    expect(onChange).toHaveBeenCalledWith("");

    // But onSelectEmployee should NOT have been called since no Employee was found
    expect(onSelectEmployee).not.toHaveBeenCalled();
  });
});

import { render, screen } from "@testing-library/react";
import React, { createRef } from "react";

import userEvent from "@testing-library/user-event";
import { describe, it, expect, vi, beforeEach } from "vitest";

import type { NavigableListColumn } from "../navigable-list";

import NavigableList from "../navigable-list";

// Mock IntersectionObserver for jsdom
class MockIntersectionObserver {
    observe() { /* empty */ }
    unobserve() { /* empty */ }
    disconnect() { /* empty */ }
}

window.IntersectionObserver = MockIntersectionObserver as unknown as typeof IntersectionObserver;

// Mock scroll methods not available in jsdom
Element.prototype.scrollIntoView = vi.fn();

Element.prototype.scrollTo = vi.fn();

vi.mock("react-i18next", () => ({
    useTranslation: () => ({
        t: (key: string, fallback?: string) => fallback ?? key,
        i18n: { changeLanguage: () => Promise.resolve(), language: "en" },
    }),
}));

// ---------------------------------------------------------------------------
// Test data
// ---------------------------------------------------------------------------

interface TestItem {
    id: string;
    name: string;
    value: number;
}

const items: TestItem[] = [
    { id: "1", name: "Alpha", value: 10 },
    { id: "2", name: "Beta", value: 20 },
    { id: "3", name: "Charlie", value: 30 },
];

const columns: NavigableListColumn<TestItem>[] = [
    { key: "name", header: "Name", cell: (item) => item.name },
    { key: "value", header: "Value", cell: (item) => `${item.value}`, cellClassName: "text-right" },
];

const defaultProps = {
    columns,
    items,
    itemKey: (item: TestItem) => item.id,
    onSelect: vi.fn(),
};

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe("NavigableList", () => {
    beforeEach(() => { vi.clearAllMocks(); });

    // ── Rendering ──────────────────────────────────────────────

    it("renders all items", () => {
        render(<NavigableList {...defaultProps} />);
        expect(screen.getByText("Alpha")).toBeDefined();
        expect(screen.getByText("Beta")).toBeDefined();
        expect(screen.getByText("Charlie")).toBeDefined();
    });

    it("renders column headers", () => {
        render(<NavigableList {...defaultProps} />);
        expect(screen.getByText("Name")).toBeDefined();
        expect(screen.getByText("Value")).toBeDefined();
    });

    it("renders empty state when no items", () => {
        render(<NavigableList {...defaultProps} emptyMessage="Nothing here" items={[]} />);
        expect(screen.getByText("Nothing here")).toBeDefined();
    });

    it("renders loading skeletons when isLoading", () => {
        const { container } = render(<NavigableList {...defaultProps} isLoading skeletonRows={3} />);
        const skeletons = container.querySelectorAll(".animate-pulse");
        // 3 skeleton rows × 2 columns = 6 pulse divs
        expect(skeletons.length).toBe(6);
    });

    it("hides columns with hidden=true", () => {
        const cols: NavigableListColumn<TestItem>[] = [
            ...columns,
            { key: "secret", header: "Secret", cell: () => "hidden", hidden: true },
        ];
        render(<NavigableList {...defaultProps} columns={cols} />);
        expect(screen.queryByText("Secret")).toBeNull();
        expect(screen.queryByText("hidden")).toBeNull();
    });

    // ── Search ─────────────────────────────────────────────────

    it("renders search box when onSearchChange is provided", () => {
        render(
            <NavigableList
                {...defaultProps}
                onSearchChange={vi.fn()}
                searchTestId="test-search"
                searchValue=""
            />
        );
        expect(screen.getByTestId("test-search")).toBeDefined();
    });

    it("does not render search box when onSearchChange is omitted", () => {
        render(<NavigableList {...defaultProps} />);
        expect(screen.queryByTestId("navigable-list-search")).toBeNull();
    });

    // ── Row interaction ────────────────────────────────────────

    it("calls onSelect when a row is clicked", async () => {
        const onSelect = vi.fn();
        const user = userEvent.setup();
        render(<NavigableList {...defaultProps} onSelect={onSelect} />);

        await user.click(screen.getByText("Beta"));
        expect(onSelect).toHaveBeenCalledWith(items[1]);
    });

    it("highlights selected row", () => {
        const { container } = render(
            <NavigableList {...defaultProps} selectedKey="2" />
        );
        const row = container.querySelector("#nav-row-1");
        expect(row?.className).toContain("bg-primary-50");
    });

    it("shows active bar on selected row when showActiveBar is true", () => {
        const { container } = render(
            <NavigableList {...defaultProps} selectedKey="2" showActiveBar />
        );
        const bar = container.querySelector(".bg-primary-600.rounded-r-full");
        expect(bar).toBeDefined();
    });

    // ── Keyboard navigation ────────────────────────────────────

    it("ArrowDown moves focus to the next row", async () => {
        const user = userEvent.setup();
        const { container } = render(
            <NavigableList
                {...defaultProps}
                onSearchChange={vi.fn()}
                searchTestId="test-search"
                searchValue=""
            />
        );

        const searchInput = screen.getByTestId("test-search");
        await user.click(searchInput);
        await user.keyboard("{ArrowDown}");

        // Focus should move from 0 to 1 — row 1 should have focused class
        const row1 = container.querySelector("#nav-row-1");
        expect(row1?.className).toContain("ring-primary-500");
    });

    it("ArrowUp moves focus to the previous row", async () => {
        const user = userEvent.setup();
        const { container } = render(
            <NavigableList
                {...defaultProps}
                onSearchChange={vi.fn()}
                searchTestId="test-search"
                searchValue=""
            />
        );

        const searchInput = screen.getByTestId("test-search");
        await user.click(searchInput);
        // Go down twice, then up once → should be at index 1
        await user.keyboard("{ArrowDown}{ArrowDown}{ArrowUp}");

        const row1 = container.querySelector("#nav-row-1");
        expect(row1?.className).toContain("ring-primary-500");
    });

    it("Enter calls onSelect with the focused item", async () => {
        const onSelect = vi.fn();
        const user = userEvent.setup();
        render(
            <NavigableList
                {...defaultProps}
                onSearchChange={vi.fn()}
                onSelect={onSelect}
                searchTestId="test-search"
                searchValue=""
            />
        );

        const searchInput = screen.getByTestId("test-search");
        await user.click(searchInput);
        await user.keyboard("{ArrowDown}{Enter}");

        expect(onSelect).toHaveBeenCalledWith(items[1]);
    });

    it("ArrowDown does not go past the last item", async () => {
        const user = userEvent.setup();
        const { container } = render(
            <NavigableList
                {...defaultProps}
                onSearchChange={vi.fn()}
                searchTestId="test-search"
                searchValue=""
            />
        );

        const searchInput = screen.getByTestId("test-search");
        await user.click(searchInput);
        // Press ArrowDown 10 times (more than items.length)
        for (let index = 0; index < 10; index++) {
            await user.keyboard("{ArrowDown}");
        }

        // Should be clamped at last index (2)
        const lastRow = container.querySelector("#nav-row-2");
        expect(lastRow?.className).toContain("ring-primary-500");
    });

    it("ArrowUp does not go below 0", async () => {
        const user = userEvent.setup();
        const { container } = render(
            <NavigableList
                {...defaultProps}
                onSearchChange={vi.fn()}
                searchTestId="test-search"
                searchValue=""
            />
        );

        const searchInput = screen.getByTestId("test-search");
        await user.click(searchInput);
        // Press ArrowUp when already at 0 — should stay at 0
        await user.keyboard("{ArrowUp}{ArrowUp}");

        // Row 0 should have focus ring (ArrowUp sets hasNavigated=true)
        const firstRow = container.querySelector("#nav-row-0");
        expect(firstRow?.className).toContain("ring-primary-500");
        // Row 1 should NOT have focus ring
        const secondRow = container.querySelector("#nav-row-1");
        expect(secondRow?.className).not.toContain("ring-primary-500");
    });

    // ── Sortable headers ───────────────────────────────────────

    it("calls onHeaderClick when a sortable header is clicked", async () => {
        const onSort = vi.fn();
        const user = userEvent.setup();
        const sortableCols: NavigableListColumn<TestItem>[] = [
            { key: "name", header: "Name", cell: (item) => item.name, onHeaderClick: onSort },
            { key: "value", header: "Value", cell: (item) => `${item.value}` },
        ];

        render(<NavigableList {...defaultProps} columns={sortableCols} />);
        await user.click(screen.getByText("Name"));
        expect(onSort).toHaveBeenCalledTimes(1);
    });

    it("makes sortable headers have cursor-pointer class", () => {
        const sortableCols: NavigableListColumn<TestItem>[] = [
            { key: "name", header: "Name", cell: (item) => item.name, onHeaderClick: vi.fn() },
            { key: "value", header: "Value", cell: (item) => `${item.value}` },
        ];
        const { container } = render(<NavigableList {...defaultProps} columns={sortableCols} />);
        const headers = container.querySelectorAll("th");
        expect(headers[0].className).toContain("cursor-pointer");
        expect(headers[1].className).not.toContain("cursor-pointer");
    });

    // ── Chevrons ───────────────────────────────────────────────

    it("renders chevrons when showChevron is true (default)", () => {
        const { container } = render(<NavigableList {...defaultProps} />);
        const chevrons = container.querySelectorAll("svg.lucide-chevron-right");
        expect(chevrons.length).toBe(items.length);
    });

    it("hides chevrons when showChevron is false", () => {
        const { container } = render(<NavigableList {...defaultProps} showChevron={false} />);
        const chevrons = container.querySelectorAll("svg.lucide-chevron-right");
        expect(chevrons.length).toBe(0);
    });

    // ── Custom row IDs and test IDs ────────────────────────────

    it("sets row IDs with custom rowIdPrefix", () => {
        const { container } = render(
            <NavigableList {...defaultProps} rowIdPrefix="custom-row" />
        );
        expect(container.querySelector("#custom-row-0")).toBeDefined();
        expect(container.querySelector("#custom-row-1")).toBeDefined();
    });

    it("sets data-testid with testIdPrefix", () => {
        render(<NavigableList {...defaultProps} testIdPrefix="item" />);
        expect(screen.getByTestId("item-1")).toBeDefined();
        expect(screen.getByTestId("item-2")).toBeDefined();
        expect(screen.getByTestId("item-3")).toBeDefined();
    });

    // ── Header slot ────────────────────────────────────────────

    it("renders headerSlot content above the table", () => {
        render(
            <NavigableList
                {...defaultProps}
                headerSlot={<div data-testid="custom-header">Filters</div>}
            />
        );
        expect(screen.getByTestId("custom-header")).toBeDefined();
        expect(screen.getByText("Filters")).toBeDefined();
    });

    // ── onKeyDownRef ───────────────────────────────────────────

    it("exposes keyboard handler via onKeyDownRef", () => {

        const ref = createRef<((e: React.KeyboardEvent<HTMLInputElement>) => void) | null>() as React.MutableRefObject<((e: React.KeyboardEvent<HTMLInputElement>) => void) | null>;
        ref.current = null;

        render(<NavigableList {...defaultProps} onKeyDownRef={ref} />);
        expect(ref.current).toBeDefined();
        expect(typeof ref.current).toBe("function");
    });
});

import React, { Component } from "react";

interface ErrorBoundaryProps {
  children?: React.ReactNode;
  fallback?: React.ReactNode;
  onError?: (error: Error, errorInfo: React.ErrorInfo) => void;
}

interface ErrorBoundaryState {
  error: Error | null;
  hasError: boolean;
}


export class ErrorBoundary extends Component<
  ErrorBoundaryProps,
  ErrorBoundaryState
> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    console.error("[ErrorBoundary]", error, errorInfo);
    this.props.onError?.(error, errorInfo);
  }

  handleRetry = () => {
    this.setState({ hasError: false, error: null });
  };

  handleHardReload = () => {
    window.location.reload();
  };

  render() {
    if (this.state.hasError) {
      if (this.props.fallback) return this.props.fallback;

      return (
        <div className="min-h-[400px] flex items-center justify-center p-8">
          <div className="max-w-md text-center space-y-4">
            <div className="w-16 h-16 mx-auto rounded-full bg-red-100 dark:bg-red-900/30 flex items-center justify-center">
              <svg className="w-8 h-8 text-red-500" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
                <circle cx="12" cy="12" r="10" />
                <line x1="15" x2="9" y1="9" y2="15" />
                <line x1="9" x2="15" y1="9" y2="15" />
              </svg>
            </div>
            <h2 className="text-lg font-semibold text-slate-800 dark:text-slate-200">
              Something went wrong
            </h2>
            <p className="text-sm text-slate-500 dark:text-slate-400">
              {this.state.error?.message ?? "An unexpected error occurred"}
            </p>
            <div className="flex justify-center gap-3">
              <button
                className="px-4 py-2 text-sm font-medium rounded-lg bg-blue-600 text-white hover:bg-blue-700 transition-colors"
                onClick={this.handleRetry}
              >
                Try again
              </button>
              <button
                className="px-4 py-2 text-sm font-medium rounded-lg border border-slate-300 dark:border-slate-600 text-slate-700 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
                onClick={this.handleHardReload}
              >
                Reload page
              </button>
            </div>
            {!!this.state.error && !!import.meta.env.DEV && (
              <pre className="mt-4 p-4 text-left text-xs bg-slate-100 dark:bg-slate-900 rounded-lg overflow-auto max-h-[200px] text-red-600 dark:text-red-400">
                {this.state.error.stack}
              </pre>
            )}
          </div>
        </div>
      );
    }

    return this.props.children ?? null;
  }
}

