    return (
        <>
            {Array.from({ length: skeletonRows }).map((_, index) => (
                <tr key={`skeleton-${index}`}>
                    {visibleColumns.map((col) => (
                        <td className={cn("px-8 py-5", col.cellClassName)} key={col.key}>
