            </th>
            {!!isDebugMode && (
              <th className="px-4 py-2.5 text-[10px] font-bold text-amber-600 dark:text-amber-300 uppercase tracking-widest text-center">
                DEBUG
              </th>
            )}
            <th className="px-4 py-2.5"></th>
          </tr>
        </thead>

        <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
          {isLoading ? (
            <tr>
              <td
                className="px-10 py-20 text-center text-slate-500 dark:text-slate-400 font-bold italic uppercase tracking-widest text-xs opacity-50 animate-pulse"
                colSpan={isDebugMode ? (hideEmployeeName ? 9 : 10) : (hideEmployeeName ? 8 : 9)}
              >
                {t("common.loading")}
              </td>
            </tr>
          ) : data.length === 0 ? (
            <tr>
              <td
                className="px-10 py-32 text-center text-slate-500 dark:text-slate-400 font-bold italic uppercase tracking-widest text-xs opacity-50"
                colSpan={isDebugMode ? (hideEmployeeName ? 9 : 10) : (hideEmployeeName ? 8 : 9)}
              >
                {t("reports.messages.no_data")}
              </td>
            </tr>
          ) : (
            data.map((row: DailyAttendanceReport) => (
              <DailyReportTableRow
                adjustmentMap={adjustmentMap}
                confirmingRow={confirmingRow}
                expandedDebugRows={expandedDebugRows}
                formatDate={formatDate}
                formatTime={formatTime}
                hideEmployeeName={hideEmployeeName}
                isDebugMode={isDebugMode}
                key={`${row.employee_id}-${row.date}`}
                onApproveOt={onApproveOt}
                onConfirmClick={onConfirmClick}
                onReprocessClick={onReprocessClick}
                onResolveUnscheduled={onResolveUnscheduled}
                onToggleExpandRow={onToggleExpandRow}
                reprocessingRow={reprocessingRow}
                row={row}
                t={t}
                workUnitMinutes={workUnitMinutes}
              />
            ))
          )}
        </tbody>
      </table>
    </div>
  );
}

import type { TFunction } from "i18next";

import { CalendarCheck, FileBarChart, Clock } from "lucide-react";
import React, { useRef, useEffect } from "react";
import { useTranslation } from "react-i18next";

import type { DailyAttendanceReport, AttendanceAdjustmentRequest, Shift } from "@/lib/api";

import Sheet from "@/components/ui/sheet";
import { useDebug } from "@/context/debug-context";
import { useDateTimeFormatter } from "@/hooks/use-datetime";

import ConfirmAttendanceModal from "./confirm-attendance-modal";
import ConfirmReprocessModal from "./confirm-reprocess-modal";
import DailyReportTable from "./daily-report-table";
import RawLogsTable from "./raw-logs-table";
import ResolveUnscheduledModal from "./resolve-unscheduled-modal";
import { useEmployeeDailyDrawer } from "./use-employee-daily-drawer";

interface EmployeeDailyDrawerProps {
    dateRange: { start: string; end: string };
    employeeId: string;
    employeeName: string;
    isOpen: boolean;
    onClose: () => void;
    workspaceId: string;
    workUnitMinutes: number;
}

interface EmployeeDailyDrawerHeaderProps {
    isLoading: boolean;
    reportData: any[];
    setViewMode: (mode: "daily" | "raw") => void;
    t: TFunction;
    totalOtHours: string | number;
    totalStdHours: string | number;
    viewMode: "daily" | "raw";
}

function EmployeeDailyDrawerHeader({ viewMode, setViewMode, isLoading, reportData, totalStdHours, totalOtHours, t }: EmployeeDailyDrawerHeaderProps) {
    return (
        <>
            <div className="flex bg-slate-100 dark:bg-slate-800 rounded-lg p-1 border border-slate-200 dark:border-slate-700">
                <button
                    className={`px-3 py-1.5 text-[10px] font-bold uppercase tracking-widest rounded-md transition-all ${viewMode === "daily"
                        ? "bg-white dark:bg-slate-700 text-primary-600 dark:text-primary-400 shadow-sm"
                        : "text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200"
                        }`}
                    onClick={() => { setViewMode("daily"); }}
                >
                    {t("reports.tabs.daily")}
                </button>
                <button
                    className={`px-3 py-1.5 text-[10px] font-bold uppercase tracking-widest rounded-md transition-all ${viewMode === "raw"
                        ? "bg-white dark:bg-slate-700 text-primary-600 dark:text-primary-400 shadow-sm"
                        : "text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200"
                        }`}
                    onClick={() => { setViewMode("raw"); }}
                >
                    <span className="flex items-center gap-1.5"><CalendarCheck size={12} /> {t("reports.view_raw_logs")}</span>
                </button>
            </div>
            {viewMode === "daily" && !isLoading && reportData.length > 0 && (
                <>
                    <div className="flex items-center gap-1.5 bg-slate-900 dark:bg-slate-800 px-3 py-1.5 rounded-lg border border-slate-800 dark:border-slate-700 shadow-sm">
                        <FileBarChart className="text-primary-400" size={12} />
                        <span className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">{t("reports.quick_stats.std_hours")}</span>
                        <span className="font-mono font-bold text-white text-xs tracking-tighter">{totalStdHours}h</span>
                    </div>
                    {Number(totalOtHours) > 0 && (
                        <div className="flex items-center gap-1.5 bg-gradient-to-r from-orange-900 to-orange-950 px-3 py-1.5 rounded-lg border border-orange-800 shadow-sm">
                            <Clock className="text-orange-400" size={12} />
                            <span className="text-[9px] font-bold text-orange-400/70 uppercase tracking-widest">{t("reports.quick_stats.ot_hours")}</span>
                            <span className="font-mono font-bold text-orange-100 text-xs tracking-tighter">{totalOtHours}h</span>
                        </div>
                    )}
                </>
            )}
        </>
    );
}

interface EmployeeDailyDrawerModalsProps {
    confirmDialog: { show?: boolean; employeeId: string; employeeName: string; date: string } | null;
    confirmModalData: { row: DailyAttendanceReport; existingRequest?: AttendanceAdjustmentRequest } | null;
    confirmMutationPending: boolean;
    handleConfirmReprocess: () => void;
    handleConfirmSubmit: (data: any) => void;
    handleResolveSubmit: (shiftId: string) => void;
    reprocessMutationPending: boolean;
    resolveModalData: { row: DailyAttendanceReport } | null;
    resolveUnscheduledMutationPending: boolean;
    setConfirmDialog: (data: { show: boolean; employeeId: string; employeeName: string; date: string } | null) => void;
    setConfirmModalData: (data: { row: DailyAttendanceReport; existingRequest?: AttendanceAdjustmentRequest } | null) => void;
    setResolveModalData: (data: { row: DailyAttendanceReport } | null) => void;
    shifts?: Shift[];
}

function EmployeeDailyDrawerModals({
    confirmDialog,
    reprocessMutationPending,
    setConfirmDialog,
    handleConfirmReprocess,
    confirmModalData,
    confirmMutationPending,
    setConfirmModalData,
    handleConfirmSubmit,
    resolveModalData,
    resolveUnscheduledMutationPending,
    setResolveModalData,
    handleResolveSubmit,
    shifts
}: EmployeeDailyDrawerModalsProps) {
    return (
        <>
            <ConfirmReprocessModal
                dialogData={confirmDialog}
                isOpen={!!confirmDialog}
                isPending={reprocessMutationPending}
                key={confirmDialog ? `reprocess-${confirmDialog.employeeId}-${confirmDialog.date}` : "reprocess-empty"}
                onClose={() => { setConfirmDialog(null); }}
                onConfirm={handleConfirmReprocess}
            />

            <ConfirmAttendanceModal
                existingRequest={confirmModalData?.existingRequest}
                isOpen={!!confirmModalData}
                isPending={confirmMutationPending}
                key={confirmModalData ? `confirm-${confirmModalData.row.date}` : "confirm-empty"}
                onClose={() => { setConfirmModalData(null); }}
                onSubmit={handleConfirmSubmit}
                row={confirmModalData?.row ?? null}
            />

            <ResolveUnscheduledModal
                isOpen={!!resolveModalData}
                isPending={resolveUnscheduledMutationPending}
                key={resolveModalData ? `resolve-${resolveModalData.row.date}` : "resolve-empty"}
                onClose={() => { setResolveModalData(null); }}
                onSubmit={handleResolveSubmit}
                row={resolveModalData?.row ?? null}
                shifts={shifts}
            />
        </>
    );
}

export default function EmployeeDailyDrawer(props: EmployeeDailyDrawerProps) {
    const { isOpen, onClose, employeeName, dateRange, workUnitMinutes } = props;
    const { t } = useTranslation();
    const { formatDate, formatTime } = useDateTimeFormatter();
    const { isEnabled: isDebugMode } = useDebug();
    const contentRef = useRef<HTMLDivElement>(null);

    const {
        viewMode,
        setViewMode,
        expandedDebugRows,
        toggleExpandRow,
        reprocessingRow,
        confirmingRow,
        confirmDialog,
        setConfirmDialog,
        confirmModalData,
        setConfirmModalData,
        resolveModalData,
        setResolveModalData,
        reportData,
        isLoading,
        rawLogsData,
        rawLogsLoading,
        hasNextPage,
        isFetchingNextPage,
        fetchNextPage,
        adjustmentMap,
        shifts,
        totalStdHours,
        totalOtHours,
        handleReprocessClick,
        handleConfirmReprocess,
        handleConfirmClick,
        handleConfirmSubmit,
        handleApproveOt,
        handleResolveUnscheduled,
        handleResolveSubmit,
        reprocessMutationPending,
        confirmMutationPending,
        resolveUnscheduledMutationPending,
    } = useEmployeeDailyDrawer(props);

    // Keyboard navigation for tabs + scroll
    useEffect(() => {
        if (!isOpen) return;

        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) {
                return;
            }

            if (e.key === "ArrowRight" && viewMode === "daily") {
                setViewMode("raw");
            } else if (e.key === "ArrowLeft" && viewMode === "raw") {
                setViewMode("daily");
            } else if (e.key === "ArrowDown" || e.key === "ArrowUp") {
                e.preventDefault();
                const scrollContainer = contentRef.current?.querySelector(".overflow-auto") ?? contentRef.current;
                if (scrollContainer) {
                    scrollContainer.scrollBy({ top: e.key === "ArrowDown" ? 100 : -100, behavior: "smooth" });
                }
            }
        };

        window.addEventListener("keydown", handleKeyDown);
        return () => { window.removeEventListener("keydown", handleKeyDown); };
    }, [isOpen, viewMode, setViewMode]);

    return (
        <>
            <Sheet
                className="w-[95vw] xl:w-[1200px] !max-w-[95vw]"
                contentClassName="!overflow-hidden"
                headerExtra={
                    <EmployeeDailyDrawerHeader
                        isLoading={isLoading}
                        reportData={reportData}
                        setViewMode={setViewMode}
                        t={t}
                        totalOtHours={totalOtHours}
                        totalStdHours={totalStdHours}
                        viewMode={viewMode}
                    />
                }
                isOpen={isOpen}
                onClose={onClose}
                subtitle={`${formatDate(dateRange.start)} — ${formatDate(dateRange.end)}`}
                title={employeeName}
            >
                <div className="-mx-10 -mt-4 -mb-10 h-[calc(100%+theme(spacing.14))] flex flex-col" ref={contentRef}>
                    {viewMode === "raw" ? (
                        <RawLogsTable
                            fetchNextPage={fetchNextPage}
                            hasNextPage={hasNextPage}
                            isFetchingNextPage={isFetchingNextPage}
                            rawLogsData={rawLogsData}
                            rawLogsLoading={rawLogsLoading}
                        />
                    ) : (
                        <DailyReportTable
                            adjustmentMap={adjustmentMap}
                            confirmingRow={confirmingRow}
                            data={reportData}
                            expandedDebugRows={expandedDebugRows}
                            formatDate={formatDate}
                            formatTime={formatTime}
                            hideEmployeeName
                            isDebugMode={isDebugMode}
                            isLoading={isLoading}
                            onApproveOt={handleApproveOt}
                            onConfirmClick={handleConfirmClick}
                            onReprocessClick={handleReprocessClick}
                            onResolveUnscheduled={handleResolveUnscheduled}
                            onToggleExpandRow={toggleExpandRow}
                            reprocessingRow={reprocessingRow}
                            t={t}
                            workUnitMinutes={workUnitMinutes}
                        />
                    )}
                </div>
            </Sheet>

            <EmployeeDailyDrawerModals
                confirmDialog={confirmDialog}
                confirmModalData={confirmModalData}
                confirmMutationPending={confirmMutationPending}
                handleConfirmReprocess={handleConfirmReprocess}
                handleConfirmSubmit={handleConfirmSubmit}
                handleResolveSubmit={handleResolveSubmit}
                reprocessMutationPending={reprocessMutationPending}
                resolveModalData={resolveModalData}
                resolveUnscheduledMutationPending={resolveUnscheduledMutationPending}
                setConfirmDialog={setConfirmDialog}
                setConfirmModalData={setConfirmModalData}
                setResolveModalData={setResolveModalData}
                shifts={shifts}
            />
        </>
    );
}

import { SearchX, Clock } from "lucide-react";
import React from "react";
import { useTranslation } from "react-i18next";

import InfiniteScrollSentinel from "@/components/common/infinite-scroll-sentinel";
import { useDateTimeFormatter } from "@/hooks/use-datetime";
import { useInfiniteScroll } from "@/hooks/use-infinite-scroll";
import { RawAttendanceLog } from "@/lib/api";

interface RawLogsTableProps {
    fetchNextPage: () => void;
    hasNextPage: boolean;
    isFetchingNextPage: boolean;
    rawLogsData: RawAttendanceLog[];
    rawLogsLoading: boolean;
}

export default function RawLogsTable({
    rawLogsData,
    rawLogsLoading,
    hasNextPage,
    isFetchingNextPage,
    fetchNextPage,
}: RawLogsTableProps) {
    const { t } = useTranslation();
    const { formatDate, formatTime } = useDateTimeFormatter();

    const loadMoreRef = useInfiniteScroll<HTMLTableRowElement>({
        hasNextPage,
        isFetchingNextPage,
        fetchNextPage,
    });

    return (
        <div className="overflow-auto flex-1 min-h-0 relative">
            <table className="w-full text-left border-collapse">
                <thead>
                    <tr className="bg-slate-50/95 dark:bg-slate-800/95 backdrop-blur-sm border-b border-slate-100 dark:border-slate-800 sticky top-0 z-10">
                        <th className="px-8 py-4 text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest">{t("common.time")}</th>
                        <th className="px-8 py-4 text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest">{t("common.source")}</th>
                        <th className="px-8 py-4 text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest text-right">{t("common.status")}</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
                    {rawLogsLoading ? (
                        Array.from({ length: 5 }).map((_, index) => (
                            <tr className="border-b border-slate-50 dark:border-slate-800/50" key={`skeleton-log-${index}`}>
                                <td className="px-8 py-5">
                                    <div className="flex items-center gap-4">
                                        <div className="w-10 h-10 rounded-xl bg-slate-100 dark:bg-slate-800 animate-pulse"></div>
                                        <div className="space-y-1">
                                            <div className="h-4 w-20 bg-slate-200 dark:bg-slate-700 animate-pulse rounded"></div>
                                            <div className="h-3 w-16 bg-slate-100 dark:bg-slate-800 animate-pulse rounded"></div>
                                        </div>
                                    </div>
                                </td>
                                <td className="px-8 py-5">
                                    <div className="h-4 w-24 bg-slate-200 dark:bg-slate-700 animate-pulse rounded"></div>
                                </td>
                                <td className="px-8 py-5 text-right">
                                    <div className="flex justify-end">
                                        <div className="h-4 w-16 bg-emerald-100 dark:bg-emerald-900/20 animate-pulse rounded-full"></div>
                                    </div>
                                </td>
                            </tr>
                        ))
                    ) : rawLogsData.length === 0 ? (
                        <tr>
                            <td className="px-8 py-20" colSpan={3}>
                                <div className="flex flex-col items-center justify-center text-center animate-in fade-in zoom-in-95 duration-500 max-w-sm mx-auto">
                                    <div className="w-16 h-16 mb-4 rounded-3xl bg-slate-50 dark:bg-slate-800/80 flex items-center justify-center text-slate-300 dark:text-slate-600 shadow-inner border border-slate-100 dark:border-slate-700/50 rotate-3">
                                        <SearchX className="-rotate-3" size={24} />
                                    </div>
                                    <h3 className="text-xs font-bold text-slate-700 dark:text-slate-200 uppercase tracking-widest mb-1">
                                        {t("attendance_logs.messages.no_data")}
                                    </h3>
                                    <p className="text-[10px] font-medium text-slate-500 dark:text-slate-400 max-w-[200px]">
                                        No punches were recorded for this day.
                                    </p>
                                </div>
                            </td>
                        </tr>
                    ) : (
                        rawLogsData.map((log: RawAttendanceLog) => (
                            <tr className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors group" key={log.id}>
                                <td className="px-8 py-5">
                                    <div className="flex items-center gap-4">
                                        <div className="w-10 h-10 rounded-xl bg-primary-50 dark:bg-primary-950 flex items-center justify-center text-primary-600 dark:text-primary-400 shadow-inner border border-primary-100 dark:border-primary-800/50"><Clock size={18} /></div>
                                        <div>
                                            <div className="font-bold text-slate-700 dark:text-slate-200 text-sm tracking-tight uppercase">{formatDate(log.punch_time)}</div>
                                            <div className="text-[10px] font-bold text-slate-500 dark:text-slate-400 font-mono uppercase tracking-tighter">{formatTime(log.punch_time)}</div>
                                        </div>
                                    </div>
                                </td>
                                <td className="px-8 py-5">
                                    <div className="flex flex-col gap-1">
                                        <div className="flex items-center gap-2">
                                            <span className="px-2.5 py-1 bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300 rounded-lg text-[9px] font-bold uppercase tracking-widest border border-slate-200 dark:border-slate-700">{log.source}</span>
                                            {!!log.device_name && <span className="text-[10px] font-bold text-slate-700 dark:text-slate-200 uppercase">{log.device_name}</span>}
                                        </div>
                                    </div>
                                </td>
                                <td className="px-8 py-5 text-right">
                                    <span className="px-3 py-1 bg-emerald-50 dark:bg-emerald-950 text-emerald-600 dark:text-emerald-300 rounded-full text-[9px] font-bold uppercase tracking-widest border border-emerald-100 dark:border-emerald-800 shadow-sm">{t("attendance_logs.status.recorded")}</span>
                                </td>
                            </tr>
                        ))
                    )}
                    {!!hasNextPage && <InfiniteScrollSentinel colSpan={3} isFetchingNextPage={isFetchingNextPage} sentinelRef={loadMoreRef} />}
                </tbody>
            </table>
        </div>
    );
}

