    );
}

import { useQuery, useMutation, useQueryClient, useInfiniteQuery } from "@tanstack/react-query";
import { useState, useMemo, useEffect } from "react";
import { useTranslation } from "react-i18next";

import { useToast } from "@/components/ui/toast";
import {
    fetchAttendanceReport,
    DailyAttendanceReport,
    reprocessAttendance,
    fetchWorkspaceAttendanceAdjustments,
    adminConfirmAttendance,
    AttendanceAdjustmentRequest,
    approveOt,
    fetchRawAttendanceLogs,
    fetchShifts,
    upsertRoster,
} from "@/lib/api";
import { formatUnitsToHours } from "@/lib/utils/attendance";

interface UseEmployeeDailyDrawerProps {
    dateRange: { start: string; end: string };
    employeeId: string;
    isOpen: boolean;
    workspaceId: string;
    workUnitMinutes: number;
}

export function useEmployeeDailyDrawer({
    isOpen,
    workspaceId,
    employeeId,
    dateRange,
    workUnitMinutes,
}: UseEmployeeDailyDrawerProps) {
    const { t } = useTranslation();
    const queryClient = useQueryClient();
    const toast = useToast();

    const [viewMode, setViewMode] = useState<"daily" | "raw">("daily");

    // Reset to daily tab whenever the drawer is (re-)opened
    // eslint-disable-next-line react-hooks/set-state-in-effect -- intentional
    useEffect(() => { if (isOpen) setViewMode("daily"); }, [isOpen]);

    const [expandedDebugRows, setExpandedDebugRows] = useState<Set<string>>(new Set());
    const [reprocessingRow, setReprocessingRow] = useState<string | null>(null);
    const [confirmingRow, setConfirmingRow] = useState<string | null>(null);
    const [confirmDialog, setConfirmDialog] = useState<{
        show: boolean;
        employeeId: string;
        employeeName: string;
        date: string;
    } | null>(null);
    const [confirmModalData, setConfirmModalData] = useState<{
        row: DailyAttendanceReport;
        existingRequest?: AttendanceAdjustmentRequest;
    } | null>(null);
    const [resolveModalData, setResolveModalData] = useState<{
        row: DailyAttendanceReport;
    } | null>(null);

    // Fetch daily data for this single employee
    const { data: reportResponse, isLoading } = useQuery({
        queryKey: ["attendance-report", workspaceId, dateRange, "daily", 1, 100, undefined, [employeeId]],
        queryFn: () =>
            fetchAttendanceReport(workspaceId, dateRange.start, dateRange.end, "daily", 1, 100, undefined, [employeeId]),
        enabled: isOpen && !!workspaceId && !!employeeId,
    });

    const { data: pendingAdjustments } = useQuery({
        queryKey: ["attendance-adjustments", workspaceId, "pending"],
        queryFn: () => fetchWorkspaceAttendanceAdjustments(workspaceId, "pending"),
        enabled: isOpen && !!workspaceId,
    });

    // Fetch shift types for the unscheduled resolution modal
    const { data: shifts } = useQuery({
        queryKey: ["shifts", workspaceId],
        queryFn: () => fetchShifts(workspaceId),
        enabled: isOpen && !!workspaceId,
    });

    // Fetch raw logs for this single employee with infinite scroll
    const {
        data: rawLogsResponse,
        isLoading: rawLogsLoading,
        fetchNextPage,
        hasNextPage,
        isFetchingNextPage
    } = useInfiniteQuery({
        queryKey: ["raw-logs", workspaceId, dateRange, [employeeId]],
        queryFn: ({ pageParam }) => {
            const from = dateRange.start ? new Date(`${dateRange.start}T00:00:00`).toISOString() : undefined;
            const to = dateRange.end ? new Date(`${dateRange.end}T23:59:59`).toISOString() : undefined;
            return fetchRawAttendanceLogs({ employee_id: employeeId, from, to, page: pageParam, limit: 100 });
        },
        getNextPageParam: (lastPage, allPages) => {
            if (lastPage.data.length < 100) return undefined;
            return allPages.length + 1;
        },
        initialPageParam: 1,
        enabled: isOpen && !!workspaceId && !!employeeId && viewMode === "raw",
    });

    // Extract flat array of logs
    const rawLogsData = useMemo(() => {
        if (!rawLogsResponse) return [];
        return rawLogsResponse.pages.flatMap((p) => p.data);
    }, [rawLogsResponse]);

    const adjustmentMap = useMemo(() => {
        const map: Record<string, AttendanceAdjustmentRequest> = {};
        pendingAdjustments?.forEach((request) => {
            const key = `${request.employee_id}-${request.requested_date}`;
            map[key] = request;
        });
        return map;
    }, [pendingAdjustments]);

    const reportData = useMemo(
        () => (reportResponse?.data ?? (Array.isArray(reportResponse) ? reportResponse : [])) as DailyAttendanceReport[],
        [reportResponse]
    );

    // Compute total hours for summary bar
    const { totalStdHours, totalOtHours } = useMemo(() => {
        const stdUnits = reportData.reduce((sum: number, r: DailyAttendanceReport) => sum + (r.std_work_units || 0), 0);
        const otUnits = reportData.reduce((sum: number, r: DailyAttendanceReport) => sum + (r.ot_work_units || 0), 0);
        return {
            totalStdHours: formatUnitsToHours(stdUnits, workUnitMinutes),
            totalOtHours: formatUnitsToHours(otUnits, workUnitMinutes),
        };
    }, [reportData, workUnitMinutes]);

    const toggleExpandRow = (rowKey: string) => {
        const next = new Set(expandedDebugRows);
        if (next.has(rowKey)) next.delete(rowKey);
        else next.add(rowKey);
        setExpandedDebugRows(next);
    };

    // Reprocess mutation
    const reprocessMutation = useMutation({
        mutationFn: ({ empId, date }: { empId: string; date: string }) =>
            reprocessAttendance(workspaceId, empId, date, date),
        onSuccess: () => {
            void queryClient.invalidateQueries({ queryKey: ["attendance-report"] });
            setReprocessingRow(null);
            setConfirmDialog(null);
            toast.success(t("common.success"));
        },
    });

    // Confirm mutation
    const confirmMutation = useMutation({
        mutationFn: ({
            row,
            existingRequestId,
            reason,
        }: {
            row: DailyAttendanceReport;
            existingRequestId?: string;
            reason?: string;
        }) => adminConfirmAttendance(workspaceId, row, existingRequestId, reason),
        onSuccess: () => {
            void queryClient.invalidateQueries({ queryKey: ["attendance-report"] });
            void queryClient.invalidateQueries({ queryKey: ["attendance-adjustments"] });
            setConfirmingRow(null);
            setConfirmModalData(null);
            toast.success(t("reports.confirm.success"));
        },
        onError: () => {
            setConfirmingRow(null);
            toast.error(t("reports.confirm.error"));
        },
    });

    // OT approve mutation
    const approveOtMutation = useMutation({
        mutationFn: ({ row, action }: { row: DailyAttendanceReport; action: "approved" | "rejected" }) =>
            approveOt(workspaceId, row.employee_id, {
                date: row.date,
                approved_minutes: row.ot_work_units * (workUnitMinutes || 60),
                status: action,
            }),
        onSuccess: (_data, variables) => {
            void queryClient.invalidateQueries({ queryKey: ["attendance-report"] });
            const message =
                variables.action === "approved"
                    ? t("reports.ot_approve.success_approved")
                    : t("reports.ot_approve.success_rejected");
            toast.success(message);
        },
        onError: () => {
            toast.error(t("reports.ot_approve.error"));
        },
    });

    // Resolve unscheduled mutation: upsert roster + reprocess
    const resolveUnscheduledMutation = useMutation({
        mutationFn: async ({ row, shiftId }: { row: DailyAttendanceReport; shiftId: string }) => {
            // Step 1: Assign the shift to this day
            await upsertRoster(workspaceId, row.employee_id, {
                date: row.date,
                shift_id: shiftId,
            });
            // Step 2: Reprocess to recalculate attendance with the new shift
            await reprocessAttendance(workspaceId, row.employee_id, row.date, row.date);
        },
        onSuccess: () => {
            void queryClient.invalidateQueries({ queryKey: ["attendance-report"] });
            setResolveModalData(null);
            toast.success(t("reports.unscheduled.success"));
        },
        onError: () => {
            toast.error(t("reports.unscheduled.error"));
        },
    });

    const handleApproveOt = (row: DailyAttendanceReport, action: "approved" | "rejected") => {
        approveOtMutation.mutate({ row, action });
    };

    const handleResolveUnscheduled = (row: DailyAttendanceReport) => {
        setResolveModalData({ row });
    };

    const handleResolveSubmit = (shiftId: string) => {
        if (!resolveModalData) return;
        resolveUnscheduledMutation.mutate({
            row: resolveModalData.row,
            shiftId,
        });
    };

    const handleReprocessClick = (row: DailyAttendanceReport) => {
        setConfirmDialog({
            show: true,
            employeeId: row.employee_id,
            employeeName: row.employee_name,
            date: row.date,
        });
    };

    const handleConfirmReprocess = () => {
        if (!confirmDialog) return;
        setReprocessingRow(`${confirmDialog.employeeId}-${confirmDialog.date}`);
        reprocessMutation.mutate({ empId: confirmDialog.employeeId, date: confirmDialog.date });
    };

    const handleConfirmClick = (row: DailyAttendanceReport, existing?: AttendanceAdjustmentRequest) => {
        setConfirmModalData({ row, existingRequest: existing });
    };

    const handleConfirmSubmit = ({ punchIn, punchOut, reason }: { punchIn: string; punchOut: string; reason: string }) => {
        if (!confirmModalData) return;
        const { row, existingRequest } = confirmModalData;
        const rowKey = `${row.employee_id}-${row.date}`;
        setConfirmingRow(rowKey);

        if (existingRequest) {
            confirmMutation.mutate({ row, existingRequestId: existingRequest.id });
        } else {
            const createIsoFromLocal = (dateString: string, hhmm: string): string | null => {
                if (!hhmm) return null;
                const [y, m, d] = dateString.split("-").map(Number);
                const [hours, mins] = hhmm.split(":").map(Number);
                return new Date(y, m - 1, d, hours, mins, 0).toISOString();
            };

            const modifiedRow = {
                ...row,
                actual_punch_in: createIsoFromLocal(row.date, punchIn),
                actual_punch_out: createIsoFromLocal(row.date, punchOut),
            };
            confirmMutation.mutate({ row: modifiedRow, reason });
        }
    };

    return {
        viewMode,
        setViewMode,
        expandedDebugRows,
        toggleExpandRow,
        reprocessingRow,
        confirmingRow,
        confirmDialog,
        setConfirmDialog,
        confirmModalData,
        setConfirmModalData,
        resolveModalData,
        setResolveModalData,
        reportData,
        isLoading,
        rawLogsData,
        rawLogsLoading,
        hasNextPage,
        isFetchingNextPage,
        fetchNextPage,
        adjustmentMap,
        shifts,
        totalStdHours,
        totalOtHours,
        handleReprocessClick,
        handleConfirmReprocess,
        handleConfirmClick,
        handleConfirmSubmit,
        handleApproveOt,
        handleResolveUnscheduled,
        handleResolveSubmit,
        reprocessMutationPending: reprocessMutation.isPending,
        confirmMutationPending: confirmMutation.isPending,
        resolveUnscheduledMutationPending: resolveUnscheduledMutation.isPending,
    };
}

import { KeyRound, Plus, Trash2, Clock, Search } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import Modal from "@/components/ui/modal";
import { useConfirm } from "@/hooks/use-confirm";
import { useDateTimeFormatter } from "@/hooks/use-datetime";
import { useMemberPermissions } from "@/hooks/use-workspace";


interface PermissionManagementModalProps {
    isOpen: boolean;
    onClose: () => void;
    userId: string | null;
}

export default function PermissionManagementModal({
    userId,
    isOpen,
    onClose,
}: PermissionManagementModalProps) {
    const { t } = useTranslation();
    const { formatDateTime } = useDateTimeFormatter();
    const {
        permissions,
        available,
        isLoading,
        assignPermission,
        revokePermission,
    } = useMemberPermissions(userId ?? "", undefined);
    const [newPermission, setNewPermission] = useState("");
    const [expiresAt, setExpiresAt] = useState("");
    const [searchTerm, setSearchTerm] = useState("");
    const { confirm, ConfirmationDialog } = useConfirm();

    const filteredAvailable = available.filter(
        (p) =>
            p.toLowerCase().includes(searchTerm.toLowerCase()) &&
            !permissions.some((ep) => ep.permission === p),
    );

    async function handleAssign(e: React.FormEvent) {
        e.preventDefault();
        if (!expiresAt || !newPermission || !userId) return;
        try {
            const isoExpiresAt = new Date(expiresAt).toISOString();
            await assignPermission({ permission: newPermission, expiresAt: isoExpiresAt });
            setExpiresAt("");
            setNewPermission("");
            setSearchTerm("");
        } catch (e) {
            console.error(e);
        }
    }

    async function handleRevoke(permId: string) {
        const ok = await confirm({
            title: t("common.warning", { defaultValue: "Warning" }),
            message: t("members.permissions.confirm_revoke", { defaultValue: "Revoke this permission?" }),
            variant: "danger"
        });
        if (!ok) return;
        try {
            await revokePermission(permId);
        } catch (e) {
            console.error(e);
        }
    }

    if (!isOpen) return null;

    return (
        <Modal
            icon={<KeyRound size={24} />}
            isOpen={isOpen}
            maxWidth="lg"
            onClose={onClose}
            subtitle={t("members.permissions.modal_subtitle", { defaultValue: "Grant or revoke individual permissions" })}
            title={t("members.permissions.modal_title", { defaultValue: "Manage Permissions" })}
        >
            <div className="space-y-10">
                    {isLoading ? (
                        <div className="py-20 text-center text-slate-500 dark:text-slate-400 font-bold italic uppercase tracking-widest text-xs opacity-50 animate-pulse">{t("common.loading")}</div>
                    ) : (
                        <div className="space-y-10 animate-in fade-in duration-700">
                            {/* Active permissions list */}
                            <div className="space-y-5 px-1">
                                <label className="text-[10px] font-bold uppercase tracking-[0.25em] text-slate-500 dark:text-slate-400 ml-1">
                                    {t("members.permissions.active_label", { defaultValue: "Active Extra Permissions" }).toUpperCase()}
                                </label>

                                <div className="space-y-4 max-h-[300px] overflow-y-auto">
                                    {permissions.map((perm) => (
                                        <div className="flex items-center justify-between p-6 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-800 rounded-[2rem] hover:bg-white dark:hover:bg-slate-900 hover:shadow-xl hover:shadow-amber-100/10 transition-all group relative overflow-hidden shadow-inner" key={perm.id}>
                                            <div className="space-y-2 min-w-0 flex-1">
                                                <p className="font-bold text-slate-700 dark:text-slate-200 text-sm tracking-tight leading-none font-mono">{perm.permission}</p>
                                                <div className="flex items-center gap-2 text-[10px] text-slate-500 dark:text-slate-400 font-bold uppercase tracking-widest opacity-70">
                                                    <Clock className="text-amber-400" size={12} /> <span>{t("members.roles.expires_at", { defaultValue: "Expires" }).toUpperCase()}: {formatDateTime(perm.expires_at)}</span>
                                                </div>
                                            </div>
                                            <button className="p-3 bg-white dark:bg-slate-900 text-slate-300 dark:text-slate-600 hover:text-rose-600 dark:text-rose-300 rounded-xl shadow-md border border-slate-100 dark:border-slate-800 transition-all opacity-0 group-hover:opacity-100 translate-x-2 group-hover:translate-x-0 active:scale-90 flex-shrink-0 ml-4" onClick={() => handleRevoke(perm.id)}><Trash2 size={18} /></button>
                                        </div>
                                    ))}

                                    {permissions.length === 0 && (
                                        <div className="text-center py-12 border-2 border-dashed border-slate-100 dark:border-slate-800 rounded-[2.5rem] bg-slate-50 dark:bg-slate-800/30 flex flex-col items-center">
                                            <KeyRound className="text-slate-200 dark:text-slate-700 mb-4" size={32} />
                                            <p className="text-[10px] font-bold text-slate-300 dark:text-slate-600 uppercase tracking-widest opacity-60 italic">
                                                {t("members.permissions.no_extra_permissions", { defaultValue: "No extra permissions" })}
                                            </p>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>
                    )}

                    {/* Assign new permission */}
                    <div className="pt-10 border-t border-slate-50 dark:border-slate-800 space-y-8">
                        <h3 className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-[0.3em] flex items-center gap-3 px-1">
                            <Plus className="text-amber-500" size={16} /> {t("members.permissions.assign_new_title", { defaultValue: "Grant Permission" }).toUpperCase()}
                        </h3>
                        <form className="space-y-6 animate-in slide-in-from-bottom-4 duration-700" onSubmit={handleAssign}>
                            <div className="space-y-3 px-1">
                                <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ml-1">
                                    {t("members.permissions.permission_label", { defaultValue: "Permission" })}
                                </label>
                                <div className="relative">
                                    <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                                    <input
                                        className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-800 rounded-2xl pl-12 pr-6 py-4 focus:ring-4 focus:ring-amber-500/10 focus:bg-white dark:focus:bg-slate-900 outline-none transition-all font-bold text-sm tracking-tight shadow-sm"
                                        onChange={(e) => {
                                            setSearchTerm(e.target.value);
                                            setNewPermission("");
                                        }}
                                        placeholder={t("members.permissions.search_placeholder", { defaultValue: "Search permissions..." })}
                                        type="text"
                                        value={searchTerm}
                                    />
                                </div>
                                {!!searchTerm && filteredAvailable.length > 0 && (
                                    <div className="max-h-48 overflow-y-auto rounded-2xl border border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900 shadow-lg">
                                        {filteredAvailable.map((p) => (
                                            <button
                                                className={`w-full text-left px-6 py-3 text-sm font-mono hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors ${newPermission === p ? "bg-amber-50 dark:bg-amber-950 text-amber-600 dark:text-amber-400 font-bold" : "text-slate-600 dark:text-slate-300"}`}
                                                key={p}
                                                onClick={() => { setNewPermission(p); setSearchTerm(p); }}
                                                type="button"
                                            >
                                                {p}
                                            </button>
                                        ))}
                                    </div>
                                  )}
                                {!!newPermission && (
                                    <p className="text-[10px] text-amber-600 dark:text-amber-400 font-bold uppercase tracking-widest ml-1">
                                        ✓ {newPermission}
                                    </p>
                                  )}
                            </div>
                            <div className="space-y-3 px-1">
                                <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ml-1" htmlFor="perm-expires-at-input">
                                    {t("members.permissions.expiry_label", { defaultValue: "Expiration" })}
                                </label>
                                <input className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-800 rounded-2xl px-6 py-4 focus:ring-4 focus:ring-amber-500/10 focus:bg-white dark:focus:bg-slate-900 outline-none transition-all font-bold text-sm tracking-tight shadow-sm" id="perm-expires-at-input" onChange={(e) => { setExpiresAt(e.target.value); }} required type="datetime-local" value={expiresAt}
                                />
                            </div>
                            <div className="pt-2">
                                <button
                                    className="w-full bg-slate-900 text-white py-5 rounded-2xl font-bold text-xs uppercase tracking-[0.2em] hover:bg-amber-700 transition-all shadow-2xl shadow-slate-400 dark:shadow-black/40 active:scale-95 disabled:opacity-40 disabled:cursor-not-allowed"
                                    disabled={!newPermission || !expiresAt}
                                    type="submit"
                                >
                                    {t("members.permissions.grant_btn", { defaultValue: "Grant Permission" }).toUpperCase()}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            <ConfirmationDialog />
        </Modal>
    );
}

