                  c.class,
                  color === c.id ? "ring-4 ring-offset-2 ring-primary-500/30 dark:ring-offset-slate-900 scale-110" : "hover:scale-110"
                )}
                key={c.id}
                onClick={() => { setColor(c.id); }}
