      <div className="flex h-24 items-center justify-between px-6 border-b border-slate-50 dark:border-slate-800">
        {!isCollapsed && <div className="flex items-center gap-3"><div className="h-10 w-10 rounded-2xl bg-gradient-to-tr from-primary-600 to-indigo-500 shadow-lg shadow-primary-200 flex items-center justify-center text-white font-black text-xl tracking-tighter italic">L</div><span className="text-xl font-black tracking-tighter text-slate-800 dark:text-slate-200 uppercase italic">Lee<span className="text-primary-600 dark:text-primary-400">Attend</span></span></div>}
        <button className="lg:hidden p-3 min-w-[44px] min-h-[44px] flex items-center justify-center text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 bg-slate-50 dark:bg-slate-800 rounded-xl transition-colors" onClick={onClose}><X className="h-5 w-5" /></button>
      </div>
      <div className="flex-1 overflow-y-auto custom-scrollbar px-4 py-6 space-y-8">
        {filteredMenuItems.map((item) => (
          <div key={item.label}>
            {item.section ? (
              <div className="space-y-2">
                {!isCollapsed && (item.section !== undefined) && <button className="flex w-full items-center justify-between px-4 py-3 min-h-[44px] text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-[0.25em] hover:text-primary-600 dark:hover:text-primary-400 transition-colors group" data-testid={item.testId} onClick={() => { toggleSection(item.section as string); }}><div className="flex items-center gap-2">{!!item.sectionIcon && <item.sectionIcon className="h-3 w-3 opacity-50 group-hover:opacity-100" />}<span>{item.label}</span></div>{openSections[item.section] ? <ChevronDown className="h-3 w-3" /> : <ChevronRight className="h-3 w-3" />}</button>}
                {!!((item.section !== undefined && openSections[item.section]) || isCollapsed) && item.items !== undefined && (
                  <div className="space-y-1">
                    {item.items.map((subItem) => (
                      <Link className={cn("flex items-center gap-3 px-4 py-3 rounded-2xl transition-all duration-300 group", location.pathname === subItem.to ? "bg-primary-50 dark:bg-primary-950 text-primary-600 dark:text-primary-300 shadow-sm shadow-primary-100/50" : "text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800 hover:text-slate-700 dark:hover:text-slate-200")} data-testid={subItem.testId} key={subItem.to} to={subItem.to}>
                        <div className={cn("p-2 rounded-xl transition-colors", location.pathname === subItem.to ? "bg-white dark:bg-primary-900/30 shadow-sm" : "bg-slate-50 dark:bg-slate-800 group-hover:bg-white dark:group-hover:bg-slate-700")}>{!!subItem.icon && <subItem.icon className="h-4 w-4" />}</div>
                        {!isCollapsed && <span className="font-bold text-sm truncate">{subItem.label}</span>}
                      </Link>
                    ))}
                  </div>
                )}
              </div>
            ) : (
              <Link className={cn("flex items-center gap-3 px-4 py-3 rounded-2xl transition-all duration-300 group", (item.exact ? location.pathname === item.to : location.pathname.startsWith(((item.to || "/") as "/"))) ? "bg-primary-50 dark:bg-primary-950 text-primary-600 dark:text-primary-300 shadow-sm shadow-primary-100/50" : "text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800 hover:text-slate-700 dark:hover:text-slate-200")} data-testid={item.testId} to={((item.to || "/") as "/")}>
                <div className={cn("p-2 rounded-xl transition-colors", (item.exact ? location.pathname === item.to : location.pathname.startsWith(((item.to || "/") as "/"))) ? "bg-white dark:bg-primary-900/30 shadow-sm" : "bg-slate-50 dark:bg-slate-800 group-hover:bg-white dark:group-hover:bg-slate-700")}>{!!item.icon && <item.icon className="h-4 w-4" />}</div>
                {!isCollapsed && <span className="font-bold text-sm truncate">{item.label}</span>}
              </Link>
            )}
          </div>
        ))}
      </div>
      <div className="p-4 border-t border-slate-50 dark:border-slate-800">
        <button className="flex w-full items-center gap-3 px-4 py-4 text-slate-400 dark:text-slate-500 hover:text-rose-600 dark:hover:text-rose-400 hover:bg-rose-50 dark:hover:bg-rose-950/30 rounded-2xl transition-all duration-300 group" onClick={handleLogout}><div className="p-2 rounded-xl bg-slate-50 dark:bg-slate-800 group-hover:bg-white dark:group-hover:bg-slate-700 transition-colors"><LogOut className="h-4 w-4" /></div>{!isCollapsed && <span className="font-bold text-sm uppercase tracking-widest">{t("common.logout")}</span>}</button>
      </div>
    </div>
  );
}

