);


interface LeavePolicyManagerProps {
  wsId: string;
}

export function LeavePolicyManager({ wsId }: LeavePolicyManagerProps) {
  const { t } = useTranslation();
  const toast = useToast();
  const queryClient = useQueryClient();
  const [isCreating, setIsCreating] = useState(false);
  const [editingPolicy, setEditingPolicy] = useState<LeavePolicy | null>(null);
  const { confirm, ConfirmationDialog } = useConfirm();

  const { data: policies = [], isLoading } = useQuery({
    queryKey: ["leave-policies", wsId],
    queryFn: () => fetchLeavePolicies(wsId),
  });

  const { data: leaveTypes = [] } = useQuery({
    queryKey: ["leave-types", wsId],
    queryFn: () => fetchLeaveTypes(wsId),
  });

  const deleteMutation = useMutation({
    mutationFn: (id: string) => deleteLeavePolicy(wsId, id),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ["leave-policies"] });
      toast.success("Policy deleted successfully");
    },
  });

  const handleDelete = async (id: string) => {
    const ok = await confirm({
      title: t("common.warning", { defaultValue: "Warning" }),
      message: t("leave.policy.confirm_delete", { defaultValue: "Delete this policy?" }),
      variant: "danger"
    });
    if (ok) deleteMutation.mutate(id);
  };

  const mutation = useMutation({
    mutationFn: (data: Partial<LeavePolicy>) => 
      editingPolicy ? updateLeavePolicy(wsId, editingPolicy.id, data) : createLeavePolicy(wsId, data),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ["leave-policies"] });
      toast.success(editingPolicy ? "Policy updated" : "Policy created");
      setIsCreating(false);
      setEditingPolicy(null);
    },
    onError: (error: Error) => { toast.error(error.message); },
  });

  const _calculateAnnualEntitlement = (policy: LeavePolicy) => {
    const amount = policy.rule_config.accrual_amount;
    switch (policy.rule_config.frequency) {
      case "monthly": return amount * 12;
      case "quarterly": return amount * 4;
      case "yearly": return amount;
      default: return amount;
    }
  };

  if (isLoading) return <div className="p-12 text-center text-slate-400 dark:text-slate-500 animate-pulse font-bold uppercase tracking-widest text-[10px]">Loading policies...</div>;

  return (
    <div className="space-y-6">
      <div className="flex justify-end px-1">
         <button className="flex items-center gap-2 rounded-xl bg-primary-600 px-6 py-2.5 text-[10px] font-bold text-white uppercase tracking-widest hover:bg-primary-700 transition-all shadow-lg shadow-primary-100" data-testid="add-policy-btn" onClick={() => { setIsCreating(true); }}><Plus size={14} /> Create Policy</button>
      </div>

      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
        {policies.length === 0 ? (
          <div className="col-span-full py-20 bg-slate-50 dark:bg-slate-800 border-2 border-dashed border-slate-200 dark:border-slate-700 rounded-[2.5rem] flex flex-col items-center justify-center text-slate-400 dark:text-slate-500">
            <ShieldCheck className="mb-4 opacity-20" size={40} />
            <p className="text-xs font-bold uppercase tracking-widest">No policies defined yet</p>
          </div>
        ) : policies.map((policy) => {
          const type = leaveTypes.find(t => t.id === policy.leave_type_id);
          const bonusCount = policy.rule_config.seniority_bonus.length || 0;
          return (
            <div className="relative flex flex-col justify-between rounded-[2rem] border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 p-7 shadow-sm hover:shadow-md transition-all group" key={policy.id}>
              <div>
                <div className="flex items-center justify-between">
                  <span className="inline-flex items-center rounded-lg bg-primary-50 dark:bg-primary-950 px-2.5 py-1 text-[9px] font-bold text-primary-600 dark:text-primary-400 uppercase tracking-widest border border-primary-100 dark:border-primary-800 shadow-sm">
                    {type?.name ?? "Unknown"}
                  </span>
                  <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                    <button className="p-2 text-slate-400 dark:text-slate-500 hover:text-primary-600 dark:text-primary-400 bg-slate-50 dark:bg-slate-800 rounded-xl border border-slate-100 dark:border-slate-800" data-testid="edit-policy-btn" onClick={() => { setEditingPolicy(policy); }}><Pencil size={16} /></button>
                    <button className="p-2 text-slate-400 dark:text-slate-500 hover:text-rose-600 dark:text-rose-300 bg-slate-50 dark:bg-slate-800 rounded-xl border border-slate-100 dark:border-slate-800" data-testid="delete-policy-btn" onClick={() => handleDelete(policy.id)}><Trash2 size={16} /></button>
                  </div>
                </div>
                <h3 className="mt-5 text-lg font-bold text-slate-800 dark:text-slate-100 tracking-tight leading-none uppercase">{policy.name}</h3>

                <div className="mt-6 p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl border border-slate-100 dark:border-slate-800 space-y-3">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2 text-slate-400 dark:text-slate-500"><Clock size={14} /><span className="text-[10px] font-bold uppercase tracking-widest">Base Accrual</span></div>
                    <span className="text-[10px] font-bold text-slate-600 dark:text-slate-300 uppercase tracking-widest">{policy.rule_config.accrual_amount} / {policy.rule_config.frequency}</span>
                  </div>
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2 text-slate-400 dark:text-slate-500"><Milestone size={14} /><span className="text-[10px] font-bold uppercase tracking-widest">Bonus Steps</span></div>
                    <span className="text-[10px] font-bold text-primary-600 dark:text-primary-400 uppercase tracking-widest">{bonusCount} steps</span>
                  </div>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {!!(isCreating || editingPolicy) && (
        <PolicyModal
          isOpen={true}
          isSaving={mutation.isPending}
          leaveTypes={leaveTypes}
          onClose={() => { setIsCreating(false); setEditingPolicy(null); }}
          onSave={(data: Partial<LeavePolicy>) => { mutation.mutate(data); }}

          policy={editingPolicy}
        />
      )}
      <ConfirmationDialog />
    </div>
  );
}

interface PolicyModalProps {

  isOpen: boolean;
  isSaving: boolean;
  leaveTypes: { id: string; name: string }[];
  onClose: () => void;
  onSave: (data: Partial<LeavePolicy>) => void;
  policy: LeavePolicy | null;
}

function PolicyModal({ isOpen, onClose, leaveTypes, policy, onSave, isSaving }: PolicyModalProps) {
  const [formData, setFormData] = useState({
    name: policy?.name ?? "",
    description: policy?.description ?? "",
    leave_type_id: policy?.leave_type_id ?? (leaveTypes.length > 0 ? leaveTypes[0].id : ""),
    accrual_amount: policy?.rule_config.accrual_amount ?? 1.0,
    frequency: (policy?.rule_config.frequency ?? "monthly"),
    carry_over_limit: policy?.rule_config.carry_over_limit ?? 5,
    min_work_days_threshold: policy?.rule_config.min_work_days_threshold ?? 14
  });

  const [seniorityBonus, setSeniorityBonus] = useState<{ min_years: number; extra_days: number }[]>(
    policy?.rule_config.seniority_bonus ?? []
  );

  const addBonusMilestone = () => {
    setSeniorityBonus([...seniorityBonus, { min_years: 1, extra_days: 1.0 }]);
  };

  const removeBonusMilestone = (index: number) => {
    setSeniorityBonus(seniorityBonus.filter((_, index_) => index_ !== index));
  };

  const updateBonusMilestone = (index: number, field: "min_years" | "extra_days", value: number) => {
    const next = [...seniorityBonus];
    next[index] = { ...next[index], [field]: value };
    setSeniorityBonus(next);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      ...formData,
      rule_config: {
        frequency: formData.frequency,
        accrual_amount: formData.accrual_amount,
        accrual_timing: "start_of_period",
        carry_over_limit: formData.carry_over_limit,
        min_work_days_threshold: formData.min_work_days_threshold,
        seniority_bonus: seniorityBonus.sort((a, b) => a.min_years - b.min_years)
      }
    });
  };



  return (
    <Modal isOpen={isOpen} maxWidth="lg" onClose={onClose} title={policy ? "Edit Policy" : "Create Leave Policy"}>
      <form className="p-8 space-y-12 max-h-[85vh] overflow-y-auto custom-scrollbar" onSubmit={handleSubmit}>
        {/* IDENTITY */}
        <div className="space-y-8">
          <div className="flex items-center gap-3">
            { }
            <div className="h-8 w-8 rounded-xl bg-primary-50 dark:bg-primary-950 flex items-center justify-center text-primary-600 dark:text-primary-400"><LayoutGrid size={18} /></div>
            <h4 className="text-sm font-black text-slate-800 dark:text-slate-100 uppercase tracking-tighter">Identity</h4>
          </div>
          <div className="space-y-6 px-2">
            <FormRow label="Policy Name">
              <input className="w-full rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 p-3 text-sm font-bold outline-none focus:ring-4 focus:ring-primary-500/5 transition-all h-[54px]" id="policy-name" onChange={(e) => { setFormData({...formData, name: e.target.value}); }} placeholder="e.g. Standard Policy" required type="text" value={formData.name} />
            </FormRow>
            <FormRow label="Leave Type">
              <Combobox className="bg-white dark:bg-slate-900 border-slate-200 dark:border-slate-700 h-[54px] rounded-xl" onChange={(value) => { setFormData({...formData, leave_type_id: value}); }} options={leaveTypes.map((t) => ({ value: t.id, label: t.name }))} value={formData.leave_type_id} />
            </FormRow>
          </div>
        </div>

        {/* ACCRUAL RULES */}
        <div className="space-y-8">
          <div className="flex items-center gap-3">
            <div className="h-8 w-8 rounded-xl bg-emerald-50 dark:bg-emerald-950 flex items-center justify-center text-emerald-600 dark:text-emerald-300"><Clock size={18} /></div>
            <h4 className="text-sm font-black text-slate-800 dark:text-slate-100 uppercase tracking-tighter">Accrual Logic</h4>
          </div>
          <div className="bg-slate-50 dark:bg-slate-800/50 p-10 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 space-y-6">
            <FormRow info="Days to grant per period" label="Base Amount">
              <input className="w-full rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 p-3 text-sm font-bold font-mono text-center h-[54px]" id="annual-entitlement" onChange={(e) => { setFormData({...formData, accrual_amount: parseFloat(e.target.value)}); }} required step="0.1" type="number" value={formData.accrual_amount} />
            </FormRow>
            <FormRow label="Frequency">
              <select className="w-full rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 p-3 text-sm font-bold uppercase h-[54px]" onChange={(e) => { setFormData({...formData, frequency: e.target.value as "monthly" | "quarterly" | "yearly"}); }} value={formData.frequency}>
                <option value="monthly">Monthly</option>
                <option value="quarterly">Quarterly</option>
                <option value="yearly">Yearly</option>
              </select>
            </FormRow>
            <FormRow info="Threshold to receive accrual" label="Min Days Work">
              <input className="w-full rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 p-3 text-sm font-bold font-mono text-center text-amber-600 dark:text-amber-300 h-[54px]" onChange={(e) => { setFormData({...formData, min_work_days_threshold: parseFloat(e.target.value)}); }} required step="0.5" type="number" value={formData.min_work_days_threshold} />
            </FormRow>
            <FormRow info="Max days to carry over next year" label="Carry Limit">
              <input className="w-full rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 p-3 text-sm font-bold font-mono text-center h-[54px]" onChange={(e) => { setFormData({...formData, carry_over_limit: parseInt(e.target.value)}); }} required type="number" value={formData.carry_over_limit} />
            </FormRow>
          </div>
        </div>

        {/* SENIORITY BONUS */}
        <div className="space-y-8">
          <div className="flex justify-between items-center px-1">
            <div className="flex items-center gap-3">
              <div className="h-8 w-8 rounded-xl bg-indigo-50 dark:bg-indigo-950 flex items-center justify-center text-indigo-600"><Milestone size={18} /></div>
              <h4 className="text-sm font-black text-slate-800 dark:text-slate-100 uppercase tracking-tighter">Service Bonuses</h4>
            </div>
            <button className="flex items-center gap-2 rounded-xl bg-indigo-600 px-4 py-2 text-[10px] font-bold text-white uppercase tracking-widest hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100" onClick={addBonusMilestone} type="button"><Plus size={12} /> Add Row</button>
          </div>

          <div className="space-y-8 px-2">
            {seniorityBonus.length === 0 ? (
              <div className="py-10 text-center bg-white dark:bg-slate-900 border-2 border-dashed border-slate-100 dark:border-slate-800 rounded-[2rem] text-slate-400 dark:text-slate-500 italic text-xs">No bonus milestones defined.</div>
            ) : seniorityBonus.map((bonus, index) => (
              <div className="space-y-6 pt-8 first:pt-0 border-t first:border-0 border-slate-100 dark:border-slate-800 animate-in slide-in-from-right-2 duration-300 relative group/row" key={index}>
                <div className="absolute -left-4 top-10 font-black text-[8px] text-slate-300 dark:text-slate-600 uppercase vertical-text tracking-widest">Row {index + 1}</div>

                <FormRow label="After Years">
                  <input className="w-full rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 p-3 text-sm font-bold font-mono text-center h-[54px] focus:ring-4 focus:ring-indigo-500/5 transition-all outline-none" onChange={(e) => { updateBonusMilestone(index, "min_years", parseInt(e.target.value)); }} type="number" value={bonus.min_years} />
                </FormRow>

                <FormRow label="Bonus Amount">
                  <div className="flex gap-4 w-full max-w-md">
                    <input className="flex-1 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 p-3 text-sm font-bold font-mono text-center text-primary-600 dark:text-primary-400 h-[54px] focus:ring-4 focus:ring-primary-500/5 transition-all outline-none" onChange={(e) => { updateBonusMilestone(index, "extra_days", parseFloat(e.target.value)); }} step="0.5" type="number" value={bonus.extra_days} />
                    <button className="p-4 text-slate-300 dark:text-slate-600 hover:text-rose-600 dark:text-rose-300 hover:bg-rose-50 dark:bg-rose-950 rounded-2xl transition-all h-[54px] flex items-center justify-center border border-transparent hover:border-rose-100 dark:border-rose-800 shadow-sm hover:shadow-md" onClick={() => { removeBonusMilestone(index); }} type="button"><Trash2 size={18} /></button>
                  </div>
                </FormRow>
              </div>
            ))}
          </div>
        </div>

        {/* FOOTER */}
        <div className="flex justify-end gap-4 pt-8 border-t border-slate-100 dark:border-slate-800 sticky bottom-0 bg-white dark:bg-slate-900 pb-2">
          <button className="px-8 py-3 text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-[0.2em] hover:text-slate-600 dark:hover:text-slate-300 dark:text-slate-600" onClick={onClose} type="button">Cancel</button>
          <button className="rounded-2xl bg-primary-600 px-10 py-4 text-xs font-black text-white uppercase tracking-[0.2em] shadow-2xl shadow-primary-200 hover:bg-primary-700 active:scale-95 transition-all" data-testid="save-policy-btn" disabled={isSaving} type="submit">
            {isSaving ? "Saving..." : (policy ? "Update Policy" : "Create Policy")}
          </button>
        </div>
      </form>
    </Modal>
  );
}

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Wallet, AlertTriangle, Pencil, Plus, Trash2 } from "lucide-react";
import React, { useState } from "react";

import Modal from "@/components/ui/modal";
import { useToast } from "@/components/ui/toast";
import { fetchLeaveTypes, updateLeaveTypeConfig, createLeaveType, deleteLeaveType } from "@/lib/api/leaves";
import { LeaveType, LeaveTypeConfig } from "@/lib/api/types";
import { cn } from "@/lib/utils";

interface LeaveTypeManagerProps {
  wsId: string;
}

export function LeaveTypeManager({ wsId }: LeaveTypeManagerProps) {
  const toast = useToast();
  const queryClient = useQueryClient();

  const [editingType, setEditingType] = useState<LeaveType | null>(null);
  const [isAddingType, setIsAddingType] = useState(false);
  const [deletingType, setDeletingType] = useState<LeaveType | null>(null);

  const { data: leaveTypes = [], isLoading: isTypesLoading } = useQuery({
    queryKey: ["leave-types", wsId],
    queryFn: () => fetchLeaveTypes(wsId),
  });

  const createTypeMutation = useMutation({
    mutationFn: (data: { code: string; name: string; is_paid: boolean }) => createLeaveType(wsId, data),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ["leave-types"] });
      toast.success("Leave type created successfully");
      setIsAddingType(false);
    },
    onError: (error: Error) => { toast.error(error.message); },
  });

  const updateTypeMutation = useMutation({
    mutationFn: (data: { typeId: string; config: LeaveTypeConfig }) => updateLeaveTypeConfig(wsId, data.typeId, data.config),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ["leave-types"] });
      toast.success("Leave type updated successfully");
      setEditingType(null);
    },
    onError: () => { toast.error("Failed to update leave type"); },
  });

  const deleteTypeMutation = useMutation({
    mutationFn: (typeId: string) => deleteLeaveType(wsId, typeId),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ["leave-types"] });
      toast.success("Leave type deleted successfully");
      setDeletingType(null);
    },
    onError: (error: Error) => {
      toast.error(error.message);
      setDeletingType(null);
    },
  });

  if (isTypesLoading) return <div className="py-12 text-center text-slate-400 dark:text-slate-500 animate-pulse">Loading leave types...</div>;

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center px-1">
         <p className="text-xs font-medium text-slate-500 dark:text-slate-400 max-w-md italic">Define the categories of leave available in your organization (e.g., Annual Leave, Sick Leave).</p>
         <button className="flex items-center gap-2 rounded-xl bg-primary-600 px-6 py-2.5 text-[10px] font-bold text-white uppercase tracking-widest hover:bg-primary-700 transition-all shadow-lg shadow-primary-100" onClick={() => { setIsAddingType(true); }}><Plus size={14} /> Add Leave Type</button>
      </div>

      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
        {leaveTypes.map((type) => (
          <div className="relative flex flex-col justify-between rounded-[2rem] border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 p-7 shadow-sm hover:shadow-md transition-all group" key={type.id}>
            <div>
              <div className="flex items-center justify-between">
                <div className={cn("flex h-12 w-12 items-center justify-center rounded-2xl shadow-inner", type.is_paid ? "bg-emerald-50 dark:bg-emerald-950 text-emerald-600 dark:text-emerald-300 border border-emerald-100 dark:border-emerald-800" : "bg-amber-50 dark:bg-amber-950 text-amber-600 dark:text-amber-300 border border-amber-100 dark:border-amber-800")}>
                  {type.is_paid ? <Wallet size={20} /> : <AlertTriangle size={20} />}
                </div>
                <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                  <button className="p-2 text-slate-400 dark:text-slate-500 hover:text-primary-600 dark:text-primary-400 bg-slate-50 dark:bg-slate-800 rounded-xl border border-slate-100 dark:border-slate-800" onClick={() => { setEditingType(type); }}><Pencil size={16} /></button>
                  <button className="p-2 text-slate-400 dark:text-slate-500 hover:text-rose-600 dark:text-rose-300 bg-slate-50 dark:bg-slate-800 rounded-xl border border-slate-100 dark:border-slate-800" onClick={() => { setDeletingType(type); }}><Trash2 size={16} /></button>
                </div>
              </div>
              <h3 className="mt-5 text-lg font-bold text-slate-800 dark:text-slate-100 tracking-tight leading-none uppercase">{type.name}</h3>
              <p className="mt-1 text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest">Code: {type.code}</p>
              <div className="mt-4 flex gap-2">
                 <span className={cn("px-2.5 py-1 rounded-lg text-[9px] font-bold uppercase tracking-widest border", type.is_paid ? "bg-emerald-50 dark:bg-emerald-950 text-emerald-700 dark:text-emerald-300 border-emerald-100 dark:border-emerald-800" : "bg-amber-50 dark:bg-amber-950 text-amber-700 dark:text-amber-300 border-amber-100 dark:border-amber-800")}>{type.is_paid ? "Paid" : "Unpaid"}</span>
              </div>
            </div>
          </div>
        ))}
      </div>

      {!!isAddingType && <AddLeaveTypeModal isSaving={createTypeMutation.isPending} onClose={() => { setIsAddingType(false); }} onSave={(data) => { createTypeMutation.mutate(data); }} />}
      {!!editingType && <EditLeaveTypeModal isSaving={updateTypeMutation.isPending} leaveType={editingType} onClose={() => { setEditingType(null); }} onSave={(config: LeaveTypeConfig) => { updateTypeMutation.mutate({ typeId: editingType.id, config }); }} />}
      { }
      {!!deletingType && (
        <Modal isOpen={true} onClose={() => { setDeletingType(null); }} title="Confirm Delete">
          <div className="p-8">
            <p className="text-sm">Are you sure you want to delete "{deletingType.name}"?</p>
            <div className="mt-8 flex justify-end gap-3"><button className="px-6 py-2 text-xs font-bold text-slate-400 dark:text-slate-500" onClick={() => { setDeletingType(null); }}>Cancel</button><button className="rounded-xl bg-rose-600 px-6 py-2.5 text-[10px] font-bold text-white uppercase" onClick={() => { deleteTypeMutation.mutate(deletingType.id); }}>Delete</button></div>
          </div>
        </Modal>
      )}
    </div>
  );
}

interface AddLeaveTypeModalProps {
  isSaving: boolean;

  onClose: () => void;
  onSave: (data: { code: string; name: string; is_paid: boolean }) => void;
}

function AddLeaveTypeModal({ onClose, onSave, isSaving }: AddLeaveTypeModalProps) {
  const [formData, setFormData] = useState({ code: "", name: "", is_paid: true });
  return (

    <Modal isOpen={true} onClose={onClose} title="Add Leave Type">
      <form className="p-8 space-y-5" onSubmit={(e) => { e.preventDefault(); onSave(formData); }}>
        <input className="w-full rounded-2xl border p-4 text-sm" onChange={(e) => { setFormData({ ...formData, code: e.target.value.toUpperCase() }); }} placeholder="Code" required type="text" value={formData.code} />
        <input className="w-full rounded-2xl border p-4 text-sm" onChange={(e) => { setFormData({ ...formData, name: e.target.value }); }} placeholder="Name" required type="text" value={formData.name} />
        <div className="flex items-center gap-3"><input checked={formData.is_paid} id="paid-leave-input" onChange={(e) => { setFormData({ ...formData, is_paid: e.target.checked }); }} type="checkbox" /><label className="text-xs font-bold uppercase" htmlFor="paid-leave-input">Paid Leave?</label></div>
        <div className="flex justify-end gap-3 pt-6"><button onClick={onClose} type="button">Cancel</button><button className="rounded-xl bg-primary-600 px-8 py-3 text-xs font-bold text-white uppercase" disabled={isSaving} type="submit">Create</button></div>
      </form>
      { }
    </Modal>
  );
}

interface EditLeaveTypeModalProps {
  isSaving: boolean;
  leaveType: LeaveType;
  onClose: () => void;
  onSave: (config: LeaveTypeConfig) => void;
}

function EditLeaveTypeModal({ leaveType, onClose, onSave, isSaving }: EditLeaveTypeModalProps) {
  const [config, setConfig] = useState(leaveType.policy_config || { approval_required: true, requires_document: false, allow_negative_balance: false });
  return (
    <Modal isOpen={true} onClose={onClose} title={`Config: ${leaveType.name}`}>
      <form className="p-8 space-y-4" onSubmit={(e) => { e.preventDefault(); onSave(config); }}>
        <div className="flex items-center gap-3"><input checked={config.approval_required} id="approval-req-input" onChange={(e) => { setConfig({ ...config, approval_required: e.target.checked }); }} type="checkbox" /><label className="text-xs font-bold uppercase" htmlFor="approval-req-input">Approval Required</label></div>
        <div className="flex justify-end gap-3 pt-6"><button onClick={onClose} type="button">Cancel</button><button className="rounded-xl bg-primary-600 px-8 py-3 text-xs font-bold text-white uppercase" disabled={isSaving} type="submit">Save</button></div>
      </form>
    </Modal>
  );
}

import { Mail, UserPlus, Loader2 } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { useWorkspaceMembers, useWorkspaceRoles } from "@/hooks/use-workspace";

import Modal from "../ui/modal";

interface InviteMemberDialogProps {
  isOpen: boolean;
  onClose: () => void;
}

export default function InviteMemberDialog({
  isOpen,
  onClose,
}: InviteMemberDialogProps) {
  const { t } = useTranslation();
  const { addMember, isAdding } = useWorkspaceMembers();
  const { roles } = useWorkspaceRoles();
  const [email, setEmail] = useState("");
  const [roleId, setRoleId] = useState("");
  const [error, setError] = useState<string | null>(null);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault(); setError(null);
    try {
      const selectedRoleId = roleId || roles[0]?.id;
      if (!selectedRoleId) throw new Error("No role selected");
      await addMember({ email, roleId: selectedRoleId });
      setEmail(""); setRoleId(""); onClose();
    } catch {
      setError(t("members.invite.error_message"));
    }
  }

  return (
    <Modal icon={<UserPlus size={24} />} isOpen={isOpen} maxWidth="md" onClose={onClose} subtitle={t("members.invite.subtitle")} title={t("members.invite.title")}>
      <form className="space-y-8 pt-4 animate-in fade-in duration-500" onSubmit={handleSubmit}>
        {!!error && (
          <div className="p-4 text-[11px] font-bold uppercase tracking-widest text-rose-600 dark:text-rose-300 bg-rose-50 dark:bg-rose-950 border border-rose-100 dark:border-rose-800 rounded-2xl animate-in slide-in-from-top-2">
            {error}
          </div>
        )}

        <div className="space-y-3">
          <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ml-1">{t("members.invite.email_label")}</label>
          <div className="relative group">
            <div className="absolute inset-y-0 left-0 pl-5 flex items-center pointer-events-none text-slate-300 dark:text-slate-600 group-focus-within:text-primary-500 dark:group-focus-within:text-primary-400 transition-colors">
              <Mail size={18} />
            </div>
            <input className="w-full pl-14 pr-6 py-4 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-800 rounded-2xl focus:ring-4 focus:ring-primary-500/10 focus:bg-white dark:focus:bg-slate-900 outline-none transition-all font-bold text-sm tracking-tight" onChange={(e) => { setEmail(e.target.value); }} placeholder="dongnghiep@congty.com" required type="email" value={email} />
          </div>
        </div>

        <div className="space-y-3">
          <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ml-1">{t("members.invite.role_label")}</label>
          <select className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-800 rounded-2xl focus:ring-4 focus:ring-primary-500/10 focus:bg-white dark:focus:bg-slate-900 outline-none transition-all font-bold text-sm uppercase tracking-tight shadow-sm appearance-none cursor-pointer" onChange={(e) => { setRoleId(e.target.value); }} value={roleId || (roles[0]?.id ?? "")}>
            {roles.map(r => (
              <option key={r.id} value={r.id}>{r.name}</option>
            ))}
          </select>
        </div>

        <div className="pt-2">
          <button className="w-full flex items-center justify-center gap-3 bg-slate-900 text-white py-4 rounded-2xl font-bold text-xs uppercase tracking-widest hover:bg-primary-700 transition-all shadow-xl shadow-slate-200 dark:shadow-black/30 active:scale-95 disabled:opacity-50" data-testid="submit-invite-member-btn" disabled={isAdding} type="submit">
            {isAdding ? <Loader2 className="animate-spin" size={18} /> : <UserPlus size={18} />}
            {t("members.invite.submit_btn").toUpperCase()}
          </button>
        </div>
      </form>
    </Modal>
  );
}

import {

  Shield,
  Trash2,
  UserCog,
  KeyRound,
  Mail,
  User as UserIcon,
} from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import PermissionGate from "@/components/common/permission-gate";
import PermissionManagementModal from "@/components/features/settings/permission-management-modal";
import RoleManagementModal from "@/components/features/settings/role-management-modal";
import { useConfirm } from "@/hooks/use-confirm";
import { useWorkspaceMembers, useWorkspaceRoles } from "@/hooks/use-workspace";
import { WorkspaceRole } from "@/lib/api";
import { cn } from "@/lib/utils";

const roleColorMap: Record<string, string> = {
  teal: "bg-teal-50 dark:bg-teal-950 text-teal-600 dark:text-teal-300 border-teal-100",
  blue: "bg-blue-50 dark:bg-blue-950 text-blue-600 dark:text-blue-300 border-blue-100 dark:border-blue-800",
  slate: "bg-slate-50 dark:bg-slate-800 text-slate-500 dark:text-slate-400 border-slate-100 dark:border-slate-800",
  rose: "bg-rose-50 dark:bg-rose-950 text-rose-600 dark:text-rose-300 border-rose-100",
  indigo: "bg-indigo-50 dark:bg-indigo-950 text-indigo-600 dark:text-indigo-300 border-indigo-100",
  emerald: "bg-emerald-50 dark:bg-emerald-950 text-emerald-600 dark:text-emerald-300 border-emerald-100",
};

export default function MemberTable() {
  const { t } = useTranslation();
  const { confirm, ConfirmationDialog } = useConfirm();
  const { members, isLoading: membersLoading, removeMember } = useWorkspaceMembers();
  const { roles, isLoading: rolesLoading } = useWorkspaceRoles();
  const isLoading = membersLoading || rolesLoading;
  const [selectedUserId, setSelectedUserId] = useState<string | null>(null);
  const [isRoleModalOpen, setIsRoleModalOpen] = useState(false);
  const [isPermModalOpen, setIsPermModalOpen] = useState(false);

  const handleManageRoles = (userId: string) => { setSelectedUserId(userId); setIsRoleModalOpen(true); };
  const handleManagePermissions = (userId: string) => { setSelectedUserId(userId); setIsPermModalOpen(true); };
  const handleRemoveMember = async (userId: string) => { 
    const isConfirmed = await confirm({ title: t('common.warning', { defaultValue: 'Warning' }), message: t("members.table.confirm_remove"), variant: 'danger' });
    if (!isConfirmed) return; 

    try { await removeMember(userId); } catch (e: unknown) { console.error(e); } 
  };

  if (isLoading) return <div className="flex justify-center py-32"><div className="animate-spin rounded-full h-12 w-12 border-4 border-primary-600 border-t-transparent shadow-xl"></div></div>;

  return (
    <>
      <div className="bg-white dark:bg-slate-900 rounded-[3rem] border border-slate-100 dark:border-slate-800 shadow-sm overflow-hidden animate-in fade-in duration-700">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-slate-50 dark:bg-slate-800/50 border-b border-slate-100 dark:border-slate-800">
                <th className="px-10 py-6 text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-[0.25em]">{t("common.user")}</th>
                <th className="px-8 py-6 text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-[0.25em]">{t("common.role")}</th>
                <th className="px-10 py-6 border-b border-slate-100 dark:border-slate-800"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
              {members.map((member) => (
                <tr className="group hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-all" key={member.user_id}>
                  <td className="px-10 py-6">
                    <div className="flex items-center gap-5">
                      <div className="w-14 h-14 rounded-2xl bg-primary-50 dark:bg-primary-950 flex items-center justify-center text-primary-600 dark:text-primary-400 font-bold shadow-inner border border-primary-100 dark:border-primary-800/50 overflow-hidden group-hover:scale-110 transition-transform">
                        {member.avatar_url ? (
                          <img alt="Member avatar" className="w-full h-full object-cover" src={member.avatar_url} />
                        ) : (
                          <span className="text-lg uppercase">{(member.full_name ?? member.email).substring(0, 2)}</span>
                        )}
                      </div>
                      <div>
                        <div className="font-bold text-slate-700 dark:text-slate-200 text-sm tracking-tight uppercase leading-none mb-1.5">{member.full_name ?? t("common.no_name")}</div>
                        <div className="text-[10px] text-slate-500 dark:text-slate-400 font-mono font-bold flex items-center gap-2 opacity-70">
                          <Mail className="text-primary-400" size={12} /> {member.email}
                        </div>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-6">
                    <div className="flex flex-wrap items-center gap-2">
                      {(() => {
                        const primaryRole = roles.find(r => r.id === member.role_id);
                        if (!primaryRole) return <span className="text-xs text-slate-400">Loading...</span>;

                        const extraRoles = (member.extra_role_ids || [])
                          .map(id => roles.find(r => r.id === id))
                          .filter(Boolean) as WorkspaceRole[];

                        return (
                          <>
                            <span className={cn(
                              "inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-widest border shadow-sm",
                              roleColorMap[primaryRole.color] || roleColorMap.slate
                            )}>
                              {!!primaryRole.is_system && primaryRole.name.toLowerCase() === "owner" && <Shield size={10} />}
                              {primaryRole.name}
                            </span>

                            {extraRoles.length > 0 && (
                              <div className="relative group/badge">
                                <span className="inline-flex items-center justify-center min-w-[28px] h-[26px] px-1.5 rounded-full text-[10px] font-bold bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 cursor-help transition-colors group-hover/badge:bg-indigo-50 group-hover/badge:text-indigo-600 group-hover/badge:border-indigo-200 dark:group-hover/badge:bg-indigo-900/50 dark:group-hover/badge:border-indigo-800">
                                  +{extraRoles.length}
                                </span>

                                {/* Premium Popover for extra roles */}
                                <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 w-max max-w-[200px] opacity-0 invisible group-hover/badge:opacity-100 group-hover/badge:visible transition-all duration-300 ease-out translate-y-2 group-hover/badge:translate-y-0 z-10">
                                  <div className="p-3 bg-white/90 dark:bg-slate-900/90 backdrop-blur-xl rounded-2xl shadow-xl shadow-slate-200/50 dark:shadow-black/40 border border-slate-100 dark:border-slate-800 flex flex-col gap-2">
                                    <span className="text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest pb-1 border-b border-slate-100 dark:border-slate-800">Extra Roles</span>
                                    {extraRoles.map(er => (
                                      <span className={cn(
                                        "inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-[9px] font-bold uppercase tracking-widest border",
                                        roleColorMap[er.color] || roleColorMap.slate
                                      )} key={er.id}>
                                        {er.name}
                                      </span>
                                    ))}
                                  </div>
                                </div>
                              </div>
                            )}
                          </>
                        );
                      })()}
                    </div>
                  </td>
                  <td className="px-10 py-6 text-right">
                    <div className="flex items-center justify-end gap-3 opacity-0 group-hover:opacity-100 transition-all duration-300 translate-x-2 group-hover:translate-x-0">
                      <PermissionGate permission="members:roles:manage">
                        <button className="p-3 bg-white dark:bg-slate-900 text-slate-500 dark:text-slate-400 hover:text-primary-600 dark:text-primary-400 rounded-xl shadow-md border border-slate-100 dark:border-slate-800 transition-all active:scale-90" onClick={() => { handleManageRoles(member.user_id); }} title={t("members.table.manage_roles")}><UserCog size={20} /></button>
                      </PermissionGate>
                      <PermissionGate permission="members:roles:manage">
                        <button className="p-3 bg-white dark:bg-slate-900 text-slate-500 dark:text-slate-400 hover:text-amber-600 dark:text-amber-400 rounded-xl shadow-md border border-slate-100 dark:border-slate-800 transition-all active:scale-90" onClick={() => { handleManagePermissions(member.user_id); }} title={t("members.table.manage_permissions", { defaultValue: "Manage Permissions" })}><KeyRound size={20} /></button>
                      </PermissionGate>
                      {roles.find(r => r.id === member.role_id)?.name.toLowerCase() !== "owner" && (
                        <PermissionGate permission="members:remove">
                          <button className="p-3 bg-white dark:bg-slate-900 text-slate-500 dark:text-slate-400 hover:text-rose-600 dark:text-rose-300 rounded-xl shadow-md border border-slate-100 dark:border-slate-800 transition-all active:scale-90" onClick={() => handleRemoveMember(member.user_id)} title={t("members.table.remove_member")}><Trash2 size={20} /></button>
                        </PermissionGate>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>

          {members.length === 0 && (
            <div className="py-32 text-center bg-slate-50 dark:bg-slate-800/30 flex flex-col items-center">
              <UserIcon className="w-20 h-20 mb-6 text-slate-200 dark:text-slate-700" />
              <p className="text-[10px] font-bold text-slate-300 dark:text-slate-600 uppercase tracking-[0.25em]">{t("members.table.messages.no_members")}</p>
            </div>
          )}
        </div>
      </div>

      {!!selectedUserId && <>
          <RoleManagementModal isOpen={isRoleModalOpen} onClose={() => { setIsRoleModalOpen(false); }} userId={selectedUserId} />
          <PermissionManagementModal isOpen={isPermModalOpen} onClose={() => { setIsPermModalOpen(false); }} userId={selectedUserId} />
        </>}
      <ConfirmationDialog />
    </>
  );
}

import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { render, screen, fireEvent, waitFor } from "@testing-library/react";

import { describe, it, expect, vi, beforeEach } from "vitest";

import { ToastProvider } from "@/components/ui/toast";
import * as api from "@/lib/api/payroll";

import BonusPolicyManager from "../bonus-policy-manager";


// Mock API
vi.mock("@/lib/api/payroll", () => ({
  fetchIncentivePolicies: vi.fn(),
  createIncentivePolicy: vi.fn(),
  deleteIncentivePolicy: vi.fn(),
}));

// Mock i18next
vi.mock("react-i18next", () => ({
  useTranslation: () => ({
    t: (key: string) => key,
  }),
}));

const queryClient = new QueryClient({
  defaultOptions: { queries: { retry: false } },
});

const renderWithProviders = (ui: React.ReactNode) => {
  return render(
    <QueryClientProvider client={queryClient}>
      <ToastProvider>
        {ui}
      </ToastProvider>
    </QueryClientProvider>
  );
};

describe("BonusPolicyManager", () => {
  const mockWsId = "ws-123";

  beforeEach(() => {
    vi.clearAllMocks();

    vi.mocked(api.fetchIncentivePolicies).mockResolvedValue([]);
  });

