              </div>
            </div>
          ))
        )}
      </div>
    </Sheet>
  );
}

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { 
  Calendar, 
  ShieldCheck,
  Building2,
  User,
  Save,
  Clock
} from 'lucide-react';
import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';

import { EmployeeSearch } from '@/components/common/employee-search';
import { Combobox } from '@/components/ui/combobox';
import Modal from '@/components/ui/modal';
import { useToast } from '@/components/ui/toast';
import { fetchDepartments } from '@/lib/api/departments';
import { fetchOvertimePolicies, assignOvertimePolicy } from '@/lib/api/payroll';
import { cn } from '@/lib/utils';

interface AssignOvertimePolicyModalProps {
  initialId?: string;
  initialType?: 'employee' | 'department' | 'workspace';
  isOpen: boolean;
  onClose: () => void;
  wsId: string;
}

export default function AssignOvertimePolicyModal({ 
  wsId, 
  isOpen, 
  onClose,
  initialType = 'employee',
  initialId = ''
}: AssignOvertimePolicyModalProps) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const toast = useToast();

  const [selectedType, setSelectedType] = useState<'employee' | 'department' | 'workspace'>(initialType);
  const [targetId, setTargetId] = useState(initialId);
  const [policyId, setPolicyId] = useState('');
  const [effectiveFrom, setEffectiveFrom] = useState(new Date().toISOString().split('T')[0]);

  const { data: policies = [] } = useQuery({
    queryKey: ['overtime-policies', wsId],
    queryFn: () => fetchOvertimePolicies(wsId),
    enabled: isOpen
  });

  const { data: departments = [] } = useQuery({
    queryKey: ['departments', wsId],
    queryFn: () => fetchDepartments(wsId),
    enabled: isOpen && selectedType === 'department'
  });

  const assignMutation = useMutation({

    mutationFn: (data: Parameters<typeof assignOvertimePolicy>[1]) => assignOvertimePolicy(wsId, data),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ['overtime-policy-assignment'] });
      toast.success(t('common.success'));
      onClose();
    },

    onError: (error: Error) => {
      toast.error(error.message || t('common.error'));
    }
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedType !== 'workspace' && !targetId) {
      toast.error(t('common.error'));
      return;
    }
    if (!policyId) {
      toast.error(t('common.error'));
      return;
    }

    assignMutation.mutate({
      employee_id: selectedType === 'employee' ? targetId : undefined,
      department_id: selectedType === 'department' ? targetId : undefined,
      policy_id: policyId,
      effective_from: effectiveFrom
    });
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} title={t('payroll.assign_overtime_policy')}>
      <form className='space-y-6' onSubmit={handleSubmit}>
        <div className='grid grid-cols-1 gap-6'>
          <div className='space-y-2'>
            <label className='text-[10px] font-bold uppercase tracking-widest text-slate-500 dark:text-slate-400 ml-1'>{t('payroll.assignee_type')}</label>
            <div className='flex bg-slate-100 dark:bg-slate-700 p-1 rounded-2xl'>
              {[
                { id: 'employee', label: t('common.employee'), icon: <User size={12}/> },
                { id: 'department', label: t('common.department'), icon: <Building2 size={12}/> },
                { id: 'workspace', label: t('common.global'), icon: <ShieldCheck size={12}/> }
              ].map(opt => (
                <button
                  className={cn(
                    'flex-1 flex items-center justify-center gap-2 py-2 rounded-xl text-xs font-bold transition-all',
                    selectedType === opt.id ? 'bg-white dark:bg-slate-900 text-primary-600 dark:text-primary-400 shadow-sm' : 'text-slate-500 dark:text-slate-400'
                  )}
                  data-testid={`assignee-type-${opt.id}`}
                  key={opt.id}
                  onClick={() => {

                    setSelectedType(opt.id as 'employee' | 'department' | 'workspace');
                    setTargetId('');
                  }}
                  type='button'
                >
                  {opt.icon} {opt.label}
                </button>
              ))}
            </div>
          </div>

          {selectedType === 'employee' && (
            <div className='space-y-2'>
              <label className='text-[10px] font-bold uppercase tracking-widest text-slate-500 dark:text-slate-400 ml-1'>{t('common.select_employee')}</label>
              <EmployeeSearch 
                className='bg-slate-50 dark:bg-slate-800 border-slate-100 dark:border-slate-800 h-14'
                data-testid='assign-employee-search'
                onChange={(value) => { setTargetId(Array.isArray(value) ? value[0] : value); }}
                placeholder={t('common.select_employee')}
                value={targetId}
                workspaceId={wsId}
              />
            </div>
          )}

          {selectedType === 'department' && (
            <div className='space-y-2'>
              <label className='text-[10px] font-bold uppercase tracking-widest text-slate-500 dark:text-slate-400 ml-1'>{t('common.select_department')}</label>
              <Combobox 
                className='bg-slate-50 dark:bg-slate-800 border-slate-100 dark:border-slate-800 h-14'
                data-testid='assign-dept-select'
                id='dept-select'
                onChange={setTargetId}
                options={departments.map(d => ({
                  value: d.id,
                  label: d.name,
                  icon: <Building2 className='text-slate-500 dark:text-slate-400' size={14} />
                }))}
                placeholder={t('common.select_department')}
                value={targetId}
              />
            </div>
          )}

          <div className='space-y-2'>
            <label className='text-[10px] font-bold uppercase tracking-widest text-slate-500 dark:text-slate-400 ml-1'>{t('payroll.select_policy')}</label>
            <Combobox 
              className='bg-slate-50 dark:bg-slate-800 border-slate-100 dark:border-slate-800 h-14'
              data-testid='assign-policy-select'

              id='policy-select'
              onChange={setPolicyId}
              options={policies.map((p: { id: string; name: string }) => ({
                value: p.id,
                label: p.name,
                icon: <Clock className='text-primary-500' size={14} />
              }))}
              placeholder={t('payroll.select_policy_placeholder')}
              value={policyId}
            />
          </div>

          <div className='space-y-2'>
            <label className='text-[10px] font-bold uppercase tracking-widest text-slate-500 dark:text-slate-400 ml-1'>{t('payroll.effective_from')}</label>
            <div className='relative'>
              <Calendar className='absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 dark:text-slate-400' size={16} />
              <input 
                className='w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl pl-12 pr-4 py-3 text-sm outline-none focus:ring-2 focus:ring-primary-500 font-bold'
                data-testid='assign-effective-from'
                onChange={e => { setEffectiveFrom(e.target.value); }} 
                required
                type='date'
                value={effectiveFrom}
              />
            </div>
          </div>
        </div>

        <div className='flex justify-end gap-3 pt-4'>
          <button className='px-6 py-2 rounded-xl text-sm font-bold text-slate-500 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700 transition-all uppercase tracking-widest' onClick={onClose} type='button'>{t('common.cancel')}</button>
          <button
            className='flex items-center gap-2 bg-primary-600 text-white px-8 py-2 rounded-xl text-sm font-bold hover:bg-primary-700 transition-all shadow-xl shadow-primary-100 dark:shadow-black/30 active:scale-95 disabled:opacity-50 uppercase tracking-widest'
            data-testid='assign-policy-submit-btn'
            disabled={assignMutation.isPending}
            type='submit'
          >
            <Save size={16} />
            {t('payroll.assign_policy')}
          </button>
        </div>
      </form>
    </Modal>
  );
}

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { 
  Calculator, 
  CheckCircle2, 
  AlertCircle, 
  Loader2, 
  User,
} from "lucide-react";
import React, { useState } from "react";
import { useTranslation } from "react-i18next";

import { MonthYearPicker } from "@/components/common/month-year-picker";
import Modal from "@/components/ui/modal";
import { useToast } from "@/components/ui/toast";
import { calculateBatchPayslips } from "@/lib/api";
import { BatchCalculateResult } from "@/lib/api/types";
import { cn } from "@/lib/utils";

interface BatchCalculationModalProps {
  employeeIds: string[];
  employeeNames: Record<string, string>; // ID -> Name map
  isOpen: boolean;
  onClose: () => void;
  workspaceId: string;
}

export default function BatchCalculationModal({ 
  isOpen, 
  onClose, 
  workspaceId, 
  employeeIds,
  employeeNames
}: BatchCalculationModalProps) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const toast = useToast();

  const [calcYear, setCalcYear] = useState(() => {
    const d = new Date(); d.setMonth(d.getMonth() - 1);
    return d.getFullYear();
  });
  const [calcMonth, setCalcMonth] = useState(() => {
    const d = new Date(); d.setMonth(d.getMonth() - 1);
    return d.getMonth() + 1;
  });

  const [results, setResults] = useState<BatchCalculateResult[] | null>(null);

  const batchMutation = useMutation({
    mutationFn: (data: { year: number; month: number }) => 
      calculateBatchPayslips(workspaceId, { employee_ids: employeeIds, year: data.year, month: data.month }),
    onSuccess: (data) => {
      setResults(data.results);
      void queryClient.invalidateQueries({ queryKey: ["payslips"] });
      toast.success(t("payroll.messages.calculate_success"));
    },
  });

  const handleCalculate = () => { batchMutation.mutate({ year: calcYear, month: calcMonth }); };
  const resetAndClose = () => { setResults(null); batchMutation.reset(); onClose(); };

  const successCount = results?.filter(r => r.status === "success").length ?? 0;
  const errorCount = (results?.length ?? 0) - successCount;

  return (
    <Modal 
      icon={<Calculator size={24} />} 
      isOpen={isOpen} 
      maxWidth="lg" 
      onClose={batchMutation.isPending ? () => { /* empty */ } : resetAndClose} 
      subtitle={t("payroll.modal.subtitle")} 
      testId="batch-calc-modal"
      title={t("payroll.modal.title")}
    >
      <div className="space-y-8 pt-4 animate-in fade-in duration-500">
        {!results && !batchMutation.isPending && (
          <div className="space-y-8 animate-in fade-in duration-500">
            <div className="bg-primary-50 dark:bg-primary-950/50 p-8 rounded-[2.5rem] border border-primary-100 dark:border-primary-800/50 flex items-center gap-6 shadow-inner">
              <div className="w-16 h-16 bg-white dark:bg-slate-900 rounded-3xl flex items-center justify-center text-primary-600 dark:text-primary-400 shadow-sm border border-primary-100 dark:border-primary-800">
                <User size={32} />
              </div>
              <div>
                <p className="text-[10px] font-bold text-primary-400 uppercase tracking-[0.2em] mb-1 opacity-70">{t("common.employees")}</p>
                <p className="text-2xl font-bold text-slate-700 dark:text-slate-200 tracking-tight uppercase">
                  {employeeIds.length} {t("common.people")}
                </p>
              </div>
            </div>

            <div className="space-y-4">
              <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ml-1">{t("payroll.table.period")}</label>
              <div className="bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-800 p-2 rounded-[2rem] shadow-inner">
                <MonthYearPicker month={calcMonth} onChange={(m, y) => { setCalcMonth(m); setCalcYear(y); }} year={calcYear} />
              </div>
            </div>

            <div className="pt-4 grid grid-cols-2 gap-5">
              <button className="px-8 py-4 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl font-bold text-xs uppercase tracking-widest text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800 transition-all" onClick={onClose} type="button">{t("common.cancel")}</button>
              <button 
                className="px-8 py-4 bg-slate-900 text-white rounded-2xl font-bold text-xs uppercase tracking-widest hover:bg-primary-700 transition-all shadow-xl shadow-slate-200 dark:shadow-black/30 active:scale-95"
                data-testid="batch-calc-submit-btn" 
                onClick={handleCalculate}
              >
                {t("payroll.modal.submit")}
              </button>
            </div>
          </div>
        )}

        {!!batchMutation.isPending && (
          <div className="py-20 flex flex-col items-center justify-center text-center animate-in zoom-in-95 duration-500">
            <div className="w-24 h-24 bg-slate-50 dark:bg-slate-800 rounded-full flex items-center justify-center mb-8 relative shadow-inner">
              <Loader2 className="w-12 h-12 text-primary-600 dark:text-primary-400 animate-spin" />
              <div className="absolute inset-0 border-4 border-primary-100 dark:border-primary-800 border-t-transparent rounded-full opacity-50" />
            </div>
            <h3 className="text-2xl font-bold text-slate-700 dark:text-slate-200 mb-2 uppercase tracking-tight">{t("common.processing")}</h3>
            <p className="text-slate-500 dark:text-slate-400 text-sm font-medium max-w-xs leading-relaxed">
              Calculating payroll for {employeeIds.length} employees. This may take a moment...
            </p>
          </div>
        )}

        {!!results && (
          <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="grid grid-cols-2 gap-6">
              <div className="bg-emerald-50 dark:bg-emerald-950/50 p-6 rounded-[2rem] border border-emerald-100 dark:border-emerald-800 shadow-inner">
                <p className="text-[10px] font-bold text-emerald-600 dark:text-emerald-300 uppercase tracking-widest mb-1 opacity-70">Success</p>
                <p className="text-3xl font-bold text-emerald-700 dark:text-emerald-300 font-mono tracking-tighter">{successCount}</p>
              </div>
              <div className="bg-rose-50 dark:bg-rose-950/50 p-6 rounded-[2rem] border border-rose-100 dark:border-rose-800 shadow-inner">
                <p className="text-[10px] font-bold text-rose-600 dark:text-rose-300 uppercase tracking-widest mb-1 opacity-70">Errors</p>
                <p className="text-3xl font-bold text-rose-700 dark:text-rose-300 font-mono tracking-tighter">{errorCount}</p>
              </div>
            </div>

            <div className="max-h-72 overflow-y-auto space-y-3 pr-2 custom-scrollbar p-1">
              {results.map(res => (
                <div className="flex items-center justify-between p-4 bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-2xl hover:shadow-md transition-all group" key={res.employee_id}>
                  <div className="flex items-center gap-4">
                    <div className={cn("w-10 h-10 rounded-xl flex items-center justify-center shadow-inner border", res.status === 'success' ? "bg-emerald-50 dark:bg-emerald-950 text-emerald-600 dark:text-emerald-300 border-emerald-100 dark:border-emerald-800" : "bg-rose-50 dark:bg-rose-950 text-rose-600 dark:text-rose-300 border-rose-100 dark:border-rose-800")}>
                      {res.status === 'success' ? <CheckCircle2 size={18} /> : <AlertCircle size={18} />}
                    </div>
                    <div>
                      <p className="font-bold text-slate-700 dark:text-slate-200 text-sm tracking-tight uppercase">{employeeNames[res.employee_id] || "—"}</p>
                      {!!res.error_message && <p className="text-[10px] text-rose-500 font-bold uppercase tracking-widest mt-0.5 opacity-80">{res.error_message}</p>}
                    </div>
                  </div>
                  {res.status === 'success' && !!res.payslip && (
                    <span className="text-sm font-bold text-primary-600 dark:text-primary-400 font-mono tracking-tighter">
                      {new Intl.NumberFormat('vi-VN').format(parseFloat(res.payslip.net_pay_amount))}
                    </span>
                  )}
                </div>
              ))}
            </div>

            <div className="pt-4 border-t border-slate-50 dark:border-slate-800">
              <button className="w-full py-4 bg-slate-900 text-white rounded-2xl font-bold text-xs uppercase tracking-widest hover:bg-primary-700 transition-all shadow-xl shadow-slate-200 dark:shadow-black/30 active:scale-95" onClick={resetAndClose}>{t("common.close")}</button>
            </div>
          </div>
        )}
      </div>
    </Modal>
  );
}

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { 
  Sparkles, 
  Plus, 
  Trash2, 
  Save,
  CheckCircle2,
  AlertCircle,
  TrendingUp,
  Target,
  Clock
} from "lucide-react";
import React, { useState } from "react";
import { useTranslation } from "react-i18next";

import { useToast } from "@/components/ui/toast";
import { fetchIncentivePolicies, createIncentivePolicy, deleteIncentivePolicy } from "@/lib/api/payroll";
import { cn } from "@/lib/utils";

interface BonusPolicyManagerProps {
  wsId: string;
}

interface TierInput {
  [key: string]: string | number | null;
  max_late_early_count: string | number | null;
  max_sick_leave_days: string | number | null;
  max_total_leave_days: string | number | null;
  max_unpaid_leave_days: string | number | null;
  payout_amount: string | number;
  priority: number;
}

export default function BonusPolicyManager({ wsId }: BonusPolicyManagerProps) {

  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const toast = useToast();
  const [isCreating, setIsCreating] = useState(false);

  // Form State
  const [name, setName] = useState("");
  const [baseAmount, setBaseAmount] = useState(300000);
  const [payoutType, _setPayoutType] = useState<"fixed" | "percentage">("fixed");
  const [tiers, setTiers] = useState<TierInput[]>([
    { priority: 1, max_total_leave_days: 1, max_late_early_count: 2, max_unpaid_leave_days: 0.5, max_sick_leave_days: 1, payout_amount: 150000 },

    { priority: 2, max_total_leave_days: null, max_late_early_count: null, max_unpaid_leave_days: null, max_sick_leave_days: null, payout_amount: 0 }
  ]);

  const { data: policies = [], isLoading } = useQuery({
    queryKey: ["incentive-policies", wsId],
    queryFn: () => fetchIncentivePolicies(wsId),
  });

  const createMutation = useMutation({
    mutationFn: (data: Parameters<typeof createIncentivePolicy>[1]) => createIncentivePolicy(wsId, data),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ["incentive-policies"] });
      setIsCreating(false);
      toast.success(t("common.success"));
      // Reset form
      setName(""); setBaseAmount(300000);
    },
  });

  const deleteMutation = useMutation({
    mutationFn: (id: string) => deleteIncentivePolicy(wsId, id),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ["incentive-policies"] });
      toast.success(t("common.deleted"));
    },
  });

  const handleAddTier = () => {
    setTiers([...tiers, { 
      priority: tiers.length + 1, 
      max_total_leave_days: null, 
      max_late_early_count: null,
      max_unpaid_leave_days: null,

      max_sick_leave_days: null,
      payout_amount: 0 
    }]);
  };

  const handleRemoveTier = (index: number) => {
    setTiers(tiers.filter((_, index_) => index_ !== index));
  };

  const updateTier = (index: number, field: string, value: string | number | null) => {
    const next = [...tiers];
    next[index][field] = value === "" ? null : value;
    setTiers(next);
  };

  const handleSave = () => {
    if (!name) { toast.error(t("payroll.incentives.name_required")); return; }
    createMutation.mutate({
      name,
      base_amount: baseAmount,
      payout_type: payoutType,
      tiers: tiers.map(t => ({
        ...t,
        max_total_leave_days: t.max_total_leave_days !== null && t.max_total_leave_days !== "" ? Number(t.max_total_leave_days) : null,
        max_late_early_count: t.max_late_early_count !== null && t.max_late_early_count !== "" ? Number(t.max_late_early_count) : null,
        max_unpaid_leave_days: t.max_unpaid_leave_days !== null && t.max_unpaid_leave_days !== "" ? Number(t.max_unpaid_leave_days) : null,
        max_sick_leave_days: t.max_sick_leave_days !== null && t.max_sick_leave_days !== "" ? Number(t.max_sick_leave_days) : null,
        payout_amount: Number(t.payout_amount)
      })) as Parameters<typeof createIncentivePolicy>[1]["tiers"]
    });
  };

  return (
    <div className="space-y-10">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-bold text-slate-700 dark:text-slate-200 uppercase tracking-tight flex items-center gap-3">
            <Sparkles className="text-primary-600 dark:text-primary-400" size={24} />
            {t("payroll.incentives.title", { defaultValue: "INCENTIVE & BONUS POLICIES" })}
          </h2>
          <p className="text-sm text-slate-500 dark:text-slate-400 font-medium mt-1 uppercase tracking-widest text-[10px] opacity-70">Manage Diligence, Performance and Safety bonuses</p>
        </div>
        <button 
          className={cn(
            "flex items-center gap-2 px-6 py-3 rounded-2xl font-bold text-[10px] uppercase tracking-widest transition-all shadow-lg active:scale-95",
            isCreating ? "bg-slate-100 dark:bg-slate-700 text-slate-500 dark:text-slate-400" : "bg-primary-600 text-white hover:bg-primary-700"
          )}
          onClick={() => { setIsCreating(!isCreating); }}
        >
          {isCreating ? t("common.cancel") : <><Plus size={16} /> {t("payroll.incentives.add_btn", { defaultValue: "NEW POLICY" })}</>}
        </button>
      </div>

      {!!isCreating && (
        <div className="bg-slate-50 dark:bg-slate-800 rounded-[2.5rem] p-10 border border-slate-200 dark:border-slate-700 shadow-inner animate-in slide-in-from-top-4 duration-500 space-y-10">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="space-y-3">
              <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ml-1">{t("payroll.incentives.policy_name")}</label>
              <input 
                className="w-full bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl px-6 py-4 outline-none focus:ring-4 focus:ring-primary-500/10 focus:border-primary-300 transition-all font-bold text-sm shadow-sm" 
                onChange={e => { setName(e.target.value); }} 
                placeholder="e.g. Diligence Bonus"
                type="text"
                value={name}
              />
            </div>
            <div className="space-y-3">
              <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ml-1">{t("payroll.incentives.base_amount")}</label>
              <input 
                className="w-full bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl px-6 py-4 outline-none focus:ring-4 focus:ring-primary-500/10 focus:border-primary-300 transition-all font-bold text-sm shadow-sm font-mono" 
                onChange={e => { setBaseAmount(parseFloat(e.target.value)); }} 
                type="number"
                value={baseAmount}
              />
            </div>
          </div>

          <div className="space-y-6">
            <div className="flex items-center justify-between px-1">
              <h3 className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-[0.2em]">{t("payroll.incentives.tiers_config", { defaultValue: "EVALUATION TIERS" })}</h3>
              <button className="text-primary-600 dark:text-primary-400 hover:text-primary-700 dark:text-primary-300 font-bold text-[10px] uppercase tracking-widest flex items-center gap-1.5" onClick={handleAddTier}><Plus size={14} /> {t("common.add")}</button>
            </div>

            <div className="space-y-4">
              {tiers.map((tier, index) => (
                <div className="bg-white dark:bg-slate-900 p-8 rounded-3xl border border-slate-100 dark:border-slate-800 shadow-sm flex flex-col items-stretch gap-8 group relative" key={index}>
                  <div className="flex items-center justify-between">
                    <div className="w-10 h-10 rounded-xl bg-slate-100 dark:bg-slate-700 flex items-center justify-center font-bold text-slate-500 dark:text-slate-400 text-xs shadow-inner">#{index + 1}</div>
                    <button 

                      className="w-10 h-10 rounded-xl text-slate-300 dark:text-slate-600 hover:text-rose-500 hover:bg-rose-50 dark:bg-rose-950 transition-all flex items-center justify-center"
                      onClick={() => { handleRemoveTier(index); }}
                    >
                      <Trash2 size={18} />
                    </button>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-5 gap-6">
                    <div className="space-y-2">
                      <label className="text-[9px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest flex items-center gap-1.5" htmlFor={`late-${index}`}><Clock size={10} /> Max Late/Early</label>
                      { }
                      <input 
                        className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-800 rounded-xl px-4 py-2.5 outline-none focus:bg-white dark:focus:bg-slate-900 transition-all font-bold text-xs"
                        id={`late-${index}`} 
                        onChange={e => { updateTier(index, "max_late_early_count", e.target.value); }} 
                        placeholder="Any"
                        type="number"
                        value={tier.max_late_early_count ?? ""}
                      />
                    </div>
                    <div className="space-y-2">
                      { }
                      <label className="text-[9px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest flex items-center gap-1.5" htmlFor={`unpaid-${index}`}><AlertCircle size={10} /> Max Unpaid</label>
                      <input 
                        className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-800 rounded-xl px-4 py-2.5 outline-none focus:bg-white dark:focus:bg-slate-900 transition-all font-bold text-xs"
                        id={`unpaid-${index}`} 
                        onChange={e => { updateTier(index, "max_unpaid_leave_days", e.target.value); }} 
                        placeholder="Any"
                        type="number"
                        value={tier.max_unpaid_leave_days ?? ""}
                      />
                    </div>
                    { }
                    <div className="space-y-2">
                      <label className="text-[9px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest flex items-center gap-1.5" htmlFor={`sick-${index}`}><AlertCircle size={10} /> Max Sick</label>
                      <input 
                        className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-800 rounded-xl px-4 py-2.5 outline-none focus:bg-white dark:focus:bg-slate-900 transition-all font-bold text-xs"
                        id={`sick-${index}`} 
                        onChange={e => { updateTier(index, "max_sick_leave_days", e.target.value); }} 
                        placeholder="Any"
                        type="number"
                        value={tier.max_sick_leave_days ?? ""}
                      />
                      { }
                    </div>
                    <div className="space-y-2">
                      <label className="text-[9px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest flex items-center gap-1.5" htmlFor={`total-${index}`}><AlertCircle size={10} /> Max Total Days</label>
                      <input 
                        className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-800 rounded-xl px-4 py-2.5 outline-none focus:bg-white dark:focus:bg-slate-900 transition-all font-bold text-xs"
                        id={`total-${index}`} 
                        onChange={e => { updateTier(index, "max_total_leave_days", e.target.value); }} 
                        placeholder="Any"
                        type="number"
                        value={tier.max_total_leave_days ?? ""}
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[9px] font-bold text-primary-600 dark:text-primary-400 uppercase tracking-widest flex items-center gap-1.5" htmlFor={`payout-${index}`}><TrendingUp size={10} /> Payout</label>
                      <input 
                        className="w-full bg-primary-50 dark:bg-primary-950/50 border border-primary-100 dark:border-primary-800 rounded-xl px-4 py-2.5 outline-none focus:bg-white dark:focus:bg-slate-900 transition-all font-bold text-xs font-mono text-primary-700 dark:text-primary-300"
                        id={`payout-${index}`} 
                        onChange={e => { updateTier(index, "payout_amount", e.target.value); }} 
                        type="number"
                        value={tier.payout_amount}
                      />
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>

          <div className="flex justify-end pt-4">
            <button 
              className="bg-slate-900 hover:bg-primary-700 text-white px-10 py-4 rounded-2xl font-bold text-xs uppercase tracking-[0.2em] shadow-2xl active:scale-95 transition-all flex items-center gap-3 disabled:opacity-50"
              disabled={createMutation.isPending}
              onClick={handleSave}
            >
              {createMutation.isPending ? <Plus className="animate-spin" size={18} /> : <Save size={18} />}
              {t("common.save_settings")}
            </button>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 gap-6">
        {policies.map(policy => (
          <div className="bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-[2.5rem] p-8 shadow-sm hover:shadow-md transition-all group relative overflow-hidden" key={policy.id}>
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 relative z-10">
              <div className="flex items-center gap-6">
                <div className="w-16 h-16 rounded-[1.5rem] bg-primary-50 dark:bg-primary-950 flex items-center justify-center text-primary-600 dark:text-primary-400 shadow-inner border border-primary-100 dark:border-primary-800/50">
                  <Target size={32} />
                </div>
                <div>
                  <h3 className="text-xl font-bold text-slate-700 dark:text-slate-200 uppercase tracking-tight">{policy.name}</h3>
                  <div className="flex items-center gap-4 mt-1.5">
                    <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest bg-slate-50 dark:bg-slate-800 px-3 py-1 rounded-lg border border-slate-100 dark:border-slate-800">BASE: {new Intl.NumberFormat('vi-VN').format(policy.base_amount)} VND</span>
                    <span className="flex items-center gap-1.5 text-[10px] font-bold text-emerald-600 dark:text-emerald-300 uppercase tracking-widest">
                      <CheckCircle2 size={12} /> {t("common.active")}
                    </span>
                  </div>
                </div>
              </div>

              <div className="flex flex-wrap gap-3">
                {policy.tiers?.sort((a, b) => a.priority - b.priority).map((tier, _tidx) => (
                  <div className="bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-800 rounded-2xl px-5 py-4 flex flex-col items-center min-w-[140px] shadow-inner" key={tier.id}>
                    <span className="text-[8px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest mb-2">Tier {tier.priority}</span>
                    <span className="text-sm font-bold text-primary-600 dark:text-primary-400 font-mono tracking-tighter">
                      +{new Intl.NumberFormat('vi-VN').format(tier.payout_amount)}
                    </span>
                    <div className="mt-2 flex flex-col items-center gap-1 opacity-60">
                      {tier.max_late_early_count != null && <span className="text-[7px] font-bold text-slate-500 dark:text-slate-400 uppercase">Late &lt; {tier.max_late_early_count}</span>}
                      {tier.max_unpaid_leave_days != null && <span className="text-[7px] font-bold text-slate-500 dark:text-slate-400 uppercase">Unpaid &lt; {tier.max_unpaid_leave_days}d</span>}
                      {tier.max_sick_leave_days != null && <span className="text-[7px] font-bold text-slate-500 dark:text-slate-400 uppercase">Sick &lt; {tier.max_sick_leave_days}d</span>}
                      {tier.max_total_leave_days != null && <span className="text-[7px] font-bold text-slate-500 dark:text-slate-400 uppercase">Total &lt; {tier.max_total_leave_days}d</span>}
                      {tier.max_late_early_count == null && tier.max_unpaid_leave_days == null && tier.max_sick_leave_days == null && tier.max_total_leave_days == null && (
                        <span className="text-[7px] font-bold text-slate-500 dark:text-slate-400 uppercase italic">Default</span>
                      )}
                    </div>
                  </div>
                ))}
              </div>

              <button 
                className="p-4 rounded-2xl text-slate-300 dark:text-slate-600 hover:text-rose-500 hover:bg-rose-50 dark:bg-rose-950 transition-all active:scale-90"
                onClick={() => { deleteMutation.mutate(policy.id); }}
              >
                <Trash2 size={20} />
              </button>
            </div>
            <Sparkles className="absolute -right-8 -bottom-8 w-40 h-40 text-primary-500 opacity-[0.03] -rotate-12 group-hover:rotate-0 transition-transform duration-1000" />
          </div>
        ))}

        {!isLoading && policies.length === 0 && !isCreating && (
          <div className="py-24 text-center border-2 border-dashed border-slate-100 dark:border-slate-800 rounded-[3rem] bg-slate-50 dark:bg-slate-800/30 flex flex-col items-center">
            <div className="w-20 h-20 bg-white dark:bg-slate-900 rounded-full flex items-center justify-center shadow-sm mb-4 border border-slate-100 dark:border-slate-800"><Sparkles className="text-slate-200 dark:text-slate-700" size={32} /></div>
            <h3 className="text-lg font-bold text-slate-700 dark:text-slate-200">{t("payroll.incentives.no_policies", { defaultValue: "NO INCENTIVE POLICIES" })}</h3>
            <p className="text-slate-500 dark:text-slate-400 text-sm mt-1 uppercase font-bold tracking-widest opacity-50">Configure your first bonus rule to reward diligent staff</p>
          </div>
        )}
      </div>
    </div>
  );
}

