import { Shield, Plus, Users } from "lucide-react";
import React, { useState } from "react";
import { useTranslation } from "react-i18next";

import { PayrollRuleAssignment } from "@/lib/api/types";

import { AssignmentFormModal } from "./rule-assignment/assignment-form-modal";
import { AssignmentList } from "./rule-assignment/assignment-list";
import { useRuleAssignments } from "./rule-assignment/use-rule-assignments";

interface Props {
  calculationMethod?: "percentage" | "fixed" | "tiered";
  ruleId: string;
  wsId: string;
}

export default function RuleAssignmentManager({
  wsId,
  ruleId,
  calculationMethod,
}: Props) {
  const { t } = useTranslation();
  const [isModalOpen, setIsModalOpen] = useState(false);

  const {
    isLoading,
    departments,
    deptMap,
    grouped,
    totalCount,
    createMutation,
    deleteMutation,
  } = useRuleAssignments(wsId, ruleId);

  const handleCreate = (data: Partial<PayrollRuleAssignment>) => {
    createMutation.mutate(data, {
      onSuccess: () => { setIsModalOpen(false); },
    });
  };

  return (
    <div className="space-y-5 mt-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 rounded-xl bg-teal-50 dark:bg-teal-950/40 text-teal-600 dark:text-teal-400 flex items-center justify-center shadow-sm border border-teal-100 dark:border-teal-800">
            <Shield size={16} />
          </div>
          <div>
            <h3 className="font-bold text-sm uppercase tracking-widest text-slate-700 dark:text-slate-200 leading-none">
              {t("payroll_rules.rule_assignments", "Rule Assignments")}
            </h3>
            <p className="text-[10px] text-slate-500 dark:text-slate-400 uppercase tracking-widest mt-1 opacity-70">
              {totalCount} active{" "}
              {totalCount === 1 ? "assignment" : "assignments"} across all scopes
            </p>
          </div>
        </div>
        <button
          className="flex items-center gap-2 bg-teal-600 hover:bg-teal-700 text-white px-5 py-2.5 rounded-xl font-bold text-[10px] uppercase tracking-widest transition-all shadow-lg shadow-teal-100 dark:shadow-black/30 active:scale-95"
          onClick={() => { setIsModalOpen(true); }}
        >
          <Plus size={14} /> {t("common.assign", "Assign")}
        </button>
      </div>

      {/* Loading state */}
      {!!isLoading && (
        <div className="p-12 flex justify-center">
          <div className="w-8 h-8 border-[3px] border-teal-600 border-t-transparent rounded-full animate-spin" />
        </div>
      )}

      {/* Empty state */}
      {!isLoading && totalCount === 0 && (
        <div className="p-12 bg-slate-50 dark:bg-slate-800/30 rounded-2xl border-2 border-dashed border-slate-100 dark:border-slate-800 flex flex-col items-center gap-3">
          <div className="w-14 h-14 bg-white dark:bg-slate-900 rounded-2xl flex items-center justify-center shadow-sm border border-slate-100 dark:border-slate-800">
            <Users className="text-slate-200 dark:text-slate-700" size={24} />
          </div>
          <p className="text-[10px] font-bold text-slate-300 dark:text-slate-600 uppercase tracking-widest">
            {t(
              "payroll.no_assignments_yet",
              "No assignments yet — click 'Assign' to get started"
            )}
          </p>
        </div>
      )}

      {/* Assignment cards by scope */}
      {!isLoading && totalCount > 0 && (
        <AssignmentList
          deptMap={deptMap}
          grouped={grouped}
          isDeleting={deleteMutation.isPending}
          onDelete={(id) => { deleteMutation.mutate(id); }}
        />
      )}

      {/* Create Assignment Modal */}
      <AssignmentFormModal
        calculationMethod={calculationMethod}
        departments={departments}
        isOpen={isModalOpen}
        isSubmitting={createMutation.isPending}
        onClose={() => { setIsModalOpen(false); }}
        onSubmit={handleCreate}
        wsId={wsId}
      />
    </div>
  );
}

import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { renderHook, waitFor } from "@testing-library/react";

import { describe, it, expect, vi, beforeEach } from "vitest";

import * as departmentsApi from "@/lib/api/departments";
import * as payrollApi from "@/lib/api/payroll";

import { useRuleAssignments } from "../use-rule-assignments";

// --- Mocks ---
vi.mock("@/lib/api/payroll");
vi.mock("@/lib/api/departments");

vi.mock("react-i18next", () => ({
  useTranslation: () => ({
    t: (key: string, fallback?: string) => fallback ?? key,
  }),
}));

const mockToastSuccess = vi.fn();
const mockToastError = vi.fn();
vi.mock("@/components/ui/toast", () => ({
  useToast: () => ({
    success: mockToastSuccess,
    error: mockToastError,
  }),
}));

describe("useRuleAssignments", () => {
  let queryClient: QueryClient;

  beforeEach(() => {
    queryClient = new QueryClient({
      defaultOptions: { queries: { retry: false } },
    });
    vi.clearAllMocks();
  });

  const getWrapper = () => {
    return ({ children }: { children: React.ReactNode }) => (
      <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>
    );
  };

  it("fetches and groups assignments correctly", async () => {
    vi.mocked(payrollApi.fetchPayrollRuleAssignments).mockResolvedValueOnce([
      {
        id: "a-1",
        workspace_id: "ws-1",
        rule_definition_id: "rule-1",
        assignee_type: "workspace",
        assignee_id: null,
        effective_from: "2026-01-01",
        created_at: "2026-01-01T00:00:00Z",
      },
      {
        id: "a-2",
        workspace_id: "ws-1",
        rule_definition_id: "rule-1",
        assignee_type: "department",
        assignee_id: "dept-1",
        effective_from: "2026-02-01",
        override_config: { rate: 10, base: "gross" },
        created_at: "2026-02-01T00:00:00Z",
      },
    ]);

    vi.mocked(departmentsApi.fetchDepartments).mockResolvedValueOnce([
      {
        id: "dept-1",
        workspace_id: "ws-1",
        name: "Engineering",
        active_employee_count: 5,
        created_at: "",
        updated_at: "",
      },
    ]);

    const { result } = renderHook(() => useRuleAssignments("ws-1", "rule-1"), {
      wrapper: getWrapper(),
    });

    await waitFor(() => {
      expect(result.current.isLoading).toBe(false);
    });

    expect(result.current.assignments).toHaveLength(2);
    expect(result.current.totalCount).toBe(2);
    expect(result.current.deptMap["dept-1"].name).toBe("Engineering");

    // Check grouping
    expect(result.current.grouped.workspace).toHaveLength(1);
    expect(result.current.grouped.department).toHaveLength(1);
    expect(result.current.grouped.employee).toHaveLength(0);
  });

  it("handles successful create mutation", async () => {
    vi.mocked(payrollApi.fetchPayrollRuleAssignments).mockResolvedValueOnce([]);
    vi.mocked(departmentsApi.fetchDepartments).mockResolvedValueOnce([]);
    vi.mocked(payrollApi.createPayrollRuleAssignment).mockResolvedValueOnce(
      {} as never
    );

    const { result } = renderHook(() => useRuleAssignments("ws-1", "rule-1"), {
      wrapper: getWrapper(),
    });

    result.current.createMutation.mutate({
      assignee_type: "workspace",
    });

    await waitFor(() => {
      expect(result.current.createMutation.isSuccess).toBe(true);
    });

    expect(payrollApi.createPayrollRuleAssignment).toHaveBeenCalledWith(
      "ws-1",
      "rule-1",
      { assignee_type: "workspace" }
    );
    expect(mockToastSuccess).toHaveBeenCalledWith("Success");
  });

  it("handles failed delete mutation", async () => {
    vi.mocked(payrollApi.fetchPayrollRuleAssignments).mockResolvedValueOnce([]);
    vi.mocked(departmentsApi.fetchDepartments).mockResolvedValueOnce([]);
    vi.mocked(payrollApi.deletePayrollRuleAssignment).mockRejectedValueOnce(
      new Error("API Error")
    );

    const { result } = renderHook(() => useRuleAssignments("ws-1", "rule-1"), {
      wrapper: getWrapper(),
    });

    result.current.deleteMutation.mutate("a-1");

    await waitFor(() => {
      expect(result.current.deleteMutation.isError).toBe(true);
    });

    expect(payrollApi.deletePayrollRuleAssignment).toHaveBeenCalledWith(
      "ws-1",
      "rule-1",
      "a-1"
    );
    expect(mockToastError).toHaveBeenCalledWith("API Error");
  });
});

import { Users, Building, Globe, Clock, Sliders, Shield } from "lucide-react";
import React, { useState } from "react";
import { useTranslation } from "react-i18next";

import { EmployeeSearch } from "@/components/common/employee-search";
import Modal from "@/components/ui/modal";
import { Department, PayrollRuleAssignment } from "@/lib/api/types";
import { cn } from "@/lib/utils";

const SCOPE_ICONS = {
  workspace: Globe,
  department: Building,
  employee: Users,
} as const;

const SCOPE_COLORS = {
  workspace: {
    bg: "bg-amber-50 dark:bg-amber-950/40",
    text: "text-amber-600 dark:text-amber-400",
    border: "border-amber-100 dark:border-amber-800",
  },
  department: {
    bg: "bg-sky-50 dark:bg-sky-950/40",
    text: "text-sky-600 dark:text-sky-400",
    border: "border-sky-100 dark:border-sky-800",
  },
  employee: {
    bg: "bg-teal-50 dark:bg-teal-950/40",
    text: "text-teal-600 dark:text-teal-400",
    border: "border-teal-100 dark:border-teal-800",
  },
} as const;

interface Props {
  calculationMethod?: "percentage" | "fixed" | "tiered";
  departments?: Department[];
  isOpen: boolean;
  isSubmitting: boolean;
  onClose: () => void;
  onSubmit: (data: Partial<PayrollRuleAssignment>) => void;
  wsId: string;
}

export function AssignmentFormModal({
  isOpen,
  onClose,
  onSubmit,
  isSubmitting,
  wsId,
  departments,
  calculationMethod,
}: Props) {
  const { t } = useTranslation();

  const [assigneeType, setAssigneeType] = useState<
    "workspace" | "department" | "employee"
  >("employee");
  const [assigneeId, setAssigneeId] = useState<string>("");
  const [effectiveFrom, setEffectiveFrom] = useState(
    () => new Date().toISOString().split("T")[0]
  );
  const [effectiveTo, setEffectiveTo] = useState<string>("");
  const [hasOverride, setHasOverride] = useState(false);
  const [overrideRate, setOverrideRate] = useState<string>("");
  const [overrideAmount, setOverrideAmount] = useState<string>("");
  const [overrideBase, setOverrideBase] = useState<string>("gross");

  const handleClose = () => {
    onClose();
    setAssigneeType("employee");
    setAssigneeId("");
    setEffectiveFrom(new Date().toISOString().split("T")[0]);
    setEffectiveTo("");
    setHasOverride(false);
    setOverrideRate("");
    setOverrideAmount("");
    setOverrideBase("gross");
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    let overrideConfig: Record<string, unknown> | undefined;
    if (hasOverride) {
      if (calculationMethod === "percentage" && overrideRate) {
        overrideConfig = { rate: parseFloat(overrideRate), base: overrideBase };
      } else if (calculationMethod === "fixed" && overrideAmount) {
        overrideConfig = { amount: parseFloat(overrideAmount) };
      }
    }
    onSubmit({
      assignee_type: assigneeType,
      assignee_id: assigneeType === "workspace" ? undefined : assigneeId || undefined,
      effective_from: effectiveFrom,
      effective_to: effectiveTo || undefined,
      override_config: overrideConfig,
    });
  };

  return (
    <Modal
      icon={<Shield size={24} />}
      isOpen={isOpen}
      maxWidth="lg"
      onClose={handleClose}
      subtitle={t(
        "payroll.assign_rule_desc",
        "Define who this rule applies to and when"
      )}
      title={t("payroll.assign_rule", "Assign Rule")}
    >
      <form
        className="space-y-8 pt-2 animate-in fade-in duration-300"
        onSubmit={handleSubmit}
      >
        {/* Scope selector */}
        <div className="space-y-3">
          <div className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ml-1 mb-1">
            {t("payroll.assignment_scope", "Assignment Scope")}
          </div>
          <div className="grid grid-cols-3 gap-3">
            {(["employee", "department", "workspace"] as const).map((scope) => {
              const Icon = SCOPE_ICONS[scope];
              const colors = SCOPE_COLORS[scope];
              const isActive = assigneeType === scope;
              return (
                <button
                  className={cn(
                    "flex flex-col items-center gap-2.5 p-5 rounded-2xl border-2 transition-all active:scale-[0.97]",
                    isActive
                      ? `${colors.bg} ${colors.border} shadow-lg`
                      : "bg-slate-50 dark:bg-slate-800/50 border-transparent hover:border-slate-200 dark:hover:border-slate-700 hover:bg-white dark:hover:bg-slate-900"
                  )}
                  key={scope}
                  onClick={() => {
                    setAssigneeType(scope);
                    setAssigneeId("");
                  }}
                  type="button"
                >
                  <Icon
                    className={
                      isActive ? colors.text : "text-slate-400 dark:text-slate-500"
                    }
                    size={22}
                  />
                  <span
                    className={cn(
                      "text-[10px] font-bold uppercase tracking-widest",
                      isActive
                        ? "text-slate-700 dark:text-slate-200"
                        : "text-slate-500 dark:text-slate-400"
                    )}
                  >
                    {t(`payroll.scope_${scope}`, scope)}
                  </span>
                </button>
              );
            })}
          </div>
        </div>

        {/* Assignee picker */}
        {assigneeType === "employee" && (
          <div className="space-y-3">
            <div className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ml-1 mb-1">
              {t("payroll.select_employee", "Select Employee")}
            </div>
            <EmployeeSearch
              onChange={(value) => { setAssigneeId(Array.isArray(value) ? value[0] : value); }}
              placeholder={t("payroll.search_employees", "Search employees…")}
              value={assigneeId}
              workspaceId={wsId}
            />
          </div>
        )}

        {assigneeType === "department" && (
          <div className="space-y-3">
            <label
              className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ml-1"
              htmlFor="dept-select"
            >
              {t("payroll.select_department", "Select Department")}
            </label>
            <select
              className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 font-bold text-sm text-slate-700 dark:text-slate-200 focus:ring-4 focus:ring-sky-500/10 focus:bg-white dark:focus:bg-slate-900 outline-none transition-all uppercase tracking-tight shadow-sm"
              id="dept-select"
              onChange={(e) => { setAssigneeId(e.target.value); }}
              required
              value={assigneeId}
            >
              <option value="">
                {t(
                  "payroll.select_department_placeholder",
                  "— Select department —"
                )}
              </option>
              {departments?.map((d) => (
                <option key={d.id} value={d.id}>
                  {d.name}
                </option>
              ))}
            </select>
          </div>
        )}

        {assigneeType === "workspace" && (
          <div className="bg-amber-50 dark:bg-amber-950/30 border border-amber-100 dark:border-amber-800 rounded-2xl p-5 flex items-center gap-4">
            <Globe
              className="text-amber-600 dark:text-amber-400 shrink-0"
              size={20}
            />
            <p className="text-xs font-bold text-amber-800 dark:text-amber-200 uppercase tracking-tight">
              {t(
                "payroll.workspace_scope_info",
                "This rule will apply to all employees in the workspace"
              )}
            </p>
          </div>
        )}

        {/* Date range */}
        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-3">
            <label
              className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ml-1 flex items-center gap-1.5"
              htmlFor="effective-from"
            >
              <Clock size={10} /> {t("payroll.effective_from", "Effective From")}
            </label>
            <input
              className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 font-bold text-sm text-slate-700 dark:text-slate-200 focus:ring-4 focus:ring-primary-500/10 focus:bg-white dark:focus:bg-slate-900 outline-none transition-all shadow-sm"
              id="effective-from"
              onChange={(e) => { setEffectiveFrom(e.target.value); }}
              required
              type="date"
              value={effectiveFrom}
            />
          </div>
          <div className="space-y-3">
            <label
              className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ml-1 flex items-center gap-1.5"
              htmlFor="effective-to"
            >
              <Clock size={10} /> {t("payroll.effective_to", "Effective To")}
              <span className="opacity-40 normal-case tracking-normal">
                ({t("common.optional", "optional")})
              </span>
            </label>
            <input
              className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 font-bold text-sm text-slate-700 dark:text-slate-200 focus:ring-4 focus:ring-primary-500/10 focus:bg-white dark:focus:bg-slate-900 outline-none transition-all shadow-sm"
              id="effective-to"
              onChange={(e) => { setEffectiveTo(e.target.value); }}
              type="date"
              value={effectiveTo}
            />
          </div>
        </div>

        {/* Override config toggle */}
        {(calculationMethod === "percentage" ||
          calculationMethod === "fixed") && (
          <div className="space-y-4">
            {/* eslint-disable-next-line jsx-a11y/label-has-associated-control */}
            <label
              className={cn(
                "flex items-center gap-4 p-5 rounded-2xl cursor-pointer transition-all border-2 active:scale-[0.98]",
                hasOverride
                  ? "bg-orange-50 dark:bg-orange-950/30 border-orange-100 dark:border-orange-800 shadow-lg"
                  : "bg-slate-50 dark:bg-slate-800/50 border-transparent hover:border-slate-200 dark:hover:border-slate-700"
              )}
              htmlFor="override-config"
            >
              <input
                checked={hasOverride}
                className="w-5 h-5 rounded-lg text-orange-600 focus:ring-orange-500 border-slate-300 dark:border-slate-600 cursor-pointer"
                id="override-config"
                onChange={(e) => { setHasOverride(e.target.checked); }}
                type="checkbox"
              />
              <div>
                <p className="font-bold text-sm text-slate-700 dark:text-slate-200 uppercase tracking-tight flex items-center gap-2">
                  <Sliders className="opacity-50" size={14} />{" "}
                  {t("payroll.override_config", "Override Default Config")}
                </p>
                <p className="text-[10px] text-slate-500 dark:text-slate-400 uppercase tracking-widest mt-1 opacity-70">
                  {t(
                    "payroll.override_config_desc",
                    "Apply a different rate or amount for this specific assignment"
                  )}
                </p>
              </div>
            </label>

            {!!hasOverride && (
              <div className="bg-orange-50 dark:bg-orange-950/20 rounded-2xl p-5 border border-orange-100 dark:border-orange-800 space-y-4 animate-in slide-in-from-top-2 duration-200">
                {calculationMethod === "percentage" && (
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <label
                        className="text-[10px] font-bold text-orange-700 dark:text-orange-300 uppercase tracking-widest"
                        htmlFor="override-rate"
                      >
                        {t("payroll.override_rate", "Override Rate (%)")}
                      </label>
                      <input
                        className="w-full bg-white dark:bg-slate-900 border border-orange-200 dark:border-orange-800 rounded-xl px-4 py-3 font-bold text-sm text-slate-700 dark:text-slate-200 focus:ring-2 focus:ring-orange-500/20 outline-none"
                        id="override-rate"
                        onChange={(e) => { setOverrideRate(e.target.value); }}
                        placeholder="e.g. 10.5"
                        step="0.01"
                        type="number"
                        value={overrideRate}
                      />
                    </div>
                    <div className="space-y-2">
                      <label
                        className="text-[10px] font-bold text-orange-700 dark:text-orange-300 uppercase tracking-widest"
                        htmlFor="override-base"
                      >
                        {t("payroll.override_base", "Override Base")}
                      </label>
                      <select
                        className="w-full bg-white dark:bg-slate-900 border border-orange-200 dark:border-orange-800 rounded-xl px-4 py-3 font-bold text-sm text-slate-700 dark:text-slate-200 focus:ring-2 focus:ring-orange-500/20 outline-none uppercase tracking-tight"
                        id="override-base"
                        onChange={(e) => { setOverrideBase(e.target.value); }}
                        value={overrideBase}
                      >
                        <option value="gross">
                          {t("payroll.base_gross", "Gross Salary")}
                        </option>
                        <option value="gross_salary">
                          {t("payroll.base_gross_alt", "Gross Salary (alt)")}
                        </option>
                        <option value="taxable_income">
                          {t("payroll.base_taxable", "Taxable Income")}
                        </option>
                      </select>
                    </div>
                  </div>
                )}
                {calculationMethod === "fixed" && (
                  <div className="space-y-2">
                    <label
                      className="text-[10px] font-bold text-orange-700 dark:text-orange-300 uppercase tracking-widest"
                      htmlFor="override-amount"
                    >
                      {t("payroll.override_amount", "Override Amount (₫)")}
                    </label>
                    <input
                      className="w-full bg-white dark:bg-slate-900 border border-orange-200 dark:border-orange-800 rounded-xl px-4 py-3 font-bold text-sm text-slate-700 dark:text-slate-200 focus:ring-2 focus:ring-orange-500/20 outline-none"
                      id="override-amount"
                      onChange={(e) => { setOverrideAmount(e.target.value); }}
                      placeholder="e.g. 500000"
                      type="number"
                      value={overrideAmount}
                    />
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {/* Actions */}
        <div className="flex gap-4 pt-2 border-t border-slate-50 dark:border-slate-800">
          <button
            className="flex-1 px-6 py-3.5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 rounded-2xl font-bold text-xs uppercase tracking-widest hover:bg-slate-50 dark:hover:bg-slate-800 transition-all active:scale-95"
            onClick={handleClose}
            type="button"
          >
            {t("common.cancel", "Cancel")}
          </button>
          <button
            className="flex-[1.5] bg-teal-600 text-white rounded-2xl font-bold text-xs uppercase tracking-widest hover:bg-teal-700 transition-all shadow-xl shadow-teal-100 dark:shadow-black/30 active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed py-3.5"
            disabled={
              isSubmitting ||
              (assigneeType !== "workspace" && !assigneeId)
            }
            type="submit"
          >
            {isSubmitting
              ? t("common.saving", "Saving") + "…"
              : t("payroll.assign_rule", "Assign Rule")}
          </button>
        </div>
      </form>
    </Modal>
  );
}

import { Users, Building, Globe, Trash2, Calendar, Sliders } from "lucide-react";
import React, { useState } from "react";
import { useTranslation } from "react-i18next";

import { PayrollRuleAssignment, Department } from "@/lib/api/types";
import { cn } from "@/lib/utils";

const SCOPE_ICONS = {
  workspace: Globe,
  department: Building,
  employee: Users,
} as const;

const SCOPE_COLORS = {
  workspace: {
    bg: "bg-amber-50 dark:bg-amber-950/40",
    text: "text-amber-600 dark:text-amber-400",
    border: "border-amber-100 dark:border-amber-800",
    badge: "bg-amber-100 dark:bg-amber-900/50 text-amber-700 dark:text-amber-300",
  },
  department: {
    bg: "bg-sky-50 dark:bg-sky-950/40",
    text: "text-sky-600 dark:text-sky-400",
    border: "border-sky-100 dark:border-sky-800",
    badge: "bg-sky-100 dark:bg-sky-900/50 text-sky-700 dark:text-sky-300",
  },
  employee: {
    bg: "bg-teal-50 dark:bg-teal-950/40",
    text: "text-teal-600 dark:text-teal-400",
    border: "border-teal-100 dark:border-teal-800",
    badge: "bg-teal-100 dark:bg-teal-900/50 text-teal-700 dark:text-teal-300",
  },
} as const;

function formatDate(d: string) {
  return new Date(d).toLocaleDateString("vi-VN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });
}

interface Props {
  deptMap: Record<string, Department>;
  grouped: {
    workspace: PayrollRuleAssignment[];
    department: PayrollRuleAssignment[];
    employee: PayrollRuleAssignment[];
  };
  isDeleting: boolean;
  onDelete: (id: string) => void;
}

export function AssignmentList({ grouped, deptMap, onDelete, isDeleting }: Props) {
  const { t } = useTranslation();
  const [deletingId, setDeletingId] = useState<string | null>(null);

  const getAssigneeName = (a: PayrollRuleAssignment) => {
    if (a.assignee_type === "workspace")
      return t("payroll_rules.scope_workspace", "Entire Workspace");
    if (a.assignee_type === "department")
      return deptMap[a.assignee_id!].name || a.assignee_id?.slice(0, 8) + "…";
    return a.assignee_id?.slice(0, 8) + "…";
  };

  const handleDelete = (id: string) => {
    onDelete(id);
    setDeletingId(null);
  };

  return (
    <div className="space-y-3">
      {(["workspace", "department", "employee"] as const).map((scope) => {
        const items = grouped[scope];
        if (items.length === 0) return null;
        const colors = SCOPE_COLORS[scope];
        const Icon = SCOPE_ICONS[scope];
        return (
          <div className="space-y-2" key={scope}>
            <div className="flex items-center gap-2 px-1">
              <Icon className={colors.text + " opacity-60"} size={12} />
              <span className="text-[9px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-[0.2em]">
                {t(`payroll.scope_level_${scope}`, `${scope} level`)} ({items.length})
              </span>
            </div>
            {items.map((a) => (
              <div
                className={cn(
                  "flex items-center justify-between p-4 rounded-xl border shadow-sm transition-all group hover:shadow-md",
                  colors.bg,
                  colors.border,
                  deletingId === a.id && "ring-2 ring-rose-300 dark:ring-rose-700"
                )}
                key={a.id}
              >
                <div className="flex items-center gap-4 min-w-0">
                  <div
                    className={cn(
                      "w-10 h-10 rounded-xl flex items-center justify-center shrink-0",
                      colors.badge
                    )}
                  >
                    <Icon size={18} />
                  </div>
                  <div className="min-w-0">
                    <p className="font-bold text-sm text-slate-700 dark:text-slate-200 uppercase tracking-tight truncate leading-none">
                      {getAssigneeName(a)}
                    </p>
                    <div className="flex items-center gap-3 mt-1.5 flex-wrap">
                      <span className="flex items-center gap-1 text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest">
                        <Calendar className="opacity-50" size={10} />
                        {formatDate(a.effective_from)}
                        {a.effective_to
                          ? ` → ${formatDate(a.effective_to)}`
                          : " → ∞"}
                      </span>
                      {!!a.override_config && (
                        <span className="flex items-center gap-1 text-[9px] font-bold bg-orange-100 dark:bg-orange-900/40 text-orange-700 dark:text-orange-300 px-2 py-0.5 rounded-md border border-orange-200 dark:border-orange-800">
                          <Sliders size={9} /> {t("payroll.override", "OVERRIDE")}
                          {a.override_config.rate != null &&
                            ` ${a.override_config.rate}%`}
                          {a.override_config.amount != null &&
                            ` ₫${Number(
                              a.override_config.amount
                            ).toLocaleString()}`}
                        </span>
                      )}
                    </div>
                  </div>
                </div>

                {/* Delete button */}
                {deletingId === a.id ? (
                  <div className="flex items-center gap-2 animate-in fade-in duration-200">
                    <button
                      className="px-3 py-1.5 bg-rose-600 text-white rounded-lg text-[10px] font-bold uppercase tracking-widest hover:bg-rose-700 transition-all disabled:opacity-50"
                      disabled={isDeleting}
                      onClick={() => { handleDelete(a.id); }}
                    >
                      {isDeleting ? "…" : t("common.confirm", "Confirm")}
                    </button>
                    <button
                      className="px-3 py-1.5 bg-slate-200 dark:bg-slate-700 text-slate-600 dark:text-slate-300 rounded-lg text-[10px] font-bold uppercase tracking-widest hover:bg-slate-300 dark:hover:bg-slate-600 transition-all"
                      onClick={() => { setDeletingId(null); }}
                    >
                      {t("common.cancel", "Cancel")}
                    </button>
                  </div>
                ) : (
                  <button
                    aria-label={t("payroll.delete_assignment", "Delete assignment")}
                    className="p-2.5 text-slate-300 dark:text-slate-600 hover:text-rose-500 dark:hover:text-rose-400 rounded-xl hover:bg-white dark:hover:bg-slate-900 transition-all opacity-0 group-hover:opacity-100 active:scale-90 shadow-none hover:shadow-md border border-transparent hover:border-slate-100 dark:hover:border-slate-800"
                    onClick={() => { setDeletingId(a.id); }}
                  >
                    <Trash2 size={16} />
                  </button>
                )}
              </div>
            ))}
          </div>
        );
      })}
    </div>
  );
}

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Plus, Trash2, LayoutList } from "lucide-react";
import React, { useState } from "react";
import { useTranslation } from "react-i18next";

import { useToast } from "@/components/ui/toast";
import { fetchPayrollRuleTiers, createPayrollRuleTier } from "@/lib/api/payroll";
import { PayrollRuleTier } from "@/lib/api/types";


interface Props {
  onClose?: () => void;
  ruleId: string;
  wsId: string;
}

export default function RuleTierManager({ wsId, ruleId, onClose: _onClose }: Props) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const toast = useToast();

  const { data: tiers, isLoading } = useQuery({
    queryKey: ["payroll-rule-tiers", ruleId],
    queryFn: () => fetchPayrollRuleTiers(wsId, ruleId),
    enabled: !!ruleId,
  });

  const [newTier, setNewTier] = useState<Partial<PayrollRuleTier>>({
    min_amount: 0,
    max_amount: undefined,
    rate: 0,
    fixed_amount: 0,
  });

  const createMutation = useMutation({
    mutationFn: (data: Partial<PayrollRuleTier>) => createPayrollRuleTier(wsId, ruleId, { ...data, tier_order: (tiers?.length ?? 0) + 1 }),
    onSuccess: () => {
      toast.success(t("common.success"));
      void queryClient.invalidateQueries({ queryKey: ["payroll-rule-tiers", ruleId] });
      setNewTier({ min_amount: 0, max_amount: undefined, rate: 0, fixed_amount: 0 });
    },
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    createMutation.mutate(newTier);
  };

  return (
    <div className="space-y-6">
      <div className="bg-slate-50 dark:bg-slate-800/50 rounded-2xl p-6 border border-slate-100 dark:border-slate-800">
        <div className="flex items-center gap-3 mb-4">
          <div className="w-8 h-8 rounded-lg bg-primary-100 dark:bg-primary-900/30 text-primary-600 flex items-center justify-center">
            <LayoutList size={16} />
          </div>
          <div>
            <h3 className="font-bold text-sm uppercase tracking-widest text-slate-700 dark:text-slate-200">{t("payroll.rule_tiers.title")}</h3>
            <p className="text-[10px] text-slate-500 uppercase tracking-widest mt-1">{t("payroll.rule_tiers.subtitle")}</p>
          </div>
        </div>

        {isLoading ? (
          <div className="p-10 text-center text-slate-500">{t("payroll.rule_tiers.loading")}</div>
        ) : (
          <div className="space-y-2">
            {tiers?.map((tier) => (
              <div className="flex items-center justify-between p-4 bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm" key={tier.id}>
                <div className="flex items-center gap-4">
                  <span className="w-6 h-6 rounded-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center text-xs font-bold text-slate-500">{tier.tier_order}</span>
                  <div className="text-sm font-bold text-slate-700 dark:text-slate-200 font-mono">
                    {tier.min_amount.toLocaleString()} ₫ - {tier.max_amount ? `${tier.max_amount.toLocaleString()} ₫` : '∞'}
                  </div>
                </div>
                <div className="flex items-center gap-4">
                  {tier.rate !== undefined && tier.rate > 0 && <span className="text-xs font-bold text-primary-600 bg-primary-50 px-2 py-1 rounded-md">{tier.rate}%</span>}
                  {tier.fixed_amount !== undefined && tier.fixed_amount > 0 && <span className="text-xs font-bold text-rose-600 bg-rose-50 px-2 py-1 rounded-md">-{tier.fixed_amount.toLocaleString()} ₫</span>}
                  <button className="text-slate-400 hover:text-rose-500 transition-colors"><Trash2 size={16} /></button>
                </div>
              </div>
            ))}

            {/* Add new tier form */}
            <form className="mt-4 p-4 bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-700 shadow-inner flex items-end gap-4" onSubmit={handleSubmit}>
              <div className="flex-1 space-y-2">
                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{t("payroll.rule_tiers.fields.min_amount")}</label>
                <input className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm font-bold" onChange={e => { setNewTier({...newTier, min_amount: parseFloat(e.target.value)}); }} required type="number" value={newTier.min_amount} />
              </div>
              <div className="flex-1 space-y-2">
                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{t("payroll.rule_tiers.fields.max_amount")}</label>
                <input className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm font-bold" onChange={e => { setNewTier({...newTier, max_amount: e.target.value ? parseFloat(e.target.value) : undefined}); }} type="number" value={newTier.max_amount ?? ""} />
              </div>
              <div className="flex-1 space-y-2">
                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{t("payroll.rule_tiers.fields.rate")}</label>
                <input className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm font-bold" onChange={e => { setNewTier({...newTier, rate: e.target.value ? parseFloat(e.target.value) : 0}); }} step="0.01" type="number" value={newTier.rate ?? ""} />
              </div>
              <div className="flex-1 space-y-2">
                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{t("payroll.rule_tiers.fields.fixed_deduction")}</label>
