interface DayCardShiftDetailsProps {
  dateString: string;
  effectiveSchedule?: EffectiveSchedule;
  formatTime: (time: string | null | undefined) => string;
  onDeleteRoster: (date: string) => void;
  source?: string;
  t: TFunction;
