      <div className={`flex items-center gap-1.5 text-[10px] font-bold ${source === 'roster' ? 'text-teal-500' : 'text-blue-500'}`}>
        {formatTime(effectiveSchedule.start_time)} - {formatTime(effectiveSchedule.end_time)}
