      <div className="flex items-center justify-between bg-white dark:bg-slate-900 p-4 rounded-[32px] border border-slate-200 dark:border-slate-700 shadow-sm">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 bg-primary-600 rounded-2xl flex items-center justify-center text-white text-lg font-bold shadow-lg shadow-primary-100">
            {selectedEmployee.full_name[0]}
          </div>
          <div>
            <h2 className="text-lg font-bold text-slate-700 dark:text-slate-200 leading-tight">{selectedEmployee.full_name}</h2>
            <p className="text-[10px] font-bold uppercase tracking-widest text-slate-500 dark:text-slate-400">{t("shifts.current_week_roster")}</p>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <div className="w-56">
            <Combobox
              className="h-10 bg-slate-100 dark:bg-slate-700 border-slate-200 dark:border-slate-700 text-[10px] py-2 px-3 rounded-xl uppercase tracking-tighter"
              onChange={(value) => {
                if (value === "copy-prev") onCopyPreviousWeek();
                else if (value === "clear-week") onClearWeek();
                else if (value === "assign-all") onAssignAllWeek();
              }}
              options={[
                { value: "copy-prev", label: t("shifts.actions.copy_previous"), icon: <Copy className="w-4 h-4" /> },
                { value: "assign-all", label: t("shifts.actions.assign_all_week"), icon: <CalendarIcon className="w-4 h-4" /> },
                { value: "clear-week", label: t("shifts.actions.clear_week"), icon: <Trash className="w-4 h-4" /> },
              ]}
              placeholder={t("common.quick_actions")}
            />
          </div>
          <button
            className="p-2.5 hover:bg-slate-100 dark:hover:bg-slate-700 border border-slate-100 dark:border-slate-800 rounded-xl transition-all"
            onClick={() => { onNavigateWeek("prev"); }}
          >
            <ChevronLeft size={18} />
          </button>
          <div className="px-4 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-xs font-bold text-slate-600 dark:text-slate-300 uppercase tracking-tighter">
            {formatDate(weekDays[0])} - {formatDate(weekDays[6])}
          </div>
          <button
            className="p-2.5 hover:bg-slate-100 dark:hover:bg-slate-700 border border-slate-100 dark:border-slate-800 rounded-xl transition-all"
            onClick={() => { onNavigateWeek("next"); }}
          >
            <ChevronRight size={18} />
          </button>
        </div>
      </div>

      {selectedDays.length > 0 && (
        <div className="bg-primary-600 text-white p-4 rounded-[24px] flex items-center justify-between shadow-xl shadow-primary-100 dark:shadow-black/30 animate-in slide-in-from-top-4 duration-300">
          <div className="flex items-center gap-4">
            <span className="text-xs font-bold uppercase tracking-widest">
              {t("shifts.days_selected", { count: selectedDays.length })}
            </span>
            <div className="h-4 w-px bg-white dark:bg-slate-900/20" />
            <button
              className="bg-white dark:bg-slate-900/10 border border-white/20 rounded-xl px-4 py-2 text-[10px] font-bold uppercase tracking-widest hover:bg-white dark:hover:bg-slate-900/20 transition-all flex items-center gap-2"
              onClick={() => { onOpenShiftPicker(selectedDays); }}
            >
              <Plus size={14} /> {t("shifts.assign_selected_btn")}
            </button>
          </div>
          <button className="hover:bg-white dark:hover:bg-slate-900/10 p-2 rounded-xl transition-all" onClick={onClearSelection}>
            <X size={18} />
          </button>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-7 gap-4">
        {weekDays.map((day, index) => {
          const dateString = format(day, 'yyyy-MM-dd');
          const isSelected = selectedDays.includes(dateString);

          const effectiveSchedule = employeeSchedule?.schedules.find((s) => s.date === dateString);
          const isToday = day.toDateString() === new Date().toDateString();

          const isHoliday = effectiveSchedule?.is_holiday === true;

          return (
            <WeeklyRosterDayCard
              currentLocale={currentLocale}
              dateString={dateString}
              day={day}
              effectiveSchedule={effectiveSchedule}
              formatTime={formatTime}
              isHoliday={isHoliday}
              isSelected={isSelected}
              isToday={isToday}
              key={index}
              onDeleteRoster={onDeleteRoster}
              onToggleDaySelection={onToggleDaySelection}
              t={t}
            />
          );
        })}
      </div>
    </div>
  );
}

import React from "react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

export interface TabConfig {
  colorScheme: "amber" | "emerald" | "rose" | "blue" | "slate";
  icon?: React.ReactNode;
  id: string;
  label: string;
}

interface ApprovalListLayoutProps {
  activeTab: string;
  banner?: React.ReactNode;
  children?: React.ReactNode;
  emptyMessage?: string;
  headerActions?: React.ReactNode;
  isEmpty?: boolean;
  isLoading?: boolean;
  modals?: React.ReactNode;
  onTabChange: (tabId: string) => void;
  subtitle: string;
  tableHeaders: React.ReactNode[];
  tabs: TabConfig[];
  title: string;
}

export default function ApprovalListLayout({
  title,
  subtitle,
  headerActions,
  banner,
  tabs,
  activeTab,
  onTabChange,
  tableHeaders,
  isLoading,
  isEmpty,
  emptyMessage,
  children,
  modals,
}: ApprovalListLayoutProps) {
  const { t } = useTranslation();

  return (
    <div className="space-y-10 animate-in fade-in duration-700 pb-20">
      <div className="flex flex-col md:flex-row justify-between items-center gap-8 px-2">
        <div className="space-y-1">
          <h1 className="text-5xl font-bold tracking-tighter text-primary-700 dark:text-primary-300 uppercase leading-none">
            {title}
          </h1>
          <p className="text-[10px] font-bold text-primary-400 uppercase tracking-[0.25em] opacity-60">
            {subtitle}
          </p>
        </div>
        <div className="flex items-center gap-3 flex-wrap">
          {headerActions}
        </div>
      </div>

      {banner}

      <div className="flex bg-slate-100 dark:bg-slate-700/50 p-1.5 rounded-[22px] w-fit border border-primary-200 dark:border-primary-800/50/50 shadow-inner">
        {tabs.map((tab) => {
          const isActive = activeTab === tab.id;

          let activeClasses = "";
          if (isActive) {
            switch (tab.colorScheme) {
              case "amber":
                activeClasses = "bg-white dark:bg-slate-900 text-amber-600 dark:text-amber-300 shadow-sm border border-primary-100 dark:border-primary-800/50";
                break;
              case "emerald":
                activeClasses = "bg-white dark:bg-slate-900 text-emerald-600 dark:text-emerald-300 shadow-sm border border-primary-100 dark:border-primary-800/50";
                break;
              case "rose":
                activeClasses = "bg-white dark:bg-slate-900 text-rose-600 dark:text-rose-300 shadow-sm border border-primary-100 dark:border-primary-800/50";
                break;
              case "blue":
                activeClasses = "bg-white dark:bg-slate-900 text-blue-600 dark:text-blue-300 shadow-sm border border-primary-100 dark:border-primary-800/50";
                break;
              default:
                activeClasses = "bg-white dark:bg-slate-900 text-primary-600 dark:text-primary-300 shadow-sm border border-primary-100 dark:border-primary-800/50";
            }
          } else {
            activeClasses = "text-primary-400 hover:text-primary-700 dark:text-primary-300";
          }

          return (
            <button
              className={cn(
                "flex items-center gap-2 px-8 py-2.5 rounded-[18px] text-xs font-bold uppercase tracking-widest transition-all",
                activeClasses
              )}
              key={tab.id}
              onClick={() => { onTabChange(tab.id); }}
            >
              {tab.icon} {tab.label}
            </button>
          );
        })}
      </div>

      <div className="bg-white dark:bg-slate-900 border border-primary-100 dark:border-primary-800/50 rounded-[3rem] overflow-hidden shadow-sm animate-in slide-in-from-bottom-8 duration-700">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-slate-50 dark:bg-slate-800/50 border-b border-primary-100 dark:border-primary-800/50">
              {tableHeaders.map((header, index) => (
                <React.Fragment key={index}>{header}</React.Fragment>
              ))}
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
            {isLoading ? (
              <tr>
                <td className="px-10 py-20 text-center text-primary-400 font-bold italic uppercase tracking-widest text-xs opacity-50 animate-pulse" colSpan={tableHeaders.length}>
                  {t("common.loading")}
                </td>
              </tr>
            ) : isEmpty ? (
              <tr>
                <td className="px-10 py-32 text-center text-primary-400 font-bold italic uppercase tracking-widest text-xs opacity-50" colSpan={tableHeaders.length}>
                  {emptyMessage ?? t("common.no_data")}
                </td>
              </tr>
            ) : (
              children
            )}
          </tbody>
        </table>
      </div>

      {modals}
    </div>
  );
}

import { History } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { format } from "date-fns";

import Modal from "@/components/ui/modal";
import { useDateTimeFormatter } from "@/hooks/use-datetime";
import { TimeEntry } from "@/lib/api";

interface AdjustmentRequestModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (data: AdjustmentData) => Promise<void>;
  timeEntry?: TimeEntry;
  timezone: string;
}

export interface AdjustmentData {
  date: string;
  isBreakOvertime: boolean;
  punchIn: string;
  punchOut: string;
  reason: string;
  timeEntryId?: string;
}

export function AdjustmentRequestModal({
  isOpen,
  onClose,
  timeEntry,
  onSubmit,
  timezone: _timezone
}: AdjustmentRequestModalProps) {
  const { t } = useTranslation();
  const { formatTime24h } = useDateTimeFormatter();
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [formData, setFormData] = useState<AdjustmentData>({
    date: timeEntry
      ? format(new Date(timeEntry.punch_in_time), "yyyy-MM-dd")
      : format(new Date(), "yyyy-MM-dd"),
    punchIn: timeEntry
      ? formatTime24h(timeEntry.punch_in_time)
      : "08:00",
    punchOut: timeEntry?.punch_out_time
      ? formatTime24h(timeEntry.punch_out_time)
      : "17:00",
    reason: "",
    isBreakOvertime: timeEntry?.is_break_overtime ?? false,
    timeEntryId: timeEntry?.id
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    try {
      await onSubmit(formData);
      onClose();
    } catch (error) {
      console.error("Failed to submit adjustment:", error);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Modal
      icon={<History size={24} />}
      isOpen={isOpen}
      maxWidth="md"
      onClose={onClose}
      subtitle={t("time_tracking.modal.subtitle")}
      title={
        formData.timeEntryId
          ? t("time_tracking.modal.edit_title")
          : t("time_tracking.modal.new_title")
      }
    >
      <form className="space-y-8 pt-4" onSubmit={handleSubmit}>
        <div className="space-y-2">
          <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ml-1">
            {t("common.work_day")}
          </label>
          <input className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-800 rounded-2xl focus:ring-4 focus:ring-primary-500/10 focus:bg-white dark:focus:bg-slate-900 outline-none transition-all font-bold text-sm tracking-tight" onChange={(e) =>
              { setFormData({ ...formData, date: e.target.value }); }
            } required type="date" value={formData.date}
          />
        </div>

        <div className="grid grid-cols-2 gap-6">
          <div className="space-y-2">
            <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ml-1">
              {t("common.punch_in")}
            </label>
            <input
              className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-800 rounded-2xl focus:ring-4 focus:ring-primary-500/10 focus:bg-white dark:focus:bg-slate-900 outline-none transition-all font-mono font-bold text-sm text-center"
              onChange={(e) =>
                { setFormData({ ...formData, punchIn: e.target.value }); }
              }
              required
              type="time"
              value={formData.punchIn}
            />
          </div>
          <div className="space-y-2">
            <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ml-1">
              {t("common.punch_out")}
            </label>
            <input
              className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-800 rounded-2xl focus:ring-4 focus:ring-primary-500/10 focus:bg-white dark:focus:bg-slate-900 outline-none transition-all font-mono font-bold text-sm text-center"
              onChange={(e) =>
                { setFormData({ ...formData, punchOut: e.target.value }); }
              }
              required
              type="time"
              value={formData.punchOut}
            />
          </div>
        </div>

        <div className="flex items-center gap-4 py-2 bg-slate-50 dark:bg-slate-800/50 p-4 rounded-[1.5rem] border border-slate-100 dark:border-slate-800 shadow-inner">
          <input
            checked={formData.isBreakOvertime}
            className="w-6 h-6 text-primary-600 dark:text-primary-400 rounded-xl border-slate-200 dark:border-slate-700 focus:ring-primary-500 transition-all cursor-pointer"
            id="is_break_overtime"
            onChange={(e) =>
              { setFormData({ ...formData, isBreakOvertime: e.target.checked }); }
            }
            type="checkbox"
          />
          <label
            className="text-xs font-bold text-slate-700 dark:text-slate-200 uppercase tracking-widest cursor-pointer leading-tight"
            htmlFor="is_break_overtime"
          >
            {t("attendance_confirm.ot_label")}
          </label>
        </div>

        <div className="space-y-2">
          <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ml-1">
            {t("time_tracking.modal.reason_label")}
          </label>
          <textarea
            className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-800 rounded-2xl focus:ring-4 focus:ring-primary-500/10 focus:bg-white dark:focus:bg-slate-900 outline-none transition-all font-medium text-sm h-28 resize-none"
            onChange={(e) =>
              { setFormData({ ...formData, reason: e.target.value }); }
            }
            placeholder={t("time_tracking.modal.reason_placeholder")}
            required
            value={formData.reason}
          />
        </div>

        <div className="pt-6 grid grid-cols-2 gap-5">
          <button
            className="px-8 py-4 border border-slate-100 dark:border-slate-800 rounded-2xl font-bold text-xs uppercase tracking-widest text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800 transition-all"
            onClick={onClose}
            type="button"
          >
            {t("common.cancel")}
          </button>
          <button
            className="px-8 py-4 bg-slate-900 text-white rounded-2xl font-bold text-xs uppercase tracking-widest hover:bg-primary-700 transition-all shadow-xl shadow-slate-200 dark:shadow-black/30 active:scale-95 disabled:opacity-50"
            disabled={isSubmitting}
            type="submit"
          >
            {isSubmitting ? t("common.sending").toUpperCase() : t("common.submit_request")}
          </button>
        </div>
      </form>
    </Modal>
  );
}

import { useTranslation } from "react-i18next";

import { useDateTimeFormatter } from "@/hooks/use-datetime";
import { TimeEntry } from "@/lib/api";
import { cn } from "@/lib/utils";

interface TimeEntryRowProps {
  entry: TimeEntry;
  onAdjust?: (entry: TimeEntry) => void;
  showAdjustButton?: boolean;
}

export function TimeEntryRow({
  entry,
  onAdjust,
  showAdjustButton = false
}: TimeEntryRowProps) {
  const { t } = useTranslation();
  const { formatDate, formatTime } = useDateTimeFormatter();

  return (
    <tr className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-all group">
      <td className="px-8 py-5">
        <div className="flex items-center gap-3">
          <span className="text-sm font-bold text-slate-700 dark:text-slate-200">
            {formatDate(entry.punch_in_time)}
          </span>
          <span
            className={cn(
              "px-2 py-0.5 rounded-lg text-[8px] font-bold uppercase tracking-tighter border",
              entry.entry_type === "break"
                ? "bg-amber-50 dark:bg-amber-950 text-amber-600 dark:text-amber-300 border-amber-100 dark:border-amber-800"
                : "bg-primary-50 dark:bg-primary-950 text-primary-600 dark:text-primary-400 border-primary-100 dark:border-primary-800"
            )}
          >
            {entry.entry_type === "break" ? t("common.break") : t("common.work")}
          </span>
        </div>
      </td>
      <td className="px-8 py-5 text-xs font-bold text-slate-500 dark:text-slate-400 font-mono">
        {formatTime(entry.punch_in_time)}
      </td>
      <td className="px-8 py-5">
        {entry.punch_out_time ? (
          <span className="text-xs font-bold text-slate-500 dark:text-slate-400 font-mono">
            {formatTime(entry.punch_out_time)}
          </span>
        ) : (
          <span
            className={cn(
              "font-bold px-2 py-1 rounded-lg text-[9px] uppercase tracking-tighter animate-pulse",
              entry.entry_type === "break"
                ? "text-amber-600 dark:text-amber-300 bg-amber-50 dark:bg-amber-950"
                : "text-primary-600 dark:text-primary-400 bg-primary-50 dark:bg-primary-950"
            )}
          >
            {entry.entry_type === "break"
              ? t("time_tracking.status.on_break")
              : t("time_tracking.status.working")}
          </span>
        )}
      </td>
      {!!showAdjustButton && (
        <td className="px-8 py-5 text-right">
          <button
            className="text-primary-600 dark:text-primary-400 bg-white dark:bg-slate-900 shadow-sm border border-slate-100 dark:border-slate-800 hover:bg-primary-50 dark:bg-primary-950 px-4 py-1.5 rounded-xl transition-all font-bold text-[10px] uppercase tracking-widest active:scale-90 opacity-0 group-hover:opacity-100"
            onClick={() => onAdjust?.(entry)}
          >
            {t("common.adjust")}
          </button>
        </td>
      )}
    </tr>
  );
}

