// ── Hook: useDashboardLayout ───────────────────────────────────────

export function useDashboardLayout() {
    const { workspace } = useWorkspace();
    const queryClient = useQueryClient();

    const queryKey = ["dashboard-preferences", workspace?.id];

    const {
        data: preferences,
        isLoading,
        error,
    } = useQuery<DashboardLayoutPreferences>({
        queryKey,
        queryFn: async () => {
            const response = await apiFetch("/dashboard/preferences");
            if (!response.ok) throw new Error("Failed to fetch dashboard preferences");
            return (await response.json()) as DashboardLayoutPreferences;
        },
        enabled: !!workspace,
    });

    const mutation = useMutation({
        mutationFn: async (update: Partial<Omit<DashboardLayoutPreferences, "id" | "user_id" | "workspace_id">>) => {
            const response = await apiFetch("/dashboard/preferences", {
                method: "PUT",
                body: JSON.stringify(update),
            });
            if (!response.ok) throw new Error("Failed to save dashboard preferences");
            return (await response.json()) as DashboardLayoutPreferences;
        },
        onSuccess: (data) => {
            queryClient.setQueryData(queryKey, data);
        },
    });

    // ── Computed values ──────────────────────────────────────────────

    const activeView: DashboardView = preferences?.active_view ?? "overview";

    const visibleWidgets: Record<WidgetId, boolean> = (() => {
        if (activeView === "custom") {
            return (preferences?.visible_widgets ?? {}) as Record<WidgetId, boolean>;
        }
        return PRESET_VIEWS[activeView].visible as Record<WidgetId, boolean>;
    })();

    const widgetOrder: WidgetId[] = (() => {
        if (activeView === "custom" && preferences?.widget_order.length) {
            return preferences.widget_order;
        }
        return PRESET_VIEWS[activeView as Exclude<DashboardView, "custom">].order ?? ALL_WIDGETS.map((w) => w.id);
    })();

    const collapsedSections: Record<string, boolean> =
        (preferences?.collapsed_sections!) ?? {};

    // ── Actions ──────────────────────────────────────────────────────

    const setActiveView = (view: DashboardView) => {
        mutation.mutate({
            active_view: view,
            visible_widgets: view === "custom" ? preferences?.visible_widgets : PRESET_VIEWS[view].visible as Record<string, boolean>,
            widget_order: view === "custom" ? preferences?.widget_order : PRESET_VIEWS[view].order,
            collapsed_sections: preferences?.collapsed_sections,
        });
    };

    const toggleWidget = (widgetId: WidgetId) => {
        const updated = { ...visibleWidgets, [widgetId]: !visibleWidgets[widgetId] };
        mutation.mutate({
            active_view: "custom",
            visible_widgets: updated,
            widget_order: preferences?.widget_order ?? ALL_WIDGETS.map((w) => w.id),
            collapsed_sections: preferences?.collapsed_sections,
        });
    };

    const setWidgetOrder = (order: WidgetId[]) => {
        mutation.mutate({
            active_view: "custom",
            visible_widgets: preferences?.visible_widgets,
            widget_order: order,
            collapsed_sections: preferences?.collapsed_sections,
        });
    };

    const toggleSection = (sectionId: string) => {
        const updated = { ...collapsedSections, [sectionId]: !collapsedSections[sectionId] };
        mutation.mutate({
            active_view: preferences?.active_view,
            visible_widgets: preferences?.visible_widgets,
            widget_order: preferences?.widget_order,
            collapsed_sections: updated,
        });
    };

    const resetToDefault = () => {
        mutation.mutate({
            active_view: "overview",
            visible_widgets: PRESET_VIEWS.overview.visible as Record<string, boolean>,
            widget_order: PRESET_VIEWS.overview.order,
            collapsed_sections: { summary: false, charts: false, actions: true },
        });
    };

    return {
        // State
        activeView,
        visibleWidgets,
        widgetOrder,
        collapsedSections,
        isLoading,
        error,
        isSaving: mutation.isPending,
        // Actions
        setActiveView,
        toggleWidget,
        setWidgetOrder,
        toggleSection,
        resetToDefault,
        // Raw data for CustomizePanel
        allWidgets: ALL_WIDGETS,
    };
}

import { useQuery } from "@tanstack/react-query";

import { fetchEmployees } from "@/lib/api";

/**
 * Maximum number of employees fetched in a single "all employees" request.
 * Used across pages that need a full employee roster for dropdowns/search.
 */
export const MAX_EMPLOYEE_FETCH = 3_000;

export const employeeKeys = {
  all: ["employees"] as const,
  list: (wsId: string | null | undefined) => [...employeeKeys.all, wsId] as const,
};

/**
 * Shared hook to fetch the full employee list for a workspace.
 *
 * Replaces the duplicated `fetchEmployees(wsId!, 1, 3000)` pattern
 * found across multiple pages. Centralizes query key, enabled guard,
 * and the fetch limit into one reusable hook.
 *
 * @param wsId - Active workspace ID. Query is disabled when falsy.
 * @param options - Optional overrides (e.g., enabled for lazy-loaded modals).
 */
export function useAllEmployees(
  wsId: string | null | undefined,
  options?: { enabled?: boolean },
) {
  const enabledOverride = options?.enabled ?? true;

  const query = useQuery({
    queryKey: employeeKeys.list(wsId),
    queryFn: () => fetchEmployees(wsId!, 1, MAX_EMPLOYEE_FETCH),
    enabled: !!wsId && enabledOverride,
  });

  return {
    employees: (query.data?.data ?? []),
    employeesData: query.data,
    isLoading: query.isLoading,
    isError: query.isError,
    error: query.error,
  };
}

import { useEffect, useRef } from 'react';
import { useTranslation } from 'react-i18next';

import { getCurrentWorkspaceId } from '@/lib/api';

import { useProfile } from './use-profile';
import { useWorkspaces } from './use-workspace';

export function useI18nSync() {
  const { i18n } = useTranslation();
  const { user } = useProfile();
  const { workspaces } = useWorkspaces();
  const currentWsId = getCurrentWorkspaceId();
  const currentWorkspace = workspaces.find(ws => ws.id === currentWsId);

  // Track if this is the initial mount to only sync once on load
  const hasInitialized = useRef(false);

  useEffect(() => {
    // Only sync language on initial load, not on every preference change
    if (hasInitialized.current) return;

    // Respect localStorage if user has manually set a language
    const localStorageLang = localStorage.getItem('i18nextLng');
    if (localStorageLang && ['en', 'vi', 'zh'].includes(localStorageLang)) {
      // User has a localStorage preference, don't override with server value
      if (user) {
        hasInitialized.current = true;
      }
      return;
    }

    // No localStorage preference, use server preference or workspace default
    const langToSet = user?.preferred_language ?? currentWorkspace?.default_language;

    if (langToSet && i18n.language !== langToSet) {
      void i18n.changeLanguage(langToSet);
      localStorage.setItem('i18nextLng', langToSet);
    }

    // Mark as initialized once we have user data
    if (user) {
      hasInitialized.current = true;
    }
  }, [user?.preferred_language, currentWorkspace?.default_language, i18n, user]);
}

import { useQuery } from "@tanstack/react-query";
import { useCallback } from "react";

import { fetchMyPermissions, getCurrentWorkspaceId } from "@/lib/api";

export const myPermissionsKey = (wsId: string) =>
    ["my-permissions", wsId] as const;

/**
 * Hook that fetches and caches the current user's effective permissions
 * for the active workspace.
 *
 * Usage:
 *   const { hasPermission, permissions, roles, isLoading } = useMyPermissions();
 *   if (hasPermission("employees:create")) { ... }
 */
export function useMyPermissions() {
    const wsId = getCurrentWorkspaceId() ?? "";

    const query = useQuery({
        queryKey: myPermissionsKey(wsId),
        queryFn: fetchMyPermissions,
        enabled: !!wsId,
        staleTime: 5 * 60 * 1000, // cache for 5 minutes — permissions don't change often
        gcTime: 10 * 60 * 1000,
    });

    const permissionSet = new Set(query.data?.permissions ?? []);

    const hasPermission = useCallback(
        (permission: string): boolean => permissionSet.has(permission),
        // eslint-disable-next-line react-hooks/exhaustive-deps
        [query.data?.permissions],
    );

    const hasAnyPermission = useCallback(
        (...permissions: string[]): boolean =>
            permissions.some((p) => permissionSet.has(p)),
        // eslint-disable-next-line react-hooks/exhaustive-deps
        [query.data?.permissions],
    );

    const hasRole = useCallback(
        (role: string): boolean =>
            (query.data?.roles ?? []).some(
                (r: string) => r.toLowerCase() === role.toLowerCase(),
            ),
        [query.data?.roles],
    );

    const hasScopedPermission = useCallback(
        (permission: string, targetDepartmentId?: string): boolean => {
            if (!permissionSet.has(permission)) return false;

            const allowedDepts = query.data?.managed_department_ids;

            // null or undefined means global scope
            if (allowedDepts === null || allowedDepts === undefined) {
                return true;
            }

            // Must match one of the allowed departments
            if (targetDepartmentId && Array.isArray(allowedDepts)) {
                return allowedDepts.includes(targetDepartmentId);
            }

            return false;
        },
        // eslint-disable-next-line react-hooks/exhaustive-deps
        [query.data?.permissions, query.data?.managed_department_ids],
    );

    return {
        permissions: query.data?.permissions ?? [],
        roles: query.data?.roles ?? [],
        managedDepartmentIds: query.data?.managed_department_ids ?? null,
        isLoading: query.isLoading,
        hasPermission,
        hasAnyPermission,
        hasRole,
        hasScopedPermission,
    };
}

"use client";

import { useEffect, useRef, useState, useCallback } from "react";

import type {
  StreamMessage,
  StreamStatus,
} from "@/types/report-stream";

import { API_BASE_URL } from "@/lib/api/config";
import {
  getAccessToken,
  getRefreshToken,
  setAccessToken,
  setRefreshToken,
  clearAuthSession,
} from "@/lib/api/helpers";
import { ROUTES } from "@/lib/routes";

interface UseReportStreamOptions {
  jobId: string | null;
  maxRetries?: number;
  onComplete?: (data: unknown[]) => void;
  onError?: (message: string) => void;
}

interface UseReportStreamResult {
  chunks: unknown[];
  error: string | null;
  progress: number; // 0-100
  reconnect: () => void;
  status: StreamStatus;
}

/**
 * Build WebSocket URL for report streaming
 * Uses wss: for HTTPS, ws: for HTTP
 * Includes JWT token as query param (required by ws_auth_middleware)
 */
function buildWebSocketUrl(jobId: string): string {
  const protocol = window.location.protocol === "https:" ? "wss:" : "ws:";
  const host = window.location.host;
  const token = getAccessToken();
  const params = token ? `?token=${encodeURIComponent(token)}` : "";
  return `${protocol}//${host}/api/ws/reports/${jobId}${params}`;
}

/**
 * Calculate exponential backoff delay
 * Returns delays: 1s, 2s, 4s for retries 0, 1, 2
 */
function getBackoffDelay(retryCount: number): number {
  return Math.pow(2, retryCount) * 1000;
}

/**
 * Attempt to refresh JWT token (same logic as apiFetch 401 handler)
 * Returns true if refresh succeeded, false otherwise
 */
async function tryRefreshToken(): Promise<boolean> {
  const refreshToken = getRefreshToken();
  if (!refreshToken) return false;

  try {
    const response = await fetch(`${API_BASE_URL}/auth/refresh`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ refresh_token: refreshToken }),
    });

    if (response.ok) {
      const data = await response.json() as { access_token: string; refresh_token: string };
      setAccessToken(data.access_token);
      setRefreshToken(data.refresh_token);

      return true;
    }
  } catch (e) {
    console.error("[ReportStream] Token refresh failed", e);
  }

  return false;
}

/**
 * Hook for WebSocket-based report streaming
 * Connects to the report WebSocket endpoint and accumulates chunks
 */
export function useReportStream({
  jobId,
  onComplete,
  onError,
  maxRetries = 3,
}: UseReportStreamOptions): UseReportStreamResult {
  const [status, setStatus] = useState<StreamStatus>("idle");
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState<string | null>(null);
  // Expose chunks via state for consumers that need reactivity
  const [chunks, setChunks] = useState<unknown[]>([]);

  // Use refs to avoid re-renders on each chunk and prevent stale closures
  const socketRef = useRef<WebSocket | null>(null);
  const pingIntervalRef = useRef<NodeJS.Timeout | null>(null);
  const chunksRef = useRef<unknown[]>([]);
  const retryCountRef = useRef(0);
  const shouldReconnectRef = useRef(true);
  const totalBatchesRef = useRef(0);
  const statusRef = useRef<StreamStatus>("idle");

  // Store callbacks in refs to avoid dependency issues
  const onCompleteRef = useRef(onComplete);
  const onErrorRef = useRef(onError);

  useEffect(() => {
    onCompleteRef.current = onComplete;
    onErrorRef.current = onError;
    statusRef.current = status;
  });

  /**
   * Handle incoming WebSocket message
   */
  const handleMessage = useCallback((event: MessageEvent) => {
    try {
      const message = JSON.parse(event.data as string) as StreamMessage;

      switch (message.type) {
        case "CHUNK": {
          const chunkMessage = message;

          // Update progress (data is no longer sent in CHUNK messages)
          totalBatchesRef.current = chunkMessage.total_batches;
          const newProgress =
            ((chunkMessage.batch_index + 1) / chunkMessage.total_batches) * 100;
          setProgress(Math.min(newProgress, 100));
          setStatus("streaming");


          break;
        }

        case "DONE": {
          setStatus("completed");
          setProgress(100);
          shouldReconnectRef.current = false;
          // Update chunks state for consumers, then clear ref to avoid double-buffering
          const finalChunks = [...chunksRef.current];
          chunksRef.current = [];
          setChunks(finalChunks);

          onCompleteRef.current?.(finalChunks);
          break;
        }

        case "ERROR": {
          setStatus("error");
          setError(message.message);
          shouldReconnectRef.current = false;

          onErrorRef.current?.(message.message);
          break;
        }
      }
    } catch (error_) {
      console.error("[ReportStream] Failed to parse message:", error_);
    }
  }, []);

  /**
   * Connect to WebSocket
   */
  const connect = useCallback(() => {
    if (!jobId) return;

    // Clean up existing connection
    if (socketRef.current) {
      socketRef.current.close();
      socketRef.current = null;
    }

    const url = buildWebSocketUrl(jobId);
    console.error(`[ReportStream] Connecting to ${url}`);

    setStatus("connecting");
    setError(null);

    try {
      const socket = new WebSocket(url);
      socketRef.current = socket;

      // Add a connection timeout (3 seconds) to prevent infinite hanging
      // if a firewall or proxy swallows the connection attempt silently.
      const connectionTimeoutId = setTimeout(() => {
        if (socket.readyState === WebSocket.CONNECTING) {
          console.warn("[ReportStream] Connection timeout, closing socket manually");
          socket.close();
        }
      }, 3000);

      socket.onopen = () => {
        clearTimeout(connectionTimeoutId);

        setStatus("streaming");
        retryCountRef.current = 0; // Reset retry count on success

        // Start heartbeat ping to keep connection alive through proxies (e.g., Cloudflare 100s limit)
        pingIntervalRef.current = setInterval(() => {
          if (socket.readyState === WebSocket.OPEN) {
            socket.send(JSON.stringify({ type: "ping" }));
          }
        }, 30000); // 30 seconds
      };

      socket.onmessage = handleMessage;

      socket.onerror = (_event) => { /* empty */ };

      socket.onclose = (event) => {
        clearTimeout(connectionTimeoutId);


        // Handle auth failure: code 1006 on first attempt = HTTP 401 (upgrade rejected)
        // Browser doesn't expose HTTP status on WS upgrade failure, but 1006 = abnormal close
        if (
          event.code === 1006 &&
          retryCountRef.current === 0 &&
          statusRef.current === "connecting"
        ) {

          retryCountRef.current++;
          void tryRefreshToken().then((refreshed) => {
            if (refreshed && shouldReconnectRef.current) {

              // eslint-disable-next-line react-hooks/immutability
              connect();
            } else {
              // Refresh failed — session expired, redirect to login
              console.warn("[ReportStream] Session expired, redirecting to login");
              clearAuthSession();
              if (window.location.pathname !== ROUTES.LOGIN) {
                window.location.href = ROUTES.LOGIN;
              }
            }
          });
          return;
        }

        // Only reconnect if not intentionally closed and not completed/errored
        if (
          shouldReconnectRef.current &&
          retryCountRef.current < maxRetries &&
          statusRef.current !== "completed" &&
          statusRef.current !== "error"
        ) {
          const delay = getBackoffDelay(retryCountRef.current);


          retryCountRef.current++;
          setTimeout(() => {
            if (shouldReconnectRef.current) {
              connect();
            }
          }, delay);
        } else if (
          retryCountRef.current >= maxRetries &&
          statusRef.current !== "completed"
        ) {
          setStatus("error");
          setError("Connection lost. Max retries exceeded.");
          onErrorRef.current?.("Connection lost. Max retries exceeded.");
        }
      };
    } catch (error_) {
      console.error("[ReportStream] Failed to create WebSocket:", error_);
      setStatus("error");
      setError("Failed to establish connection");
    }
  }, [jobId, handleMessage, maxRetries]);

  /**
   * Manual reconnect function exposed to consumers
   */
  const reconnect = useCallback(() => {
    retryCountRef.current = 0;
    shouldReconnectRef.current = true;
    chunksRef.current = [];
    setChunks([]);
    setProgress(0);
    setError(null);
    connect();
  }, [connect]);

  const [previousJobId, setPreviousJobId] = useState(jobId);
  if (jobId !== previousJobId) {
    setPreviousJobId(jobId);
    if (!jobId) {
      setStatus("idle");
      setProgress(0);
      setError(null);
      setChunks([]);
    } else {
      setChunks([]);
    }
  }

  // Connect when jobId changes
  useEffect(() => {
    chunksRef.current = [];
    retryCountRef.current = 0;
    shouldReconnectRef.current = true;
    totalBatchesRef.current = 0;

    if (!jobId) return;

    connect();

    // Cleanup on unmount or jobId change
    return () => {
      shouldReconnectRef.current = false;
      if (pingIntervalRef.current) {
        clearInterval(pingIntervalRef.current);
        pingIntervalRef.current = null;
      }
      if (socketRef.current) {
        socketRef.current.close();
        socketRef.current = null;
      }
    };
  }, [jobId, connect]);

  return {
    status,
    progress,
    chunks,
    error,
    reconnect,
  };
}

import { useState, useEffect, useCallback } from "react";

const CHECK_INTERVAL_MS = 5 * 60 * 1000;
const CHECK_ON_VISIBLE = true;

declare const __BUILD_HASH__: string;

export function useVersionCheck() {
  const [hasNewVersion, setHasNewVersion] = useState(false);

  const check = useCallback(async () => {
    try {
      const current = __BUILD_HASH__;
      if (!current) return;

      const res = await fetch(`/?_v=${Date.now()}`, {
        method: "GET",
        headers: { "Cache-Control": "no-cache" },
      });
      const html = await res.text();
      const match = /<meta\s+name="build-version"\s+content="([^"]+)"/i.exec(html);
      if (match && match[1] !== current) {
        setHasNewVersion(true);
      }
    } catch {
      // network error — skip check
    }
  }, []);

  useEffect(() => {
    let cancelled = false;

    const run = async () => {
      await check();
    };
    void run();

    const interval = setInterval(() => {
      if (!cancelled) void check();
    }, CHECK_INTERVAL_MS);

    return () => {
      cancelled = true;
      clearInterval(interval);
    };
  }, [check]);

  useEffect(() => {
    if (!CHECK_ON_VISIBLE) return;

    const handleVisibility = () => {
      if (document.visibilityState === "visible") void check();
    };
    document.addEventListener("visibilitychange", handleVisibility);
    return () =>
      { document.removeEventListener("visibilitychange", handleVisibility); };
  }, [check]);

  const dismiss = useCallback(() => { setHasNewVersion(false); }, []);

  return { hasNewVersion, dismiss };
}

