            "summary",
            1,
            20,
            undefined,
            employeeIds
        );

        expect(apiFetch).toHaveBeenCalledTimes(1);

        const calledUrl = vi.mocked(apiFetch).mock.calls[0][0];

        expect(calledUrl).toContain("employee_ids=emp-1%2Cemp-2"); // %2C is URL encoded comma
    });
