import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Plus, Pencil, Trash2, Building2, UserCircle, Users, LayoutGrid, CalendarDays, Calculator } from "lucide-react";
import React, { useState, useEffect } from "react";
import { useTranslation } from "react-i18next";

import TemporalConfigTable from "@/components/common/temporal-config-table";
import Button from "@/components/ui/button";
import { Combobox } from "@/components/ui/combobox";
import EmptyState from "@/components/ui/empty-state";
import FormField, { LABEL_BASE } from "@/components/ui/form-field";
import Modal from "@/components/ui/modal";
import PageHeader from "@/components/ui/page-header";
import { useToast } from "@/components/ui/toast";
import { useConfirm } from "@/hooks/use-confirm";

import { fetchDepartments, createDepartment, updateDepartment, deleteDepartment, getCurrentWorkspaceId, fetchUsers, fetchWorkingPatterns, fetchDepartmentPayrollConfigs, setDepartmentPayrollConfig, Department } from "../lib/api";

export default function DepartmentsPage() {
  const { t } = useTranslation();
  const wsId = getCurrentWorkspaceId() ?? "";
  const queryClient = useQueryClient();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isConfigModalOpen, setIsConfigModalOpen] = useState(false);
  const [editingDept, setEditingDept] = useState<Department | null>(null);
  const [selectedManagerId, setSelectedManagerId] = useState<string>("");

  const [selectedPatternId, setSelectedPatternId] = useState<string>("");
  const { confirm, ConfirmationDialog } = useConfirm();

  const { data: departments = [], isLoading } = useQuery({ queryKey: ["departments", wsId], queryFn: () => fetchDepartments(wsId), enabled: !!wsId });
  const { data: deptConfigs = [], isLoading: isConfigsLoading } = useQuery({ queryKey: ["dept-payroll-configs", editingDept?.id], queryFn: () => fetchDepartmentPayrollConfigs(wsId, editingDept!.id), enabled: isConfigModalOpen && !!editingDept?.id });

  const saveConfigMutation = useMutation({
    mutationFn: (data: { std_working_days: number; hours_per_day: number; effective_date: string }) => setDepartmentPayrollConfig(wsId, editingDept!.id, data),
    onSuccess: () => { void queryClient.invalidateQueries({ queryKey: ["dept-payroll-configs", editingDept?.id] }); },
  });

  const { data: users = [] } = useQuery({ queryKey: ["users"], queryFn: fetchUsers });
  const { data: patterns = [] } = useQuery({ queryKey: ["working-patterns", wsId], queryFn: () => fetchWorkingPatterns(wsId), enabled: !!wsId });

  const createMutation = useMutation({
    mutationFn: (data: Record<string, unknown>) => createDepartment(wsId, data),
    onSuccess: () => { void queryClient.invalidateQueries({ queryKey: ["departments", wsId] }); setIsModalOpen(false); toast.success(t("common.success")); },

  });

  const updateMutation = useMutation({
    mutationFn: (data: Record<string, unknown>) => updateDepartment(wsId, editingDept!.id, data),
    onSuccess: () => { void queryClient.invalidateQueries({ queryKey: ["departments", wsId] }); setIsModalOpen(false); setEditingDept(null); toast.success(t("common.success")); },

  });

  const deleteMutation = useMutation({
    mutationFn: (id: string) => deleteDepartment(wsId, id),
    onSuccess: () => { void queryClient.invalidateQueries({ queryKey: ["departments", wsId] }); toast.success(t("common.success")); },
  });

  const toast = useToast();

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault(); const formData = new FormData(e.currentTarget);
    const data = { name: formData.get("name") as string, description: formData.get("description") as string, manager_id: selectedManagerId || null, default_working_pattern_id: selectedPatternId || null };
    if (editingDept) { updateMutation.mutate(data); } else { createMutation.mutate(data); }
  };

  useEffect(() => {
    if (editingDept) {
      // eslint-disable-next-line react-hooks/set-state-in-effect -- Derived state synced from props; intentional pattern
      setSelectedManagerId(editingDept.manager_id ?? "");
      setSelectedPatternId(editingDept.default_working_pattern_id ?? "");
    } else {
      setSelectedManagerId("");
      setSelectedPatternId("");
    }
  }, [editingDept]);

  if (!wsId) return <div className="p-12 text-center text-slate-500 dark:text-slate-400 font-bold italic uppercase tracking-widest text-xs opacity-50">{t("common.select_workspace")}</div>;

  return (
    <div className="space-y-10 animate-in fade-in duration-700 pb-20">
      <PageHeader
        actions={
          <Button data-testid="add-dept-btn" icon={<Plus size={18} />} onClick={() => { setEditingDept(null); setIsModalOpen(true); }}>{t("departments.add_btn").toUpperCase()}</Button>
        }
        data-testid="departments-title"
        icon={<Building2 size={24} />}
        subtitle={t("departments.subtitle")}
        title={t("departments.title")}
      />

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {isLoading ? (
          Array.from({ length: 3 }).map((_, index) => (
            <div className="bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 p-10 rounded-[2.5rem] shadow-sm animate-pulse h-80" key={index} />
          ))
        ) : departments.length === 0 ? (
          <EmptyState
            description={t("departments.messages.empty_desc")}
            icon={<Building2 size={40} />}
            title={t("departments.messages.no_departments")}
          />
        ) : departments.map((dept) => (
          <div className="bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 p-10 rounded-[2.5rem] shadow-sm hover:shadow-2xl hover:shadow-primary-100/10 hover:scale-[1.02] transition-all group relative overflow-hidden flex flex-col" key={dept.id}>
            <div className="absolute top-0 right-0 p-8 flex gap-3 translate-y-4 opacity-0 group-hover:translate-y-0 group-hover:opacity-100 transition-all duration-500">
              <button className="p-3 bg-white dark:bg-slate-900 text-slate-500 dark:text-slate-400 hover:text-emerald-600 dark:text-emerald-300 rounded-xl shadow-md border border-slate-100 dark:border-slate-800 transition-all active:scale-90" onClick={() => { setEditingDept(dept); setIsConfigModalOpen(true); }} title={t("payroll.settings.title")}><Calculator size={18} /></button>
              <button className="p-3 bg-white dark:bg-slate-900 text-slate-500 dark:text-slate-400 hover:text-primary-600 dark:text-primary-400 rounded-xl shadow-md border border-slate-100 dark:border-slate-800 transition-all active:scale-90" onClick={() => { setEditingDept(dept); setIsModalOpen(true); }} title={t("common.edit")}><Pencil size={18} /></button>
              <button className="p-3 bg-white dark:bg-slate-900 text-slate-500 dark:text-slate-400 hover:text-rose-600 dark:text-rose-300 rounded-xl shadow-md border border-slate-100 dark:border-slate-800 transition-all active:scale-90" onClick={async () => {
                const ok = await confirm({
                  title: t("common.warning", { defaultValue: "Warning" }),
                  message: t("departments.messages.confirm_delete"),
                  variant: "danger"
                });
                if(ok) deleteMutation.mutate(dept.id);
              }} title={t("common.delete")}><Trash2 size={18} /></button>
            </div>

            <div className="bg-primary-50 dark:bg-primary-950 w-16 h-16 rounded-[1.5rem] flex items-center justify-center text-primary-600 dark:text-primary-400 mb-8 shadow-inner border border-primary-100 dark:border-primary-800/50 group-hover:scale-110 group-hover:rotate-3 transition-all duration-500">
              <Building2 size={32} />
            </div>

            <h2 className="text-2xl font-bold text-slate-700 dark:text-slate-200 tracking-tight mb-3 uppercase leading-none">{dept.name}</h2>
            <p className="text-slate-500 dark:text-slate-400 text-xs mb-10 line-clamp-2 min-h-[3rem] font-bold uppercase tracking-tight opacity-60 leading-relaxed italic">{dept.description ?? t("common.no_description")}</p>

            <div className="mt-auto pt-8 border-t border-slate-50 dark:border-slate-800 flex flex-col gap-6">
              <div className="flex items-center gap-5 group/info">
                <div className="w-10 h-10 rounded-xl bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-800 flex items-center justify-center text-slate-300 dark:text-slate-600 shadow-inner group-hover/info:text-primary-600 dark:text-primary-400 group-hover/info:bg-primary-50 dark:bg-primary-950 group-hover/info:border-primary-100 dark:border-primary-800 transition-all"><Users size={20} /></div>
                <div>
                  <span className="block text-slate-500 dark:text-slate-400 font-bold uppercase tracking-[0.2em] text-[9px] mb-1">{t("departments.active_employees_label")}</span>
                  <span className="font-bold text-slate-800 dark:text-slate-100 text-xs uppercase tracking-tight">{dept.active_employee_count}</span>
                </div>
              </div>

              <div className="flex items-center gap-5 group/info">
                <div className="w-10 h-10 rounded-xl bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-800 flex items-center justify-center text-slate-300 dark:text-slate-600 shadow-inner group-hover/info:text-primary-600 dark:text-primary-400 group-hover/info:bg-primary-50 dark:bg-primary-950 group-hover/info:border-primary-100 dark:border-primary-800 transition-all"><UserCircle size={20} /></div>
                <div>
                  <span className="block text-slate-500 dark:text-slate-400 font-bold uppercase tracking-[0.2em] text-[9px] mb-1">{t("departments.manager_label")}</span>
                  <span className="font-bold text-slate-800 dark:text-slate-100 text-xs uppercase tracking-tight">{users.find(u => u.id === dept.manager_id)?.full_name ?? t("departments.not_assigned").toUpperCase()}</span>
                </div>
              </div>

              <div className="flex items-center gap-5 group/info">
                <div className="w-10 h-10 rounded-xl bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-800 flex items-center justify-center text-slate-300 dark:text-slate-600 shadow-inner group-hover/info:text-primary-600 dark:text-primary-400 group-hover/info:bg-primary-50 dark:bg-primary-950 group-hover/info:border-primary-100 dark:border-primary-800 transition-all"><CalendarDays size={20} /></div>
                <div>
                  <span className="block text-slate-500 dark:text-slate-400 font-bold uppercase tracking-[0.2em] text-[9px] mb-1">{t("departments.default_pattern_label")}</span>
                  <span className="font-bold text-slate-800 dark:text-slate-100 text-xs uppercase tracking-tight">{patterns.find(p => p.id === dept.default_working_pattern_id)?.name ?? t("departments.not_assigned").toUpperCase()}</span>
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>

      <Modal icon={<Calculator size={24} />} isOpen={!!isConfigModalOpen && !!editingDept} maxWidth="3xl" onClose={() => { setIsConfigModalOpen(false); }} subtitle={editingDept?.name.toUpperCase()} title={t("payroll.settings.dept_title")}>
        <div className="space-y-10 pt-4 animate-in fade-in duration-500">
          <TemporalConfigTable isLoading={isConfigsLoading} onSave={async (data) => { await saveConfigMutation.mutateAsync(data); }} records={deptConfigs as any[]} title={t("payroll.settings.std_days_history")} />
          <div className="pt-8 border-t border-slate-50 dark:border-slate-800 flex justify-end"><Button onClick={() => { setIsConfigModalOpen(false); }} size="lg" variant="secondary">{t("common.close").toUpperCase()}</Button></div>
        </div>
      </Modal>

      <Modal icon={<LayoutGrid size={24} />} isOpen={isModalOpen} maxWidth="lg" onClose={() => { setIsModalOpen(false); }} subtitle={t("departments.modal.subtitle")} title={editingDept ? t("departments.modal.edit_title") : t("departments.modal.add_title")}>
        <form className="space-y-8 pt-4 animate-in fade-in duration-500" onSubmit={handleSubmit}>
          <FormField defaultValue={editingDept?.name} id="dept-name" label={t("departments.form.name_label")} name="name" placeholder={t("departments.form.name_placeholder")} required />
          <FormField defaultValue={editingDept?.description ?? undefined} id="dept-desc" label={t("common.description")} name="description" placeholder={t("departments.form.desc_placeholder")} rows={4} type="textarea" />
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="space-y-3 px-1"><label className={LABEL_BASE} htmlFor="dept-manager">{t("departments.manager_label")}</label><Combobox className="bg-slate-50 dark:bg-slate-800 border-slate-100 dark:border-slate-800 h-14" id="dept-manager" onChange={setSelectedManagerId} options={users.map(u => ({ value: u.id, label: (u.full_name ?? u.email).toUpperCase(), icon: <UserCircle size={14} /> }))} placeholder={t("departments.form.manager_placeholder")} value={selectedManagerId} /></div>
            <div className="space-y-3 px-1"><label className={LABEL_BASE} htmlFor="dept-pattern">{t("departments.default_pattern_label")}</label><Combobox className="bg-slate-50 dark:bg-slate-800 border-slate-100 dark:border-slate-800 h-14" data-testid="dept-pattern" id="dept-pattern" onChange={setSelectedPatternId} options={patterns.map(p => ({ value: p.id, label: p.name.toUpperCase(), icon: <CalendarDays size={14} /> }))} placeholder={t("departments.form.pattern_placeholder")} value={selectedPatternId} /></div>
          </div>
          <div className="pt-6 grid grid-cols-2 gap-6 border-t border-slate-50 dark:border-slate-800">
            <Button onClick={() => { setIsModalOpen(false); }} size="lg" variant="outline">{t("common.cancel").toUpperCase()}</Button>
            <Button data-testid="save-dept-btn" size="lg" type="submit" variant="secondary">{editingDept ? t("common.update").toUpperCase() : t("departments.modal.submit_btn").toUpperCase()}</Button>
          </div>
        </form>
      </Modal>
      <ConfirmationDialog />
    </div>
  );
}

import * as Popover from "@radix-ui/react-popover";
import { useQuery, useInfiniteQuery, useMutation, useQueryClient, keepPreviousData } from "@tanstack/react-query";
import {
  Building2,
  UserPlus,
  Upload,
  ArrowUpDown,
  ChevronUp,
  ChevronDown,
  ListFilter,
  Check,
  X,
} from "lucide-react";
import React, { useState, useEffect, useMemo, useRef } from "react";
import { useTranslation } from "react-i18next";

import { format } from "date-fns";

import type { NavigableListColumn } from "@/components/common/navigable-list";

import FloatingRecordBadge from "@/components/common/floating-record-badge";
import NavigableList from "@/components/common/navigable-list";
import PermissionGate from "@/components/common/permission-gate";
import AttendanceImportDialog from "@/components/features/attendance/attendance-import-dialog";
import EmployeeDetailDrawer from "@/components/features/employees/employee-detail-drawer";
import EmployeeFormModal from "@/components/features/employees/employee-form-modal";
import EmploymentHistoryModal from "@/components/features/employees/employment-history-modal";
import RehireEmployeeModal from "@/components/features/employees/rehire-employee-modal";
import TransferEmployeeModal from "@/components/features/employees/transfer-employee-modal";
import Button from "@/components/ui/button";
import PageHeader from "@/components/ui/page-header";
import StatusBadge from "@/components/ui/status-badge";
import { useToast } from "@/components/ui/toast";
import { useConfirm } from "@/hooks/use-confirm";
import { useDateTimeFormatter } from "@/hooks/use-datetime";
import { useDebounce } from "@/hooks/use-debounce";
import { cn } from "@/lib/utils";

import {
  searchEmployees,

  updateEmployee,
  getCurrentWorkspaceId,
  Employee,
  fetchDepartments,
  fetchEmployeeDepartmentHistory,

  fetchEmploymentHistory,

} from "../lib/api";


export default function EmployeesPage() {
  const { t } = useTranslation();
  const wsId = getCurrentWorkspaceId() ?? "";
  const queryClient = useQueryClient();
  const { formatDate } = useDateTimeFormatter();
  const [searchParams] = useState(() => new URLSearchParams(window.location.search));
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isImportDialogOpen, setIsImportDialogOpen] = useState(false);
  const [editingEmployee, setEditingEmployee] = useState<Employee | null>(null);
  const [selectedEmployee, setSelectedEmployee] = useState<Employee | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [filterDeptIds, setFilterDeptIds] = useState<string[]>([]);
  const PAGE_SIZE = 20;
  const [prefillEnrollmentId, setPrefillEnrollmentId] = useState<string>("");
  const { confirm, ConfirmationDialog } = useConfirm();

  // Handle enrollment_id query param from staging logs (read once on mount)
  const [isUrlProcessed, setIsUrlProcessed] = useState(false);
  if (!isUrlProcessed) {
    setIsUrlProcessed(true);
    const enrollmentId = searchParams.get("enrollment_id");
    if (enrollmentId) {
      setPrefillEnrollmentId(enrollmentId);
      setIsModalOpen(true);
      setEditingEmployee(null);
    }
  }

  useEffect(() => {
    const enrollmentId = searchParams.get("enrollment_id");
    if (enrollmentId) {
      // Clear from URL without triggering re-render
      const url = new URL(window.location.href);
      url.searchParams.delete("enrollment_id");
      window.history.replaceState({}, "", url.toString());
    }
  }, [searchParams]);

  const [isTransferModalOpen, setIsTransferModalOpen] = useState(false);
  const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);
  const [isRehireModalOpen, setIsRehireModalOpen] = useState(false);
  const [selectedDeptId, setSelectedDeptId] = useState<string>("");

  const debouncedSearch = useDebounce(searchTerm, 500);

  // Sorting state
  type SortKey = "name" | "id" | "department" | "status";
  type SortDir = "asc" | "desc";
  const [sortKey, setSortKey] = useState<SortKey | null>(null);
  const [sortDir, setSortDir] = useState<SortDir>("asc");

  const toggleSort = (key: SortKey) => {
    if (sortKey === key) {
      setSortDir((d) => (d === "asc" ? "desc" : "asc"));
    } else {
      setSortKey(key);
      setSortDir("asc");
    }
  };

  const renderSortIcon = (col: SortKey) => {
    if (sortKey !== col) return <ArrowUpDown className="opacity-0 group-hover:opacity-50 transition-opacity ml-1" size={10} />;
    return sortDir === "asc" ? <ChevronUp className="text-primary-600 dark:text-primary-400 ml-1" size={10} /> : <ChevronDown className="text-primary-600 dark:text-primary-400 ml-1" size={10} />;
  };

  const {
    data: employeesPages,
    isLoading,
    isFetching,
    isPlaceholderData,
    fetchNextPage,
    hasNextPage,
    isFetchingNextPage,
  } = useInfiniteQuery({
    queryKey: ["employees", wsId, debouncedSearch, sortKey, sortDir, filterDeptIds],
    queryFn: ({ pageParam }) => {
      const apiSortKey = sortKey ? ({ name: "name", id: "employee_id_number", department: "department", status: "status" } as const)[sortKey] : undefined;
      return searchEmployees(wsId, debouncedSearch, pageParam, PAGE_SIZE, apiSortKey, sortDir, filterDeptIds.length > 0 ? filterDeptIds : undefined);
    },
    getNextPageParam: (lastPage, allPages) => {
      const totalLoaded = allPages.reduce((sum, p) => sum + (p.data.length || 0), 0);
      if (totalLoaded >= (lastPage.total || 0)) return undefined;
      return allPages.length + 1;
    },
    initialPageParam: 1,
    enabled: !!wsId,
    placeholderData: keepPreviousData,
  });

  const employees = useMemo(() => {
    if (!employeesPages) return [];
    return employeesPages.pages.flatMap((p) => p.data || []);
  }, [employeesPages]);

  const totalItems = employeesPages?.pages[0]?.total ?? 0;

  const { data: departments } = useQuery({ queryKey: ["departments", wsId], queryFn: () => fetchDepartments(wsId), enabled: !!wsId });

  const toggleDeptFilter = (deptId: string) => {
    setFilterDeptIds(previous =>
      previous.includes(deptId) ? previous.filter(id => id !== deptId) : [...previous, deptId]
    );
  };

  // Column definitions for NavigableList
  const employeeColumns: NavigableListColumn<Employee>[] = [
    {
      key: "name",
      header: <span className="inline-flex items-center">{t("employees.table.name")}{renderSortIcon("name")}</span>,
      onHeaderClick: () => { toggleSort("name"); },
      cell: (emp) => (
        <div className="flex items-center gap-5">
          <div className={cn("w-12 h-12 rounded-2xl flex items-center justify-center font-bold text-sm shadow-inner border transition-all uppercase", selectedEmployee?.id === emp.id ? "bg-primary-600 text-white border-primary-500" : "bg-slate-100 dark:bg-slate-700 text-slate-500 dark:text-slate-400 border-slate-100 dark:border-slate-800 group-hover:bg-white dark:hover:bg-slate-900 group-hover:text-primary-600 dark:group-hover:text-primary-400 group-hover:border-primary-100 dark:border-primary-800")}>{emp.full_name[0]}</div>
          <div>
            <div className="font-bold text-slate-700 dark:text-slate-200 text-sm tracking-tight uppercase leading-none">{emp.full_name}</div>
            <div className="font-mono font-bold text-[10px] text-slate-400 dark:text-slate-500 uppercase tracking-tighter mt-1.5">{emp.employee_id_number}</div>
          </div>
        </div>
      ),
      cellClassName: "py-6",
    },
    {
      key: "department",
      header: (
        <span className="inline-flex items-center gap-2">
          <span className="inline-flex items-center">
            {t("common.department")}{renderSortIcon("department")}
          </span>
          <Popover.Root>
            <Popover.Trigger asChild>
              <button
                className={cn(
                  "relative inline-flex items-center justify-center w-5 h-5 rounded transition-colors",
                  filterDeptIds.length > 0
                    ? "text-primary-600 dark:text-primary-400"
                    : "text-slate-400 dark:text-slate-500 opacity-60 hover:opacity-100 hover:text-primary-600 dark:hover:text-primary-400"
                )}
                data-testid="dept-filter-btn"
                onClick={(e) => { e.stopPropagation(); }}
                title={t("employees.filter_department", "Filter by department")}
                type="button"
              >
                <ListFilter size={12} />
                {filterDeptIds.length > 0 && (
                  <span className="absolute -top-1 -right-1 min-w-[14px] h-[14px] px-0.5 flex items-center justify-center bg-primary-500 text-white text-[8px] font-bold rounded-full leading-none animate-in zoom-in">
                    {filterDeptIds.length}
                  </span>
                )}
              </button>
            </Popover.Trigger>
            <Popover.Portal>
              <Popover.Content
                align="start"
                className="z-[10000] w-56 overflow-hidden rounded-2xl border border-slate-100 dark:border-slate-700 bg-white dark:bg-slate-900 p-2 shadow-2xl dark:shadow-black/30 animate-in fade-in zoom-in-95 duration-200"
                onClick={(e) => { e.stopPropagation(); }}
                sideOffset={8}
              >
                <div className="px-3 pt-2 pb-1.5">
                  <div className="text-[9px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-[0.2em]">
                    {t("employees.filter_department", "Filter by department")}
                  </div>
                </div>
                <div className="max-h-60 overflow-y-auto custom-scrollbar">
                  {/* Clear filter button — only shown when filter is active */}
                  {filterDeptIds.length > 0 && (
                    <button
                      className="flex w-full items-center gap-3 rounded-xl px-3 py-2 text-[11px] font-bold uppercase tracking-wide text-red-500 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-950/30 transition-colors mb-1"
                      onClick={() => { setFilterDeptIds([]); }}
                      type="button"
                    >
                      <X className="shrink-0" size={12} />
                      {t("employees.clear_filter", "Xóa bộ lọc")}
                    </button>
                  )}

                  {departments && departments.length > 0 ? (
                    departments.map(d => {
                      const isChecked = filterDeptIds.includes(d.id);
                      return (
                        <button
                          className={cn(
                            "flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-[11px] font-bold uppercase tracking-wide transition-colors",
                            isChecked
                              ? "bg-primary-50 dark:bg-primary-950 text-primary-600 dark:text-primary-400"
                              : "text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-800"
                          )}
                          data-testid={`dept-filter-option-${d.id}`}
                          key={d.id}
                          onClick={() => { toggleDeptFilter(d.id); }}
                          type="button"
                        >
                          <div className={cn("w-4 h-4 rounded border flex items-center justify-center shrink-0 transition-colors",
                            isChecked
                              ? "bg-primary-600 border-primary-600 text-white"
                              : "border-slate-300 dark:border-slate-600"
                          )}>
                            {!!isChecked && <Check size={10} strokeWidth={3} />}
                          </div>
                          <Building2 className="opacity-50 shrink-0" size={12} />
                          <span className="truncate">{d.name}</span>
                        </button>
                      );
                    })
                  ) : (
                    <div className="px-3 py-6 text-center text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest opacity-60">
                      {t("employees.no_departments", "Chưa có phòng ban")}
                    </div>
                  )}
                </div>
              </Popover.Content>
            </Popover.Portal>
          </Popover.Root>
        </span>
      ),
      onHeaderClick: () => { toggleSort("department"); },
      cell: (emp) => emp.department_name ? (
        <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-blue-50 dark:bg-blue-950 text-blue-600 dark:text-blue-300 rounded-xl text-[10px] font-bold uppercase tracking-widest border border-blue-100 dark:border-blue-800">
          <Building2 className="opacity-60" size={12} />{emp.department_name}
        </span>
      ) : <span className="text-slate-300 dark:text-slate-600">—</span>,
      cellClassName: "py-6",
    },
    {
      key: "status",
      header: <span className="inline-flex items-center">{t("employees.table.status")}{renderSortIcon("status")}</span>,
      onHeaderClick: () => { toggleSort("status"); },
      headerClassName: "text-center",
      cell: (emp) => (
        <StatusBadge variant={emp.is_active ? "success" : "neutral"}>{emp.is_active ? t("employees.table.active").toUpperCase() : t("employees.table.terminated").toUpperCase()}</StatusBadge>
      ),
      cellClassName: "py-6 text-center",
    },
  ];

  const { data: deptHistory } = useQuery({ queryKey: ["deptHistory", selectedEmployee?.id], queryFn: () => fetchEmployeeDepartmentHistory(wsId, selectedEmployee!.id), enabled: !!selectedEmployee });
  const { data: employmentHistory } = useQuery({ queryKey: ["employmentHistory", selectedEmployee?.id], queryFn: () => fetchEmploymentHistory(wsId, selectedEmployee!.id), enabled: !!selectedEmployee });

  const updateMutation = useMutation({
    mutationFn: (data: { id: string; employee: Partial<Employee> }) => updateEmployee(wsId, data.id, data.employee),
    onSuccess: () => { void queryClient.invalidateQueries({ queryKey: ["employees", wsId] }); setIsModalOpen(false); setEditingEmployee(null); toast.success(t("common.success")); },
  });

  const toast = useToast();



  const searchInputRef = useRef<HTMLInputElement>(null);
  const focusSearch = () => setTimeout(() => searchInputRef.current?.focus(), 100);

  const handleDrawerClose = () => {
    setSelectedEmployee(null);
    focusSearch();
  };

  if (isLoading) return <div className="flex h-full items-center justify-center py-32"><div className="animate-spin rounded-full h-12 w-12 border-4 border-primary-600 border-t-transparent shadow-xl"></div></div>;

  return (
    <div className="space-y-10 pb-20 animate-in fade-in duration-700">
      <PageHeader
        actions={
          <>
            <PermissionGate permission="employees:create">
              <Button data-testid="import-employee-btn" icon={<Upload size={18} />} onClick={() => { setIsImportDialogOpen(true); }} variant="outline">{t("employees.bulk_import_btn").toUpperCase()}</Button>
            </PermissionGate>
            <PermissionGate permission="employees:create">
              <Button data-testid="add-employee-btn" icon={<UserPlus size={18} />} onClick={() => { setEditingEmployee(null); setIsModalOpen(true); }}>{t("employees.add_btn").toUpperCase()}</Button>
            </PermissionGate>
          </>
        }
        data-testid="employees-title"
        subtitle={t("employees.subtitle")}
        title={t("employees.title")}
      />

      {/* Active filter chips */}
      {filterDeptIds.length > 0 && !!departments && (
        <div className="flex items-center gap-2 flex-wrap animate-in slide-in-from-top-4 duration-300" data-testid="active-filter-chips">
          <span className="text-[9px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-[0.2em] mr-1">
            {t("employees.filtering_by", "Đang lọc")}
          </span>
          {filterDeptIds.map(id => {
            const dept = departments.find(d => d.id === id);
            if (!dept) return null;
            return (
              <button
                className="inline-flex items-center gap-1.5 px-3 py-1 bg-primary-50 dark:bg-primary-950 text-primary-600 dark:text-primary-400 rounded-full text-[10px] font-bold uppercase tracking-wide border border-primary-100 dark:border-primary-800 hover:bg-primary-100 dark:hover:bg-primary-900 transition-colors group"
                data-testid={`dept-chip-${id}`}
                key={id}
                onClick={() => { toggleDeptFilter(id); }}
                type="button"
              >
                <Building2 className="opacity-60" size={10} />
                {dept.name}
                <X className="opacity-40 group-hover:opacity-100 transition-opacity" size={10} />
              </button>
            );
          })}
          <button
            className="text-[10px] font-bold text-slate-400 dark:text-slate-500 hover:text-red-500 dark:hover:text-red-400 uppercase tracking-wide transition-colors ml-1"
            onClick={() => { setFilterDeptIds([]); }}
            type="button"
          >
            {t("employees.clear_all", "Xóa tất cả")}
          </button>
        </div>
      )}

      <div className={cn("transition-opacity duration-300", isPlaceholderData && isFetching && "opacity-50")}>
      <NavigableList<Employee>
        className="animate-in slide-in-from-bottom-8 duration-700"
        columns={employeeColumns}
        emptyMessage={t("employees.table.no_data")}
        fetchNextPage={fetchNextPage}
        hasNextPage={hasNextPage}
        isFetchingNextPage={isFetchingNextPage}
        isLoading={false}
        itemKey={(emp) => emp.id}
        items={employees}
        maxHeightClass=""
        onSearchChange={setSearchTerm}
        onSelect={(emp) => { setSelectedEmployee(emp); }}
        resetDeps={[searchTerm]}
        rowIdPrefix="employee-row"
        searchInputRef={searchInputRef}
        searchPlaceholder={t("employees.search_placeholder")}
        searchTestId="employee-search"
        searchValue={searchTerm}
        selectedKey={selectedEmployee?.id}
        showChevron
        testIdPrefix="employees-row"
      />
      </div>

      {/* Employee Detail Drawer */}
      <EmployeeDetailDrawer
        departments={departments}
        deptHistory={deptHistory}
        employee={selectedEmployee}
        employmentHistory={employmentHistory}
        formatDate={formatDate}
        isOpen={!!selectedEmployee}
        key={selectedEmployee?.id ?? "closed"}
        onClose={handleDrawerClose}
        onEdit={(emp) => { setEditingEmployee(emp); setIsModalOpen(true); }}
        onRehire={() => { setIsRehireModalOpen(true); }}
        onTerminate={async (emp) => {
          const ok = await confirm({
            title: t("common.warning", { defaultValue: "Warning" }),
            message: t("employees.details.terminate_confirm"),
            variant: "danger"
          });
          if (!ok) return;
          updateMutation.mutate({ id: emp.id, employee: { is_active: false, termination_date: format(new Date(), 'yyyy-MM-dd') } });
        }}
        onTransfer={(deptId) => { setSelectedDeptId(deptId); setIsTransferModalOpen(true); }}
        wsId={wsId}
      />

      {/* Main Employee Form Modal */}
      <EmployeeFormModal
        editingEmployee={editingEmployee}
        isOpen={isModalOpen}
        onClose={() => { setIsModalOpen(false); }}
        onSuccess={() => { setPrefillEnrollmentId(""); }}
        prefillEnrollmentId={prefillEnrollmentId}
        wsId={wsId}
      />

      {/* Transfer Modal */}
      <TransferEmployeeModal
        departments={departments}
        employeeId={selectedEmployee?.id ?? null}
        isOpen={isTransferModalOpen}
        onClose={() => { setIsTransferModalOpen(false); }}
        selectedDeptId={selectedDeptId}
        setSelectedDeptId={setSelectedDeptId}
        wsId={wsId}
      />

      {/* History Modal */}
      <EmploymentHistoryModal
        employmentHistory={employmentHistory}
        formatDate={formatDate}
        isOpen={isHistoryModalOpen}
        onClose={() => { setIsHistoryModalOpen(false); }}
      />

      {/* Rehire Modal */}
      <RehireEmployeeModal
        employeeId={selectedEmployee?.id ?? null}
        isOpen={isRehireModalOpen}
        onClose={() => { setIsRehireModalOpen(false); }}
        onSuccess={(updatedEmp) => { setSelectedEmployee(updatedEmp); }}
        wsId={wsId}
      />

      <FloatingRecordBadge label={t("common.pagination.records")} loaded={employees.length} total={totalItems} />

      <AttendanceImportDialog
        customRequirements={[
          t("employees.import_req.col_a"),
          t("employees.import_req.col_b"),
          t("employees.import_req.col_c"),
          t("employees.import_req.col_d"),
        ]}
        endpoint="/employees/upload"
        isOpen={isImportDialogOpen}
        onClose={() => { setIsImportDialogOpen(false); }}
        targetType="employee"
        title={t("employees.bulk_import_title")}
      />
      <ConfirmationDialog />
    </div>
  );
}

import * as Popover from "@radix-ui/react-popover";
import {
  ChevronLeft,
  ChevronRight,
  Info,
  Calendar,
  Activity,
} from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { startOfMonth, endOfMonth, format, subMonths, addMonths } from "date-fns";

import { MonthYearPicker } from "@/components/common/month-year-picker";
import { ClaimOtDialog } from "@/components/ess/claim-ot-dialog";
import { useDateTimeFormatter } from "@/hooks/use-datetime";
import { useMyAttendance, useMyAttendanceSummaries  } from "@/hooks/use-ess";
import { AttendanceDailySummary } from "@/lib/api/types";
import { cn } from "@/lib/utils";

export default function MyAttendancePage() {

  const { t } = useTranslation();

  const { formatTime, formatDate } = useDateTimeFormatter();

  const [currentMonth, setCurrentMonth] = useState(new Date());



  const startDate = format(startOfMonth(currentMonth), "yyyy-MM-dd");
  const endDate = format(endOfMonth(currentMonth), "yyyy-MM-dd");

  const { entries, isLoading } = useMyAttendance({
    start_date: startDate,
    end_date: endDate,
  });

  const { summaries } = useMyAttendanceSummaries(startDate, endDate);

  const [selectedSummary, setSelectedSummary] = useState<AttendanceDailySummary | null>(null);
  const [claimOpen, setClaimOpen] = useState(false);

  const getSummary = (date: string) => summaries.find(s => s.date === date);



  const handleMonthYearChange = (month: number, year: number) => { setCurrentMonth(new Date(year, month - 1, 1)); };

  const handlePreviousMonth = () => { setCurrentMonth(subMonths(currentMonth, 1)); };

  const handleNextMonth = () => { setCurrentMonth(addMonths(currentMonth, 1)); };



  return (

    <div className="space-y-10 animate-in fade-in duration-700 pb-20">

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-8 px-2">

        <div className="space-y-1">

          <h1 className="text-4xl font-bold tracking-tighter text-slate-700 dark:text-slate-200 uppercase leading-none">{t("ess.attendance.title")}</h1>

          <p className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-[0.25em] opacity-60">{t("ess.attendance.subtitle")}</p>

        </div>



        <div className="flex items-center gap-4 bg-white dark:bg-slate-900 p-2.5 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-xl shadow-slate-900/5">

          <div className="flex items-center bg-slate-100 dark:bg-slate-700/50 rounded-[1.5rem] p-1.5 shadow-inner border border-slate-200 dark:border-slate-700/50">

            <button className="w-12 h-12 flex items-center justify-center text-slate-500 dark:text-slate-400 hover:text-primary-600 dark:text-primary-400 hover:bg-white dark:hover:bg-slate-900 hover:shadow-md rounded-xl transition-all active:scale-90" onClick={handlePreviousMonth}><ChevronLeft size={24} /></button>



            <Popover.Root>

              <Popover.Trigger asChild>

                <button className="px-10 flex flex-col items-center min-w-[200px] cursor-pointer hover:bg-white dark:hover:bg-slate-900 hover:shadow-md rounded-xl transition-all py-2 group outline-none border border-transparent hover:border-slate-100 dark:border-slate-800">

                  <span className="text-[8px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-[0.3em] leading-none mb-1.5 group-hover:text-primary-500 dark:group-hover:text-primary-400 transition-colors">{t("payroll.table.period").toUpperCase()}</span>

                  <span className="text-sm font-bold text-slate-700 dark:text-slate-200 group-hover:text-primary-600 dark:group-hover:text-primary-400 transition-colors uppercase tracking-tight">

                    {format(currentMonth, "MMMM yyyy")}

                  </span>

                </button>

              </Popover.Trigger>

              <Popover.Portal>

                <Popover.Content align="center" className="z-50 w-80 p-4 rounded-[2.5rem] shadow-premium-2xl border border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900 animate-in zoom-in-95 slide-in-from-top-4 origin-top" sideOffset={12}>

                  <MonthYearPicker month={currentMonth.getMonth() + 1} onChange={handleMonthYearChange} year={currentMonth.getFullYear()} />

                </Popover.Content>

              </Popover.Portal>

            </Popover.Root>



            <button className="w-12 h-12 flex items-center justify-center text-slate-500 dark:text-slate-400 hover:text-primary-600 dark:text-primary-400 hover:bg-white dark:hover:bg-slate-900 hover:shadow-md rounded-xl transition-all active:scale-90" onClick={handleNextMonth}><ChevronRight size={24} /></button>

          </div>

        </div>

      </div>



      <div className="bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-[3rem] overflow-hidden shadow-sm animate-in slide-in-from-bottom-8 duration-700">

        {isLoading ? (

          <div className="p-32 flex flex-col items-center gap-6 animate-pulse">

            <div className="w-12 h-12 border-4 border-primary-600 border-t-transparent rounded-full animate-spin"></div>

            <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-[0.3em]">{t("common.loading")}</span>

          </div>

        ) : entries.length === 0 ? (

          <div className="py-40 text-center flex flex-col items-center border-4 border-dashed border-slate-50 dark:border-slate-800 m-8 rounded-[3rem] bg-slate-50 dark:bg-slate-800/30">

            <div className="w-24 h-24 bg-white dark:bg-slate-900 rounded-full flex items-center justify-center shadow-xl border border-slate-100 dark:border-slate-800 mb-8"><Calendar className="text-slate-200 dark:text-slate-700" size={40} /></div>

            <h3 className="text-xl font-bold text-slate-700 dark:text-slate-200 uppercase tracking-tight">{t("ess.attendance.no_data")}</h3>

            <p className="text-slate-500 dark:text-slate-400 text-[10px] font-bold uppercase tracking-widest mt-2 opacity-50 italic">{t("common.no_records_found")}</p>

