        )}
      </div>

      <Modal icon={<Users size={24} />} isOpen={isContactModalOpen} maxWidth="md" onClose={() => { setIsContactModalOpen(false); }} title={t("ess.add_emergency_contact")}>
        <form className="space-y-8 pt-4 animate-in fade-in duration-500" onSubmit={handleAddContact}>
          <div className="space-y-3 px-1">
