            <input className="w-full px-6 py-4 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-800 rounded-2xl focus:ring-4 focus:ring-primary-500/10 focus:bg-white dark:focus:bg-slate-900 outline-none transition-all font-bold text-sm tracking-tight shadow-sm" onChange={(e) => { setNewContact({ ...newContact, contact_name: e.target.value }); }} required type="text" value={newContact.contact_name} />
