                                { value: "user_create", label: `[${t("audit_logs.filters.groups.user_auth")}] ${t("common.create")} ${t("common.user")}` },
                                { value: "user_update", label: `[${t("audit_logs.filters.groups.user_auth")}] ${t("common.update")} ${t("common.user")}` },
                                { value: "user_delete", label: `[${t("audit_logs.filters.groups.user_auth")}] ${t("common.delete")} ${t("common.user")}` },
                                { value: "role_assign", label: `[${t("audit_logs.filters.groups.roles_perms")}] ${t("workspace.roles.title")} ${t("common.assign")}` },
                                { value: "role_revoke", label: `[${t("audit_logs.filters.groups.roles_perms")}] ${t("workspace.roles.title")} ${t("common.revoke")}` },
                                { value: "permission_override_set", label: `[${t("audit_logs.filters.groups.roles_perms")}] ${t("common.permissions")} ${t("common.set")}` },
                                { value: "leave_request_create", label: `[${t("audit_logs.filters.groups.domain")}] ${t("leave.request.create")}` },
                                { value: "leave_request_approve", label: `[${t("audit_logs.filters.groups.domain")}] ${t("leave.request.approve")}` },
                                { value: "attendance_log_create", label: `[${t("audit_logs.filters.groups.domain")}] ${t("attendance.log.create")}` },
                                { value: "shift_swap_request", label: `[${t("audit_logs.filters.groups.domain")}] ${t("attendance.shift_swap.request")}` },
                            ]}
                            placeholder={t("audit_logs.filters.all_actions")}
                            value={actionFilter}
                        />
                        <div className="flex items-center gap-2">
                            <input aria-label={t("audit_logs.filters.start_date")}
                                className="text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-1.5 text-slate-700 dark:text-slate-200 focus:outline-none focus:ring-2 focus:ring-primary-500"
                                onChange={(e) => { setStartDateFilter(e.target.value); setPage(1); }}
                                type="date"
                                value={startDateFilter}
                            />
                            <span className="text-slate-400">-</span>
                            <input aria-label={t("audit_logs.filters.end_date")}
                                className="text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-1.5 text-slate-700 dark:text-slate-200 focus:outline-none focus:ring-2 focus:ring-primary-500"
                                onChange={(e) => { setEndDateFilter(e.target.value); setPage(1); }}
                                type="date"
                                value={endDateFilter}
                            />
                        </div>
                    </div>
                </div>

                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left">
                        <thead className="text-xs text-slate-500 dark:text-slate-400 bg-slate-50 dark:bg-slate-800/50 uppercase">
                            <tr>
                                <th className="px-6 py-3 font-medium">{t("audit_logs.table.timestamp")}</th>
                                <th className="px-6 py-3 font-medium">{t("audit_logs.table.action")}</th>
                                <th className="px-6 py-3 font-medium">{t("audit_logs.table.actor_target")}</th>
                                <th className="px-6 py-3 font-medium">{t("audit_logs.table.details")}</th>
                                <th className="px-6 py-3 font-medium">{t("audit_logs.table.context")}</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-200 dark:divide-slate-800">
                            {isLoading ? (
                                Array.from({ length: 5 }).map((_, index) => (
                                    <tr className="animate-pulse bg-slate-50 dark:bg-slate-800/30" key={index}>
                                        <td className="px-6 py-4"><div className="h-4 bg-slate-200 dark:bg-slate-700 rounded w-24"></div></td>
                                        <td className="px-6 py-4"><div className="h-4 bg-slate-200 dark:bg-slate-700 rounded w-20"></div></td>
                                        <td className="px-6 py-4"><div className="h-4 bg-slate-200 dark:bg-slate-700 rounded w-32"></div></td>
                                        <td className="px-6 py-4"><div className="h-4 bg-slate-200 dark:bg-slate-700 rounded w-48"></div></td>
                                        <td className="px-6 py-4"><div className="h-4 bg-slate-200 dark:bg-slate-700 rounded w-16"></div></td>
                                    </tr>
                                ))
                            ) : isError ? (
                                <tr>
                                    <td className="px-6 py-8 text-center text-red-500 dark:text-red-400" colSpan={5}>
                                        {t("audit_logs.messages.error_loading")}
                                    </td>
                                </tr>
                            ) : !data || data.data.length === 0 ? (
                                <tr>
                                    <td className="px-6 py-12 text-center text-slate-500 dark:text-slate-400" colSpan={5}>
                                        {t("audit_logs.messages.no_logs")}
                                    </td>
                                </tr>
                            ) : (
                                data.data.map((log: AuditLog) => (
                                    <tr className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors" key={log.id}>
                                        <td className="px-6 py-4 whitespace-nowrap text-slate-500 dark:text-slate-400">
                                            {formatDateTime(log.created_at, i18n.language)}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap">
                                            <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium border ${getBadgeColor(log.action)}`}>
                                                {formatActionName(log.action)}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4">
                                            <div className="space-y-1">
                                                <div className="flex items-center gap-1.5 text-slate-900 dark:text-slate-200 font-medium">
                                                    <User className="h-3.5 w-3.5 text-slate-400" />
                                                    <span title={log.actor_id}>
                                                        {log.actor_id ? log.actor_id.substring(0, 8) + '...' : t("audit_logs.messages.system")}
                                                    </span>
                                                </div>
                                                {!!log.target_user_id && (
                                                    <div className="text-xs text-slate-500 dark:text-slate-400 flex items-center gap-1.5">
                                                        {t("audit_logs.messages.target")} <span className="font-mono bg-slate-100 dark:bg-slate-800 px-1 rounded" title={log.target_user_id}>{log.target_user_id.substring(0, 8)}...</span>
                                                    </div>
                                                  )}
                                            </div>
                                        </td>
                                        <td className="px-6 py-4 max-w-[300px]">
                                            {log.details ? (
                                                <pre className="text-xs bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 p-2 rounded-md overflow-x-auto whitespace-pre-wrap font-mono border border-slate-200 dark:border-slate-700">
                                                    {JSON.stringify(log.details, null, 2)}
                                                </pre>
                                            ) : (
                                                <span className="text-xs text-slate-400 dark:text-slate-500 italic">{t("audit_logs.messages.no_details")}</span>
                                            )}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap">
                                            <div className="space-y-1.5 text-xs text-slate-500 dark:text-slate-400">
                                                {!!log.ip_address && (
                                                    <div className="flex items-center gap-1.5" title="IP Address">
                                                        <Globe className="h-3.5 w-3.5" />
                                                        <span className="truncate w-24">{log.ip_address}</span>
                                                    </div>
                                                  )}
                                                {!!log.user_agent && (
                                                    <div className="flex items-center gap-1.5" title={log.user_agent}>
                                                        <Monitor className="h-3.5 w-3.5" />
                                                        <span className="truncate w-24">{log.user_agent}</span>
                                                    </div>
                                                  )}
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>

                {!!data && data.total > 0 && (
                    <div className="border-t border-slate-200 dark:border-slate-800 px-6 py-4 flex items-center justify-between bg-slate-50/50 dark:bg-slate-800/10">
                        <div className="text-sm text-slate-500 dark:text-slate-400">
                            {t("audit_logs.pagination.showing")} <span className="font-medium text-slate-900 dark:text-white">{((page - 1) * limit) + 1}</span> {t("audit_logs.pagination.to")} <span className="font-medium text-slate-900 dark:text-white">{Math.min(page * limit, data.total)}</span> {t("audit_logs.pagination.of")} <span className="font-medium text-slate-900 dark:text-white">{data.total}</span> {t("audit_logs.pagination.entries")}
                        </div>
                        <div className="flex items-center gap-2">
                            <button
                                className="flex items-center justify-center h-8 px-3 rounded-md border border-slate-200 dark:border-slate-700 text-sm font-medium text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-800 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                                disabled={page === 1 || isLoading}
                                onClick={() => { setPage(p => Math.max(1, p - 1)); }}
                            >
                                <ChevronLeft className="h-4 w-4 mr-1" />
                                {t("audit_logs.pagination.previous")}
                            </button>
                            <button
                                className="flex items-center justify-center h-8 px-3 rounded-md border border-slate-200 dark:border-slate-700 text-sm font-medium text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-800 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                                disabled={page * limit >= data.total || isLoading}
                                onClick={() => { setPage(p => p + 1); }}
                            >
                                {t("audit_logs.pagination.next")}
                                <ChevronRight className="h-4 w-4 ml-1" />
                            </button>
                        </div>
                    </div>
                  )}
            </div>
        </div>
    );
}

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Settings2, Save, Clock, Palette, Globe, Calendar, Languages, Sun, Moon, Monitor } from "lucide-react";
import { useState, useEffect } from "react";
import { useTranslation } from "react-i18next";

import type { ThemeMode } from "@/hooks/use-dark-mode";

import Button from "@/components/ui/button";
import { Combobox } from "@/components/ui/combobox";
import { LABEL_BASE } from "@/components/ui/form-field";
import { useToast } from "@/components/ui/toast";
import { useDarkModeContext } from "@/context/use-dark-mode-context";
import { useTheme } from "@/hooks/use-theme";
import { fetchWorkspace, updateWorkspace, getCurrentWorkspaceId, Workspace } from "@/lib/api";
import { cn } from "@/lib/utils";

type TabType = "localization" | "appearance";

export default function GeneralSettings() {
  const wsId = getCurrentWorkspaceId();

  const { data: workspace, isLoading: isLoadingWs } = useQuery({
    queryKey: ["workspace", wsId],
    queryFn: () => fetchWorkspace(wsId!),
    enabled: !!wsId,
  });

  if (isLoadingWs) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary-600"></div>
      </div>
    );
  }

  if (!workspace) return null;

  return <GeneralSettingsContent key={workspace.id} workspace={workspace} />;
}

function GeneralSettingsContent({ workspace }: { workspace: Workspace }) {
  const { t } = useTranslation();
  const wsId = workspace.id;
  const queryClient = useQueryClient();
  const toast = useToast();
  const { setPreviewTheme } = useTheme();

  const [activeTab, setActiveTab] = useState<TabType>("localization");
  const [dateFormat, setDateFormat] = useState(workspace.date_format);
  const [timeFormat, setTimeFormat] = useState(workspace.time_format);
  const [timezone, setTimezone] = useState(workspace.timezone);
  const [themePrimaryColor, setThemePrimaryColor] = useState(workspace.theme_primary_color);
  const [defaultLanguage, setDefaultLanguage] = useState(workspace.default_language);

  useEffect(() => {
    setPreviewTheme(themePrimaryColor);
    return () => { setPreviewTheme(null); };
  }, [themePrimaryColor, setPreviewTheme]);

  const updateWsMutation = useMutation({
    mutationFn: (data: Partial<Workspace>) => updateWorkspace(wsId, data),
    onSuccess: () => {
      toast.success(t("common.success"));
      void queryClient.invalidateQueries({ queryKey: ["workspace", wsId] });
      void queryClient.invalidateQueries({ queryKey: ["workspaces"] });
    },
  });

  function handleSaveConfig() {
    updateWsMutation.mutate({ date_format: dateFormat, time_format: timeFormat, timezone: timezone, theme_primary_color: themePrimaryColor, default_language: defaultLanguage });
  }

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 px-2">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 rounded-[1.25rem] bg-primary-50 dark:bg-primary-950 flex items-center justify-center text-primary-600 dark:text-primary-400 shadow-sm border border-primary-100 dark:border-primary-800/50"><Settings2 size={24} /></div>
          <div>
            <h1 className="text-3xl font-bold tracking-tight text-slate-700 dark:text-slate-200 leading-tight" data-testid="general-settings-title">{t("common.settings.categories.general")}</h1>
            <p className="text-slate-500 dark:text-slate-400 mt-1 font-medium">{t("common.workspace_settings.description")}</p>
          </div>
        </div>
        <Button icon={<Save size={18} />} loading={updateWsMutation.isPending} onClick={handleSaveConfig}>{t("common.workspace_settings.save_config").toUpperCase()}</Button>
      </div>

      <div className="flex bg-slate-100 dark:bg-slate-700/50 p-1.5 rounded-[22px] w-fit border border-slate-200 dark:border-slate-700/50 shadow-inner">
        <button className={cn("flex items-center gap-2 px-8 py-2.5 rounded-[18px] text-xs font-bold uppercase tracking-widest transition-all", activeTab === 'localization' ? "bg-white dark:bg-slate-900 text-primary-600 dark:text-primary-400 shadow-sm border border-slate-100 dark:border-slate-800" : "text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200 dark:text-slate-700")} onClick={() => { setActiveTab("localization"); }}><Globe size={14} /> {t("common.settings.tabs.localization")}</button>
        <button className={cn("flex items-center gap-2 px-8 py-2.5 rounded-[18px] text-xs font-bold uppercase tracking-widest transition-all", activeTab === 'appearance' ? "bg-white dark:bg-slate-900 text-primary-600 dark:text-primary-400 shadow-sm border border-slate-100 dark:border-slate-800" : "text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200 dark:text-slate-700")} onClick={() => { setActiveTab("appearance"); }}><Palette size={14} /> {t("common.settings.tabs.appearance")}</button>
      </div>

      <div className="animate-in slide-in-from-bottom-4 duration-500">
        {activeTab === "localization" && (
          <div className="bg-white dark:bg-slate-900 p-10 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-sm space-y-10">
            <div className="flex items-center gap-3 border-b border-slate-50 dark:border-slate-800 pb-6"><Globe className="w-6 h-6 text-indigo-500" /><h2 className="text-xl font-bold text-slate-800 dark:text-slate-100 tracking-tight uppercase">{t("common.workspace_settings.general_config")}</h2></div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
              <div className="space-y-3">
                <label className={LABEL_BASE}>{t("common.workspace_settings.date_format")}</label>
                <Combobox className="bg-slate-50 dark:bg-slate-800 border-slate-100 dark:border-slate-800 h-14" onChange={setDateFormat} options={[{ value: "DD/MM/YYYY", label: "DD/MM/YYYY", description: t("common.workspace_settings.date_format_options.vn"), icon: <Calendar size={14} /> }, { value: "MM/DD/YYYY", label: "MM/DD/YYYY", description: t("common.workspace_settings.date_format_options.us"), icon: <Calendar size={14} /> }, { value: "YYYY-MM-DD", label: "YYYY-MM-DD", description: t("common.workspace_settings.date_format_options.iso"), icon: <Calendar size={14} /> }]} value={dateFormat} />
              </div>
              <div className="space-y-3">
                <label className={LABEL_BASE}>{t("common.workspace_settings.time_format")}</label>
                <Combobox className="bg-slate-50 dark:bg-slate-800 border-slate-100 dark:border-slate-800 h-14" onChange={setTimeFormat} options={[{ value: "24h", label: t("common.workspace_settings.time_format_options.24h"), description: t("common.workspace_settings.time_format_options.example_24h"), icon: <Clock size={14} /> }, { value: "12h", label: t("common.workspace_settings.time_format_options.12h"), description: t("common.workspace_settings.time_format_options.example_12h"), icon: <Clock size={14} /> }]} value={timeFormat} />
              </div>
              <div className="space-y-3">
                <label className={LABEL_BASE}>{t("common.workspace_settings.timezone")}</label>
                <Combobox className="bg-slate-50 dark:bg-slate-800 border-slate-100 dark:border-slate-800 h-14" onChange={setTimezone} options={[{ value: "Asia/Ho_Chi_Minh", label: "Asia/Ho_Chi_Minh", description: t("common.workspace_settings.timezone_options.vn"), icon: <Globe size={14} /> }, { value: "Asia/Bangkok", label: "Asia/Bangkok", description: t("common.workspace_settings.timezone_options.th"), icon: <Globe size={14} /> }, { value: "UTC", label: t("common.workspace_settings.timezone_options.utc"), icon: <Globe size={14} /> }]} value={timezone} />
              </div>
              <div className="space-y-3">
                <label className={LABEL_BASE}>{t("common.workspace_settings.default_language")}</label>
                <Combobox className="bg-slate-50 dark:bg-slate-800 border-slate-100 dark:border-slate-800 h-14" onChange={setDefaultLanguage} options={[{ value: "vi", label: t("common.languages.vi"), icon: <Languages size={14} /> }, { value: "en", label: t("common.languages.en"), icon: <Languages size={14} /> }, { value: "zh", label: t("common.languages.zh"), icon: <Languages size={14} /> }]} value={defaultLanguage} />
              </div>
            </div>
          </div>
        )}

        {activeTab === "appearance" && (
          <div className="bg-white dark:bg-slate-900 p-10 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-sm space-y-10">
            <div className="flex items-center gap-3 border-b border-slate-50 dark:border-slate-800 pb-6"><Palette className="w-6 h-6 text-pink-500" /><h2 className="text-xl font-bold text-slate-800 dark:text-slate-100 tracking-tight uppercase">{t("common.workspace_settings.theme_config")}</h2></div>
            <div className="space-y-10">
              <div className="space-y-6">
                <label className={LABEL_BASE}>{t("common.workspace_settings.primary_color")}</label>
                <div className="flex flex-wrap gap-5 items-center">
                  {[
                    { name: t("common.colors.emerald"), color: '#10b981' }, { name: t("common.colors.indigo"), color: '#4f46e5' }, { name: t("common.colors.blue"), color: '#2563eb' },
                    { name: t("common.colors.emerald"), color: '#059669' }, { name: t("common.colors.amber"), color: '#d97706' }, { name: t("common.colors.rose"), color: '#e11d48' }, { name: t("common.colors.slate"), color: '#475569' },
                  ].map((preset) => (
                    <button className={cn("w-14 h-14 rounded-2xl transition-all border-4 flex items-center justify-center shadow-lg group active:scale-90", themePrimaryColor === preset.color ? 'border-slate-900 scale-110' : 'border-white hover:scale-105 hover:border-slate-100 dark:border-slate-800')} key={preset.color} onClick={() => { setThemePrimaryColor(preset.color); }} style={{ backgroundColor: preset.color }} title={preset.name}>
                      {themePrimaryColor === preset.color && <div className="w-3 h-3 bg-white dark:bg-slate-900 rounded-full shadow-2xl animate-in zoom-in duration-300" />}
                    </button>
                  ))}
                  <div className="h-12 w-px bg-slate-100 dark:bg-slate-700 mx-2" />
                  <div className="flex items-center gap-4 bg-slate-50 dark:bg-slate-800 p-2.5 rounded-[1.5rem] border border-slate-100 dark:border-slate-800 shadow-inner group">
                    <input className="w-12 h-12 rounded-xl cursor-pointer bg-transparent border-none p-0 overflow-hidden" onChange={(e) => { setThemePrimaryColor(e.target.value); }} type="color" value={themePrimaryColor} />
                    <input className="bg-transparent border-none text-sm font-mono font-bold text-slate-600 dark:text-slate-300 w-24 outline-none tracking-tighter" onChange={(e) => { setThemePrimaryColor(e.target.value); }} type="text" value={themePrimaryColor} />
                  </div>
                </div>
              </div>
              <div className="p-8 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-800 rounded-[2rem] shadow-inner"><p className="text-[11px] font-bold text-slate-500 dark:text-slate-400 leading-relaxed italic uppercase tracking-tight opacity-80">{t("common.workspace_settings.theme_desc")}</p></div>

              {/* Dark Mode Preference */}
              <DarkModeSelector />
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

/** Dark mode preference selector with light/system/dark options */
function DarkModeSelector() {
  const { t } = useTranslation();
  const { mode, setMode } = useDarkModeContext();

  const options: { value: ThemeMode; icon: React.ReactNode; label: string; desc: string }[] = [
    { value: 'light', icon: <Sun size={20} />, label: t('common.theme.light', 'Light'), desc: t('common.theme.light_desc', 'Always use light mode') },
    { value: 'system', icon: <Monitor size={20} />, label: t('common.theme.system', 'System'), desc: t('common.theme.system_desc', 'Follow system preference') },
    { value: 'dark', icon: <Moon size={20} />, label: t('common.theme.dark', 'Dark'), desc: t('common.theme.dark_desc', 'Always use dark mode') },
  ];

  return (
    <div className="space-y-6">
      <label className={LABEL_BASE}>{t('common.theme.mode', 'Dark Mode')}</label>
      <div className="grid grid-cols-3 gap-4" data-testid="dark-mode-selector">
        {options.map((opt) => (
          <button
            className={cn(
              "flex flex-col items-center gap-3 p-6 rounded-2xl border-2 transition-all active:scale-95",
              mode === opt.value
                ? "border-primary-500 bg-primary-50 dark:bg-primary-950 text-primary-600 dark:text-primary-400 shadow-lg shadow-primary-100 dark:shadow-black/30"
                : "border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900 text-slate-400 dark:text-slate-500 hover:border-slate-200 dark:hover:border-slate-700 hover:text-slate-600 dark:hover:text-slate-300"
            )}
            data-testid={`dark-mode-option-${opt.value}`}
            key={opt.value}
            onClick={() => { setMode(opt.value); }}
          >
            {opt.icon}
            <span className="text-xs font-bold uppercase tracking-widest">{opt.label}</span>
            <span className="text-[10px] text-slate-500 dark:text-slate-400 font-medium">{opt.desc}</span>
          </button>
        ))}
      </div>
    </div>
  );
}

import { useQuery } from "@tanstack/react-query";
import { Plus, Trash2, Pencil, CalendarDays, ChevronLeft, ChevronRight, Info } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import type { Holiday } from "@/lib/api/types";

import { Combobox } from "@/components/ui/combobox";
import { useConfirm } from "@/hooks/use-confirm";
import { getCurrentWorkspaceId } from "@/lib/api";
import { fetchHolidays, createHoliday, updateHoliday, deleteHoliday } from "@/lib/api/holidays";
import { fetchLeaveTypes } from "@/lib/api/leaves";

export default function HolidaysPage() {
    const { t } = useTranslation();
    const [year, setYear] = useState(new Date().getFullYear());
    const [showForm, setShowForm] = useState(false);
    const [editingHoliday, setEditingHoliday] = useState<Holiday | null>(null);
    const [error, setError] = useState<string | null>(null);
    const { confirm, ConfirmationDialog } = useConfirm();

    // Form state
    const [formName, setFormName] = useState("");
    const [formDate, setFormDate] = useState("");
    const [formType, setFormType] = useState("national");
    const [formIsPaid, setFormIsPaid] = useState(true);
    const [formLeaveTypeId, setFormLeaveTypeId] = useState("");
    const [formOtMultiplier, setFormOtMultiplier] = useState("");
    const [formDescription, setFormDescription] = useState("");
    const [formIsCreditOnWork, setFormIsCreditOnWork] = useState(true);
    const [formThresholdPercent, setFormThresholdPercent] = useState("");

    const wsId = getCurrentWorkspaceId();

    const { data: holidays = [], isLoading, refetch: loadHolidays } = useQuery({
        queryKey: ["holidays", wsId, year],
        queryFn: () => fetchHolidays(wsId!, year),
        enabled: !!wsId
    });

    const { data: leaveTypes = [] } = useQuery({
        queryKey: ["leaveTypes", wsId],
        queryFn: () => fetchLeaveTypes(wsId!),
        enabled: !!wsId
    });

    const resetForm = () => {
        setFormName("");
        setFormDate("");
        setFormType("national");
        setFormIsPaid(true);
        setFormLeaveTypeId("");
        setFormOtMultiplier("");
        setFormDescription("");
        setFormIsCreditOnWork(true);
        setFormThresholdPercent("");
        setEditingHoliday(null);
        setShowForm(false);
        setError(null);
    };

    const openEdit = (h: Holiday) => {
        setEditingHoliday(h);
        setFormName(h.name);
        setFormDate(h.date);
        setFormType(h.holiday_type);
        setFormIsPaid(h.is_paid);
        setFormLeaveTypeId(h.leave_type_id ?? "");
        setFormOtMultiplier(h.ot_multiplier?.toString() ?? "");
        setFormDescription(h.description ?? "");
        setFormIsCreditOnWork(h.is_credit_on_work ?? true);
        setFormThresholdPercent(h.work_threshold_percent?.toString() ?? "");
        setShowForm(true);
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        const currentWsId = wsId;
        if (!currentWsId) return;
        setError(null);


        const payload = {
            name: formName,
            date: formDate,
            holiday_type: formType,
            is_paid: formIsPaid,
            leave_type_id: !formIsPaid && formLeaveTypeId ? formLeaveTypeId : null,
            description: formDescription || undefined,
            ot_multiplier: formOtMultiplier ? parseFloat(formOtMultiplier) : undefined,
            is_credit_on_work: formIsCreditOnWork,
            work_threshold_percent: formThresholdPercent ? parseInt(formThresholdPercent) : null,
        } as Parameters<typeof createHoliday>[1];

        try {
            if (editingHoliday) {
                await updateHoliday(currentWsId, editingHoliday.id, payload);
            } else {
                await createHoliday(currentWsId, payload);
            }
            resetForm();

            void loadHolidays();
        } catch (error_: unknown) {
            setError(error_ instanceof Error ? error_.message : t('holidays.messages.save_error'));
        }
    };

    const handleDelete = async (id: string) => {
        if (!wsId) return;
        const ok = await confirm({
            title: t('common.confirm_delete', 'Confirm Delete'),
            message: t('holidays.messages.confirm_delete'),
            variant: 'danger'
        });
        if (!ok) return;
        try {
            await deleteHoliday(wsId, id);
            void loadHolidays();
        } catch {
            setError(t('holidays.messages.delete_error'));
        }
    };

    return (
        <div className="space-y-8">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-2xl font-bold text-slate-900 dark:text-white tracking-tight">
                        🏖️ {t('holidays.title')}
                    </h1>
                    <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">
                        {t('holidays.subtitle')}
                    </p>
                </div>
                <button
                    className="flex items-center gap-2 px-4 py-2 bg-primary-600 text-white rounded-xl font-bold text-sm hover:bg-primary-700 transition-colors shadow-sm"
                    onClick={() => { resetForm(); setShowForm(true); }}
                >
                    <Plus size={16} />
                    {t('holidays.add_btn')}
                </button>
            </div>

            {/* Year Navigation */}
            <div className="flex items-center justify-center gap-4">
                <button
                    className="p-2 rounded-lg bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors"
                    onClick={() => { setYear(y => y - 1); }}
                >
                    <ChevronLeft size={16} />
                </button>
                <span className="text-xl font-bold text-slate-900 dark:text-white tabular-nums">
                    {year}
                </span>
                <button
                    className="p-2 rounded-lg bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors"
                    onClick={() => { setYear(y => y + 1); }}
                >
                    <ChevronRight size={16} />
                </button>
            </div>

            {/* Error */}
            {!!error && (
                <div className="p-3 bg-rose-50 dark:bg-rose-950 border border-rose-200 dark:border-rose-800 rounded-xl text-rose-600 dark:text-rose-300 text-sm font-medium">
                    {error}
                </div>
              )}

            {/* Form Modal */}
            {!!showForm && (
                <div className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 p-6 shadow-lg">
                    <h2 className="text-lg font-bold text-slate-900 dark:text-white mb-4">
                        {editingHoliday ? t('holidays.modal_title_edit') : t('holidays.modal_title_new')}
                    </h2>
                    <form className="space-y-4" onSubmit={handleSubmit}>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider mb-1">
                                    {t('holidays.fields.name')} *
                                </label>
                                <input
                                    className="w-full px-3 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm"
                                    onChange={(e) => { setFormName(e.target.value); }}
                                    placeholder={t('holidays.fields.name_placeholder')}
                                    required
                                    type="text"
                                    value={formName}
                                />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider mb-1">
                                    {t('holidays.fields.date')} *
                                </label>
                                <input
                                    className="w-full px-3 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm"
                                    onChange={(e) => { setFormDate(e.target.value); }}
                                    required
                                    type="date"
                                    value={formDate}
                                />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider mb-1">
                                    {t('holidays.fields.type')}
                                </label>
                                <Combobox
                                    className="w-full border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm py-[7px]"
                                    onChange={setFormType}
                                    options={[
                                        { value: "national", label: t('holidays.fields.types.national') },
                                        { value: "company", label: t('holidays.fields.types.company') },
                                        { value: "regional", label: t('holidays.fields.types.regional') },
                                    ]}
                                    placeholder={t('holidays.fields.type')}
                                    value={formType}
                                />
                            </div>
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider mb-1">
                                {t('holidays.fields.description')}
                            </label>
                            <input
                                className="w-full px-3 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm"
                                onChange={(e) => { setFormDescription(e.target.value); }}
                                placeholder={t('holidays.fields.description_placeholder')}
                                type="text"
                                value={formDescription}
                            />
                        </div>
                        <div className="flex items-center gap-2">
                            <input
                                checked={formIsPaid}
                                className="rounded"
                                id="isPaid"
                                onChange={(e) => { setFormIsPaid(e.target.checked); if (e.target.checked) setFormLeaveTypeId(""); }}
                                type="checkbox"
                            />
                            <label className="text-sm text-slate-700 dark:text-slate-300" htmlFor="isPaid">
                                {t('holidays.fields.paid_holiday')}
                            </label>
                        </div>
                        {!formIsPaid && (
                            <div className="space-y-3">
                                <div className="p-3 bg-blue-50 dark:bg-blue-900/30 border border-blue-200 dark:border-blue-800/50 rounded-xl flex items-start gap-3">
                                    <Info className="w-5 h-5 text-blue-500 dark:text-blue-400 mt-0.5 shrink-0" />
                                    <div>
                                        <h4 className="text-sm font-bold text-blue-900 dark:text-blue-200 mb-1">
                                            {t('holidays.info.title')}
                                        </h4>
                                        <p className="text-xs text-blue-800 dark:text-blue-300 font-medium mb-2">
                                            {t('holidays.info.body_1')}
                                        </p>
                                        <ul className="text-xs text-blue-800 dark:text-blue-300 space-y-1 list-disc list-inside">
                                            <li><span className="font-bold">{t('holidays.info.rule_1').split(':')[0]}:</span> {t('holidays.info.rule_1').split(':')[1]}</li>
                                            <li><span className="font-bold">{t('holidays.info.rule_2').split(':')[0]}:</span> {t('holidays.info.rule_2').split(':')[1]}</li>
                                        </ul>
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider mb-1">
                                        {t('holidays.fields.deduct_leave_type')}
                                    </label>
                                    <Combobox
                                        className="w-full border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm py-[7px]"
                                        onChange={setFormLeaveTypeId}
                                        options={leaveTypes.filter(lt => lt.is_paid).map(lt => ({
                                            value: lt.id,
                                            label: `${lt.name} (${lt.code})`
                                        }))}
                                        placeholder={t('holidays.fields.auto_first_paid')}
                                        value={formLeaveTypeId}
                                    />
                                    <p className="text-xs text-amber-600 dark:text-amber-400 mt-1">
                                        ⚠️ {t('holidays.fields.deduction_warning')}
                                    </p>
                                </div>
                            </div>
                        )}
                        {/* Work Policy Section */}
                        <div className="mt-2 p-4 bg-slate-50 dark:bg-slate-800/50 rounded-xl border border-slate-200 dark:border-slate-700">
                            <h3 className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider mb-3 flex items-center gap-1.5">
                                ⚙️ {t('holidays.fields.work_policy_title', 'Chính sách khi NV đi làm ngày lễ')}
                            </h3>
                            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                                <div className="flex items-start gap-2">
                                    <input
                                        checked={formIsCreditOnWork}
                                        className="rounded mt-0.5"
                                        id="isCreditOnWork"
                                        onChange={(e) => { setFormIsCreditOnWork(e.target.checked); }}
                                        type="checkbox"
                                    />
                                    <div>
                                        <label className="text-sm text-slate-700 dark:text-slate-300 font-medium" htmlFor="isCreditOnWork">
                                            {t('holidays.fields.credit_on_work', 'Credit lương ngày lễ')}
                                        </label>
                                        <p className="text-[10px] text-slate-400">
                                            {t('holidays.fields.credit_on_work_help', 'NV vẫn nhận lương ngày lễ + lương giờ làm')}
                                        </p>
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider mb-1">
                                        {t('holidays.fields.threshold_percent', 'Ngưỡng hoàn phép')} (%)
                                    </label>
                                    <input
                                        className="w-full px-3 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm"
                                        max={100}
                                        min={0}
                                        onChange={(e) => { setFormThresholdPercent(e.target.value); }}
                                        placeholder="50"
                                        type="number"
                                        value={formThresholdPercent}
                                    />
                                    <p className="text-[10px] text-slate-400 mt-0.5">
                                        {t('holidays.fields.threshold_help', 'NV làm ≥ ngưỡng → hoàn phép. < ngưỡng → giữ phép')}
                                    </p>
                                </div>
                                <div>
                                    <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider mb-1">
                                        {t('holidays.fields.ot_multiplier', 'Hệ số nhân giờ làm')}
                                    </label>
                                    <input
                                        className="w-full px-3 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm"
                                        onChange={(e) => { setFormOtMultiplier(e.target.value); }}
                                        placeholder={t('holidays.fields.ot_multiplier_placeholder', '3.0')}
                                        step="0.1"
                                        type="number"
                                        value={formOtMultiplier}
                                    />
                                    <p className="text-[10px] text-slate-400 mt-0.5">
                                        {t('holidays.fields.ot_multiplier_help', 'VD: 3× = 300% lương cho mỗi giờ đi làm')}
                                    </p>
                                </div>
                            </div>
                        </div>
                        <div className="flex gap-2 justify-end">
                            <button
                                className="px-4 py-2 rounded-xl border border-slate-200 dark:border-slate-700 text-sm font-bold text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800"
                                onClick={resetForm}
                                type="button"
                            >
                                {t('common.cancel')}
                            </button>
                            <button
                                className="px-4 py-2 bg-primary-600 text-white rounded-xl font-bold text-sm hover:bg-primary-700 transition-colors"
                                type="submit"
                            >
                                {editingHoliday ? t('common.update') : t('common.create')}
                            </button>
                        </div>
                    </form>
                </div>
              )}

            {/* Holidays Table */}
            <div className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 overflow-hidden shadow-sm">
                {isLoading ? (
                    <div className="p-12 text-center text-slate-400 text-sm font-bold uppercase tracking-widest animate-pulse">
                        {t('common.loading')}
                    </div>
                ) : holidays.length === 0 ? (
                    <div className="p-12 text-center">
                        <CalendarDays className="w-12 h-12 text-slate-300 dark:text-slate-600 mx-auto mb-3" />
                        <p className="text-slate-400 text-sm font-medium">
                            {t('holidays.no_holidays', { year })}
                        </p>
                    </div>
                ) : (
                    <table className="w-full text-left">
                        <thead>
                            <tr className="border-b border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-800/50">
                                <th className="px-4 py-3 text-[10px] font-bold text-slate-500 uppercase tracking-widest">{t('holidays.table.date')}</th>
                                <th className="px-4 py-3 text-[10px] font-bold text-slate-500 uppercase tracking-widest">{t('holidays.table.name')}</th>
                                <th className="px-4 py-3 text-[10px] font-bold text-slate-500 uppercase tracking-widest">{t('holidays.table.type')}</th>
                                <th className="px-4 py-3 text-[10px] font-bold text-slate-500 uppercase tracking-widest text-center">{t('holidays.table.paid')}</th>
                                <th className="px-4 py-3 text-[10px] font-bold text-slate-500 uppercase tracking-widest text-center">{t('holidays.table.ot')}</th>
                                <th className="px-4 py-3 text-[10px] font-bold text-slate-500 uppercase tracking-widest text-center">{t('holidays.table.credit', 'Credit')}</th>
                                <th className="px-4 py-3 text-[10px] font-bold text-slate-500 uppercase tracking-widest text-center">{t('holidays.table.threshold', 'Ngưỡng')}</th>
                                <th className="px-4 py-3 text-[10px] font-bold text-slate-500 uppercase tracking-widest">{t('holidays.table.description')}</th>
                                <th className="px-4 py-3"></th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
                            {holidays.map((h) => (
                                <tr className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors group" key={h.id}>
                                    <td className="px-4 py-3 font-mono text-sm font-bold text-slate-700 dark:text-slate-200">
                                        {h.date}
                                    </td>
                                    <td className="px-4 py-3 font-bold text-slate-900 dark:text-white text-sm">
                                        {h.name}
                                    </td>
                                    <td className="px-4 py-3">
                                        <span className="px-2 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-wide bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 border border-slate-200 dark:border-slate-700">
                                            {t(`holidays.fields.types.${h.holiday_type}`)}
                                        </span>
                                    </td>
                                    <td className="px-4 py-3 text-center">
                                        {h.is_paid ? (
                                            <span className="text-emerald-600">✅ {t('holidays.table.paid_status')}</span>
                                        ) : (
                                            <span className="text-amber-600 text-xs font-bold">
                                                ⚡ {t('holidays.table.deduct_leave')}
                                                {!!h.leave_type_id && leaveTypes.find(lt => lt.id === h.leave_type_id) && (
                                                    <span className="block text-[10px] text-slate-400 font-normal">
                                                        → {leaveTypes.find(lt => lt.id === h.leave_type_id)?.name}
                                                    </span>
                                                  )}
                                            </span>
                                        )}
                                    </td>
                                    <td className="px-4 py-3 text-center font-mono font-bold text-sm text-orange-600 dark:text-orange-400">
                                        {h.ot_multiplier ? `${h.ot_multiplier}×` : "—"}
                                    </td>
                                    <td className="px-4 py-3 text-center text-sm">
                                        {h.is_credit_on_work ? (
                                            <span className="text-emerald-600">✅</span>
                                        ) : (
                                            <span className="text-slate-400">❌</span>
                                        )}
                                    </td>
                                    <td className="px-4 py-3 text-center font-mono text-sm text-slate-600 dark:text-slate-400">
                                        {h.work_threshold_percent != null ? `${h.work_threshold_percent}%` : "—"}
                                    </td>
                                    <td className="px-4 py-3 text-xs text-slate-500 dark:text-slate-400 max-w-[200px] truncate">
                                        {h.description ?? "—"}
                                    </td>
                                    <td className="px-4 py-3">
                                        <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                            <button
                                                className="p-1.5 rounded-lg bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-500 hover:text-primary-600 hover:bg-primary-50 transition-colors"
                                                onClick={() => { openEdit(h); }}
                                            >
                                                <Pencil size={14} />
                                            </button>
                                            <button
                                                className="p-1.5 rounded-lg bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-500 hover:text-rose-600 hover:bg-rose-50 transition-colors"
                                                onClick={() => handleDelete(h.id)}
                                            >
                                                <Trash2 size={14} />
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                )}
            </div>
            <ConfirmationDialog />
        </div>
    );
}

import { useQuery } from "@tanstack/react-query";
import { CalendarDays, ShieldCheck, UserPlus, Info } from "lucide-react";
import React, { useState } from "react";
import { useTranslation } from "react-i18next";

import { format } from "date-fns";

import { AssignPolicyModal } from "@/components/leave/assign-policy-modal";
import { LeavePolicyManager } from "@/components/leave/leave-policy-manager";
import { LeaveTypeManager } from "@/components/leave/leave-type-manager";
import { fetchLeavePolicyAssignments } from "@/lib/api";
import { getCurrentWorkspaceId } from "@/lib/api/helpers";
import { cn } from "@/lib/utils";





type TabType = "types" | "policies" | "assignments";

interface LeaveAssignment {
  assignee_type: string;
  created_at: string;
  effective_from: string;
  effective_to: string | null;
  id: string;
  leave_type_name: string;
  policy_name: string;
}

export default function LeaveSettings() {
  const { t } = useTranslation();
  const wsId = getCurrentWorkspaceId();
  const [activeTab, setActiveTab] = useState<TabType>("types");
  const [isAssignModalOpen, setIsAssignModalOpen] = useState(false);

  const { data: assignments = [], isLoading: assignmentsLoading } = useQuery<LeaveAssignment[]>({
    queryKey: ["leave-assignments", wsId],
    queryFn: () => fetchLeavePolicyAssignments(wsId!),
    enabled: !!wsId && activeTab === "assignments"
  });


  if (!wsId) return null;

  return (
    <div className="space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <header className="flex flex-col gap-2">
        <div className="flex items-center gap-4">
          <div className="bg-primary-600 p-3 rounded-2xl shadow-xl shadow-primary-100 dark:shadow-black/30 rotate-3">
            <CalendarDays className="text-white w-6 h-6" />
          </div>
          <div>
            <h2 className="text-3xl font-bold tracking-tighter text-slate-800 dark:text-slate-100 uppercase leading-none">
