function TimeSettingsContent({ workspace, rules, versions }: { workspace: Workspace; rules: AttendanceRules; versions: AttendancePolicyVersion[] }) {
  const { t } = useTranslation();
  const wsId = workspace.id;
  const queryClient = useQueryClient();
  const toast = useToast();

  const [activeTab, setActiveTab] = useState<TabType>("general");

  const [workUnit, setWorkUnit] = useState(rules.work_unit_minutes ?? 15);
  const [roundingPolicy, setRoundingPolicy] = useState(rules.rounding_policy || "none");
  const [earlyArrivalStrategy, setEarlyArrivalStrategy] = useState(rules.early_arrival_strategy || "block");
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newValidFrom, setNewValidFrom] = useState(() => new Date().toISOString().split("T")[0]);

  // --- Bulk Reprocess State ---
  const [reprocessStart, setReprocessStart] = useState(() => {
    const d = new Date();
    d.setDate(d.getDate() - 30);
    return d.toISOString().split("T")[0];
  });
  const [reprocessEnd, setReprocessEnd] = useState(() => {
    return new Date().toISOString().split("T")[0];
  });
  const [showReprocessConfirm, setShowReprocessConfirm] = useState(false);
  const [pollingJobId, setPollingJobId] = useState<string | null>(null);

  const jobStatusQuery = useQuery({
    queryKey: ["generic-job-status", wsId, pollingJobId],
    queryFn: () => fetchGenericJobStatus(wsId, pollingJobId!),
    enabled: !!pollingJobId,
    refetchInterval: (query: { state: { data?: { status: string } } }) => {
      const data = query.state.data;
      return data && (data.status === "completed" || data.status === "failed") ? false : 3000;
    },
  });

  useEffect(() => {
    if (jobStatusQuery.data) {
      if (jobStatusQuery.data.status === "completed") {
        setTimeout(() => {
          toast.success(t("common.success") + " - Reprocessing finished");
          void queryClient.invalidateQueries({ queryKey: ["attendance-report"] });
          void queryClient.invalidateQueries({ queryKey: ["attendance-logs"] });
          setShowReprocessConfirm(false);
          setPollingJobId(null);
        }, 0);
      } else if (jobStatusQuery.data.status === "failed") {
        setTimeout(() => {
          toast.error("Process failed: " + (jobStatusQuery.data.error ?? "Unknown error"));
          setShowReprocessConfirm(false);
          setPollingJobId(null);
        }, 0);
      }
    }
  }, [jobStatusQuery.data, queryClient, t, toast]);

  const reprocessMutation = useMutation({
    mutationFn: () => reprocessAllAttendance(wsId, reprocessStart, reprocessEnd),
    onSuccess: (data) => {
      setPollingJobId(data.job_id);
    },
    onError: (e: Error) => {
      toast.error(e.message || t("common.error"));
    }
  });

  const handleReprocessSubmit = () => {
    reprocessMutation.mutate();
  };

  const updateRulesMutation = useMutation({
    mutationFn: (data: UpdateAttendanceRulesRequest) => updateDefaultAttendanceRules(wsId, data),
    onSuccess: () => {
      toast.success(t("common.success"));
      void queryClient.invalidateQueries({ queryKey: ["attendance-rules", wsId] });
      void queryClient.invalidateQueries({ queryKey: ["attendance-policy-versions", wsId] });
      setShowCreateModal(false);
    },
  });

  function handleSaveNewVersion() {
    updateRulesMutation.mutate({
      work_unit_minutes: workUnit,
      rounding_policy: roundingPolicy,
      early_arrival_strategy: earlyArrivalStrategy,
      valid_from: newValidFrom,
    });
  }

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 px-2">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 rounded-[1.25rem] bg-primary-50 dark:bg-primary-950 flex items-center justify-center text-primary-600 dark:text-primary-400 shadow-sm border border-primary-100 dark:border-primary-800/50"><Clock size={24} /></div>
          <div>
            <h1 className="text-3xl font-bold tracking-tight text-slate-700 dark:text-slate-200 leading-tight">{t("common.settings.categories.time")}</h1>
            <p className="text-slate-500 dark:text-slate-400 mt-1 font-medium">{t("common.settings.categories.time_desc")}</p>
          </div>
        </div>
        {activeTab === "general" && (
          <Button icon={<Plus size={18} />} onClick={() => { setShowCreateModal(true); setNewValidFrom(new Date().toISOString().split("T")[0]); }}>{t("common.workspace_settings.new_version") || "NEW VERSION"}</Button>
        )}
      </div>

      <div className="flex bg-slate-100 dark:bg-slate-700/50 p-1.5 rounded-[22px] w-fit border border-slate-200 dark:border-slate-700/50 shadow-inner">
        <button className={cn("flex items-center gap-2 px-8 py-2.5 rounded-[18px] text-xs font-bold uppercase tracking-widest transition-all", activeTab === 'general' ? "bg-white dark:bg-slate-900 text-primary-600 dark:text-primary-400 shadow-sm border border-slate-100 dark:border-slate-800" : "text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200 dark:text-slate-700")} onClick={() => { setActiveTab("general"); }}><Settings2 size={14} /> {t("common.settings.tabs.general")}</button>
        <button className={cn("flex items-center gap-2 px-8 py-2.5 rounded-[18px] text-xs font-bold uppercase tracking-widest transition-all", activeTab === 'patterns' ? "bg-white dark:bg-slate-900 text-primary-600 dark:text-primary-400 shadow-sm border border-slate-100 dark:border-slate-800" : "text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200 dark:text-slate-700")} onClick={() => { setActiveTab("patterns"); }}><LayoutGrid size={14} /> {t("common.settings.tabs.patterns")}</button>
        <button className={cn("flex items-center gap-2 px-8 py-2.5 rounded-[18px] text-xs font-bold uppercase tracking-widest transition-all", activeTab === 'rules' ? "bg-white dark:bg-slate-900 text-primary-600 dark:text-primary-400 shadow-sm border border-slate-100 dark:border-slate-800" : "text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200 dark:text-slate-700")} onClick={() => { setActiveTab("rules"); }}><Zap size={14} /> {t("common.settings.tabs.rules")}</button>
      </div>

      <div className="animate-in slide-in-from-bottom-4 duration-500">
        {activeTab === "general" && (
          <>
            <AttendanceVersionTimeline t={t} versions={versions} />
            <PolicyAssignmentsSection wsId={wsId} />
            <BulkReprocessSection reprocessEnd={reprocessEnd} reprocessStart={reprocessStart} setReprocessEnd={setReprocessEnd} setReprocessStart={setReprocessStart} setShowReprocessConfirm={setShowReprocessConfirm} t={t} />

            <Modal icon={<Plus size={24} />} isOpen={showCreateModal} maxWidth="xl" onClose={() => { setShowCreateModal(false); }} subtitle={t("common.workspace_settings.new_version_desc") || "Create a new configuration version with an effective date"} title={t("common.workspace_settings.new_version") || "New Attendance Config"}>
              <div className="space-y-8 pt-4 animate-in fade-in duration-500">
                <div className="space-y-3 px-1">
                  <label className={LABEL_BASE}>{t("common.workspace_settings.valid_from") || "Effective From"}</label>
                  <input className="w-full px-6 py-4 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-800 rounded-2xl focus:ring-4 focus:ring-primary-500/10 focus:bg-white dark:focus:bg-slate-900 outline-none transition-all font-bold text-sm tracking-tight shadow-sm" onChange={e => { setNewValidFrom(e.target.value); }} type="date" value={newValidFrom} />
                  <p className="text-[9px] text-slate-500 dark:text-slate-400 font-bold uppercase italic leading-relaxed px-1 opacity-60">{t("common.workspace_settings.valid_from_note") || "Payroll calculations will use this configuration from this date forward."}</p>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-3 px-1">
                    <label className={LABEL_BASE}>{t("common.workspace_settings.work_unit")}</label>
                    <Combobox className="bg-slate-50 dark:bg-slate-800 border-slate-100 dark:border-slate-800 h-14" onChange={(v) => { setWorkUnit(parseInt(v)); }} options={[{ value: "1", label: t("common.workspace_settings.work_unit_options.1min"), description: t("common.workspace_settings.work_unit_options.1min_desc"), icon: <Clock size={14} /> }, { value: "15", label: t("common.workspace_settings.work_unit_options.15min"), description: t("common.workspace_settings.work_unit_options.15min_desc"), icon: <Clock size={14} /> }, { value: "30", label: t("common.workspace_settings.work_unit_options.30min"), description: t("common.workspace_settings.work_unit_options.30min_desc"), icon: <Clock size={14} /> }, { value: "60", label: t("common.workspace_settings.work_unit_options.60min"), description: t("common.workspace_settings.work_unit_options.60min_desc"), icon: <Clock size={14} /> }]} value={workUnit.toString() || "15"} />
                  </div>
                  <div className="space-y-3 px-1">
                    <label className={LABEL_BASE}>{t("common.workspace_settings.rounding_policy")}</label>
                    <Combobox className="bg-slate-50 dark:bg-slate-800 border-slate-100 dark:border-slate-800 h-14" onChange={setRoundingPolicy} options={[{ value: "none", label: t("common.workspace_settings.rounding_options.none"), icon: <ShieldAlert size={14} /> }, { value: "floor", label: t("common.workspace_settings.rounding_options.floor"), icon: <Calculator size={14} /> }, { value: "ceil", label: t("common.workspace_settings.rounding_options.ceil"), icon: <Calculator size={14} /> }, { value: "round", label: t("common.workspace_settings.rounding_options.round"), icon: <Calculator size={14} /> }]} value={roundingPolicy || "none"} />
                  </div>
                </div>
                <div className="space-y-3 px-1">
                  <label className={LABEL_BASE}>{t("common.workspace_settings.early_arrival_strategy")}</label>
                  <Combobox
                    className="bg-slate-50 dark:bg-slate-800 border-slate-100 dark:border-slate-800 h-14"
                    onChange={(v) => { setEarlyArrivalStrategy(v as "block" | "allow" | "clamp"); }}

                    options={[
                      { value: "block", label: t("common.workspace_settings.early_arrival_options.block"), description: t("common.workspace_settings.early_arrival_options.block_desc"), icon: <ShieldAlert size={14} /> },
                      { value: "allow", label: t("common.workspace_settings.early_arrival_options.allow"), description: t("common.workspace_settings.early_arrival_options.allow_desc"), icon: <Zap size={14} /> },
                      { value: "clamp", label: t("common.workspace_settings.early_arrival_options.clamp"), description: t("common.workspace_settings.early_arrival_options.clamp_desc"), icon: <Settings2 size={14} /> }
                    ]}
                    value={earlyArrivalStrategy}
                  />
                </div>
                <div className="pt-8 border-t border-slate-50 dark:border-slate-800 grid grid-cols-2 gap-6">
                  <Button onClick={() => { setShowCreateModal(false); }} size="lg" variant="outline">{t("common.cancel").toUpperCase()}</Button>
                  <Button loading={updateRulesMutation.isPending} onClick={handleSaveNewVersion} size="lg" variant="secondary">{(t("common.workspace_settings.save_config") || "SAVE").toUpperCase()}</Button>
                </div>
              </div>
            </Modal>
          </>
        )}

        {activeTab === "patterns" && (
          <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 overflow-hidden shadow-sm p-4"><WorkingPatternsPage /></div>
        )}

        {activeTab === "rules" && (
          <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 overflow-hidden shadow-sm p-4"><AssignmentRulesPage /></div>
        )}

      </div>

      <Modal
        icon={<AlertTriangle size={24} />}
        isOpen={showReprocessConfirm}
        maxWidth="md"
        onClose={() => !reprocessMutation.isPending && !pollingJobId && setShowReprocessConfirm(false)}
        title={t("reports.reprocess.bulk_confirm_title") || "Confirm Reprocessing"}
      >
        <div className="space-y-6 pt-2 animate-in fade-in duration-500">
          <div className="p-4 bg-orange-50 dark:bg-orange-950 rounded-2xl border border-orange-200 dark:border-orange-800">
            <p className="text-sm font-bold text-orange-800 dark:text-orange-300">
              Are you sure you want to reprocess attendance from {reprocessStart} to {reprocessEnd}?
            </p>
            <p className="text-xs text-orange-700 dark:text-orange-400 mt-2">
              {t("reports.reprocess.bulk_confirm_message") || "This action will recalculate work hours, overtime, and late/early statuses for ALL employees in the selected date range. This process cannot be undone."}
            </p>
          </div>

          {pollingJobId && jobStatusQuery.data ? (
            <div className="space-y-3 pt-4 border-t border-slate-100 dark:border-slate-800">
              <div className="flex justify-between text-xs font-bold text-slate-500 uppercase tracking-widest">
                <span>{t("common.working")}</span>
                <span>{Math.round(jobStatusQuery.data.progress.percentage).toString()}%</span>
              </div>
              <div className="h-3 w-full bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                <div 
                  className="h-full bg-orange-500 transition-all duration-500 ease-out"
                  style={{ width: `${Math.max(5, jobStatusQuery.data.progress.percentage).toString()}%` }}
                />
              </div>
              <p className="text-center text-xs text-slate-400 mt-2 font-medium">
                {t("common.workspace_settings.please_wait_minutes")}
              </p>
            </div>
          ) : (
            <div className="flex gap-4 border-t border-slate-100 dark:border-slate-800 pt-4">
              <button
                className="flex-1 px-6 py-3.5 rounded-2xl font-bold text-xs uppercase tracking-widest text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800 transition-all active:scale-95"
                disabled={reprocessMutation.isPending}
                onClick={() => { setShowReprocessConfirm(false); }}
              >
                {t("common.cancel")}
              </button>
              <button
                className="flex-[1.5] bg-orange-600 hover:bg-orange-700 text-white font-bold px-6 py-3.5 rounded-2xl flex items-center justify-center gap-3 transition-all active:scale-95 disabled:opacity-50 shadow-xl text-xs uppercase tracking-widest"
                disabled={reprocessMutation.isPending || !reprocessStart || !reprocessEnd}
                onClick={handleReprocessSubmit}
              >
                {reprocessMutation.isPending ? (
                    <RefreshCw className="w-4 h-4 animate-spin" />
                ) : (
                    <RefreshCw size={18} />
                )}
                {(t("reports.reprocess.confirm") || "CONFIRM").toUpperCase()}
              </button>
            </div>
          )}
        </div>
      </Modal>

    </div>
  );
}

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import {
    ArrowLeftRight,
    Plus,
    Clock,
    CheckCircle,
    XCircle,
    Check,
    X,
    ArrowRight,
    CalendarDays,
    HelpCircle,
    ChevronDown,
    ChevronRight,
    Info,
} from "lucide-react";
import React, { useState } from "react";
import { useTranslation } from "react-i18next";

import ApprovalListLayout, { TabConfig } from "@/components/templates/approval-list-layout";
import Button from "@/components/ui/button";
import { Combobox } from "@/components/ui/combobox";
import FormField from "@/components/ui/form-field";
import StatusBadge from "@/components/ui/status-badge";
import { useToast } from "@/components/ui/toast";
import { useDateTimeFormatter } from "@/hooks/use-datetime";
import { useAllEmployees } from "@/hooks/use-employees";
import { cn } from "@/lib/utils";

import {
    getCurrentWorkspaceId,

} from "../lib/api";
import {
    fetchShiftSwaps,
    createShiftSwap,
    approveShiftSwap,
    fetchShiftSwapStats,
    ShiftSwapStatus,
} from "../lib/api/shift-swaps";

type TabType = "pending_target" | "pending_admin" | "approved" | "rejected" | "cancelled";

export default function ShiftSwapsPage() {
    const { t } = useTranslation();
    const wsId = getCurrentWorkspaceId();
    const queryClient = useQueryClient();
    const { formatDate } = useDateTimeFormatter();
    const [activeTab, setActiveTab] = useState<TabType>("pending_admin");
    const [showCreateForm, setShowCreateForm] = useState(false);
    const [showGuide, setShowGuide] = useState(false);
    const toast = useToast();

    // Form state
    const [requesterId, setRequesterId] = useState("");
    const [targetId, setTargetId] = useState("");
    const [swapDate, setSwapDate] = useState("");
    const [reason, setReason] = useState("");

    const { data: swaps = [], isLoading } = useQuery({
        queryKey: ["shift-swaps", wsId, activeTab],
        queryFn: () => fetchShiftSwaps(wsId!, activeTab),
        enabled: !!wsId,
    });

    const { data: stats } = useQuery({
        queryKey: ["shift-swap-stats", wsId],
        queryFn: () => fetchShiftSwapStats(wsId!),
        enabled: !!wsId,
    });

    const { employees } = useAllEmployees(wsId);

    const createMutation = useMutation({
        mutationFn: (data: {
            requester_id: string;
            target_id: string;
            swap_date: string;
            reason?: string;
        }) => createShiftSwap(wsId!, data),
        onSuccess: () => {
            void queryClient.invalidateQueries({ queryKey: ["shift-swaps"] });
            toast.success(t("shift_swaps.messages.create_success"));
            setShowCreateForm(false);
            setRequesterId("");
            setTargetId("");
            setSwapDate("");
            setReason("");
        },
        onError: () => {
            toast.error(t("shift_swaps.messages.create_error"));
        },
    });

    const approveMutation = useMutation({
        mutationFn: (data: { id: string; status: ShiftSwapStatus }) =>
            approveShiftSwap(wsId!, data.id, { status: data.status }),
        onSuccess: () => {
            void queryClient.invalidateQueries({ queryKey: ["shift-swaps"] });
            void queryClient.invalidateQueries({ queryKey: ["employee-rosters"] });
            void queryClient.invalidateQueries({ queryKey: ["workspace-schedules"] });
            toast.success(t("common.success"));
        },
    });

    const handleCreate = () => {
        if (!requesterId || !targetId || !swapDate) return;
        createMutation.mutate({
            requester_id: requesterId,
            target_id: targetId,
            swap_date: swapDate,
            reason: reason || undefined,
        });
    };

    if (!wsId)
        return (
            <div className="p-12 text-center text-slate-500 dark:text-slate-400 font-bold italic uppercase tracking-widest text-xs opacity-50">
                {t("common.select_workspace")}
            </div>
        );

    const tabs: TabConfig[] = [
        { id: "pending_admin", label: t("shift_swaps.status.pending_admin"), icon: <Clock size={14} />, colorScheme: "amber" },
        { id: "approved", label: t("shift_swaps.status.approved"), icon: <CheckCircle size={14} />, colorScheme: "emerald" },
        { id: "rejected", label: t("shift_swaps.status.rejected"), icon: <XCircle size={14} />, colorScheme: "rose" },
        { id: "cancelled", label: t("shift_swaps.status.cancelled"), icon: <XCircle size={14} />, colorScheme: "slate" },
    ];

    const tableHeaders = [
        <th className="px-10 py-6 text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-[0.25em]" key="date">
            {t("shift_swaps.swap_date")}
        </th>,
        <th className="px-8 py-6 text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-[0.25em]" key="requester">
            {t("shift_swaps.requester")}
        </th>,
        <th className="px-4 py-6 text-center" key="arrow">
            <ArrowLeftRight className="text-slate-400 mx-auto" size={14} />
        </th>,
        <th className="px-8 py-6 text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-[0.25em]" key="target">
            {t("shift_swaps.target")}
        </th>,
        <th className="px-8 py-6 text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-[0.25em]" key="reason">
            {t("shift_swaps.reason")}
        </th>,
        <th className="px-8 py-6 text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-[0.25em] text-center" key="status">
            {t("common.status")}
        </th>,
        <th className="px-10 py-6" key="actions"></th>,
    ];

    return (
        <ApprovalListLayout
            activeTab={activeTab}
            banner={
                <>
                    {/* Usage Guide */}
                    <div className="bg-gradient-to-br from-blue-50 to-indigo-50 dark:from-blue-950/30 dark:to-indigo-950/30 border border-blue-100 dark:border-blue-800/50 rounded-[2rem] overflow-hidden shadow-sm">
                        <button
                            className="flex items-center justify-between w-full px-8 py-5 group"
                            onClick={() => { setShowGuide(!showGuide); }}
                        >
                            <div className="flex items-center gap-3">
                                <div className="p-2 bg-blue-100 dark:bg-blue-900/50 rounded-xl">
                                    <HelpCircle className="text-blue-600 dark:text-blue-400" size={18} />
                                </div>
                                <span className="text-sm font-bold text-blue-700 dark:text-blue-300 uppercase tracking-widest">
                                    {t("shift_swaps.guide.title")}
                                </span>
                            </div>
                            {showGuide ? (
                                <ChevronDown className="text-blue-400" size={16} />
                            ) : (
                                <ChevronRight className="text-blue-400" size={16} />
                            )}
                        </button>

                        {!!showGuide && (
                            <div className="px-8 pb-8 animate-in slide-in-from-top-4 duration-300">
                                <div className="grid grid-cols-1 md:grid-cols-3 gap-6 pt-4 border-t border-blue-100 dark:border-blue-800/30">
                                    <div className="space-y-3">
                                        <div className="w-8 h-8 rounded-full bg-blue-100 dark:bg-blue-900/50 text-blue-600 dark:text-blue-400 flex items-center justify-center font-bold font-mono text-xs">
                                            1
                                        </div>
                                        <h4 className="font-bold text-sm text-slate-700 dark:text-slate-300">
                                            {t("shift_swaps.guide.step1.title")}
                                        </h4>
                                        <p className="text-[11px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider leading-relaxed opacity-80">
                                            {t("shift_swaps.guide.step1.desc")}
                                        </p>
                                    </div>
                                    <div className="space-y-3">
                                        <div className="w-8 h-8 rounded-full bg-indigo-100 dark:bg-indigo-900/50 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold font-mono text-xs">
                                            2
                                        </div>
                                        <h4 className="font-bold text-sm text-slate-700 dark:text-slate-300">
                                            {t("shift_swaps.guide.step2.title")}
                                        </h4>
                                        <p className="text-[11px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider leading-relaxed opacity-80">
                                            {t("shift_swaps.guide.step2.desc")}
                                        </p>
                                    </div>
                                    <div className="space-y-3">
                                        <div className="w-8 h-8 rounded-full bg-emerald-100 dark:bg-emerald-900/50 text-emerald-600 dark:text-emerald-400 flex items-center justify-center font-bold font-mono text-xs">
                                            3
                                        </div>
                                        <h4 className="font-bold text-sm text-slate-700 dark:text-slate-300">
                                            {t("shift_swaps.guide.step3.title")}
                                        </h4>
                                        <p className="text-[11px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider leading-relaxed opacity-80">
                                            {t("shift_swaps.guide.step3.desc")}
                                        </p>
                                    </div>
                                </div>

                                <div className="mt-6 p-4 bg-white/50 dark:bg-slate-900/30 rounded-2xl flex items-start gap-3">
                                    <Info className="text-blue-500 mt-0.5 shrink-0" size={16} />
                                    <p className="text-xs font-bold text-blue-800 dark:text-blue-200 tracking-tight leading-relaxed">
                                        {t("shift_swaps.guide.note")}
                                    </p>
                                </div>
                            </div>
                          )}
                    </div>

                    {/* Quick Stats */}
                    {!!stats && (
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 animate-in slide-in-from-bottom-4 duration-500 delay-100">
                            {[
                                {
                                    key: "pending_admin",
                                    label: t("shift_swaps.status.pending_admin"),
                                    value: stats.pending_admin,
                                    color: "amber",
                                },
                                {
                                    key: "pending_target",
                                    label: t("shift_swaps.status.pending_target"),
                                    value: stats.pending_target,
                                    color: "blue",
                                },
                                {
                                    key: "approved",
                                    label: t("shift_swaps.status.approved"),
                                    value: stats.approved,
                                    color: "emerald",
                                },
                                {
                                    key: "rejected",
                                    label: t("shift_swaps.status.rejected"),
                                    value: stats.rejected,
                                    color: "rose",
                                },
                            ].map((stat) => (
                                <div
                                    className={cn(
                                        "bg-white dark:bg-slate-900 p-5 rounded-[2rem] border shadow-sm cursor-pointer hover:shadow-md transition-all group",
                                        activeTab === stat.key
                                            ? `border-${stat.color}-300 dark:border-${stat.color}-700 ring-2 ring-${stat.color}-100 dark:ring-${stat.color}-900`
                                            : "border-slate-100 dark:border-slate-800 hover:border-slate-200 dark:hover:border-slate-700",
                                    )}
                                    key={stat.key}
                                    onClick={() => { setActiveTab(stat.key as TabType); }}
                                    onKeyDown={(e) => {
                                        if (e.key === "Enter" || e.key === " ") {
                                            e.preventDefault();
                                            setActiveTab(stat.key as TabType);
                                        }
                                    }}
                                    role="button"
                                    tabIndex={0}
                                >
                                    <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2 group-hover:text-slate-600 dark:group-hover:text-slate-300 transition-colors">
                                        {stat.label}
                                    </div>
                                    <div
                                        className={`text-3xl font-black tracking-tighter text-${stat.color}-600 dark:text-${stat.color}-400 font-mono`}
                                    >
                                        {stat.value}
                                    </div>
                                </div>
                            ))}
                        </div>
                      )}

                    {/* Create Form */}
                    {!!showCreateForm && (
                        <div className="bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 p-8 rounded-[2rem] shadow-sm animate-in zoom-in-95 duration-300 mb-8">
                            <h3 className="text-xl font-bold text-slate-700 dark:text-slate-200 uppercase tracking-tight mb-6 flex items-center gap-2">
                                <ArrowLeftRight className="text-primary-500" />
                                {t("shift_swaps.create_title")}
                            </h3>

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-6">
                                {/* Requester (Employee initiating swap) */}
                                <div className="space-y-3">
                                    <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ml-1">
                                        {t("shift_swaps.requester")}
                                    </label>
                                    <Combobox
                                        className="h-14 bg-slate-50 dark:bg-slate-800 border-slate-100 dark:border-slate-700"
                                        onChange={setRequesterId}
                                        options={employees.map((e) => ({
                                            value: e.id,
                                            label: e.full_name.toUpperCase(),
                                        }))}
                                        placeholder={t("common.employee")}
                                        value={requesterId}
                                    />
                                </div>

                                {/* Target (Employee covering shift) */}
                                <div className="space-y-3">
                                    <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ml-1">
                                        {t("shift_swaps.target")}
                                    </label>
                                    <Combobox
                                        className="h-14 bg-slate-50 dark:bg-slate-800 border-slate-100 dark:border-slate-700"
                                        disabled={!requesterId}
                                        onChange={setTargetId}
                                        options={employees
                                            .filter((e) => e.id !== requesterId)
                                            .map((e) => ({
                                                value: e.id,
                                                label: e.full_name.toUpperCase(),
                                            }))}
                                        placeholder={t("common.employee")}
                                        value={targetId}
                                    />
                                </div>
                            </div>

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
                                <FormField
                                    id="swap_date"
                                    inputClassName="text-slate-700 dark:text-slate-300 border-slate-100 dark:border-slate-800"
                                    label={t("shift_swaps.swap_date")}
                                    name="swap_date"
                                    onChange={(e) => { setSwapDate(e.target.value); }}
                                    required
                                    type="date"
                                    value={swapDate}
                                />

                                <FormField
                                    id="swap_reason"
                                    inputClassName="text-slate-700 dark:text-slate-300 border-slate-100 dark:border-slate-800"
                                    label={t("shift_swaps.reason")}
                                    name="reason"
                                    onChange={(e) => { setReason(e.target.value); }}
                                    placeholder={t("common.no_notes")}
                                    type="text"
                                    value={reason}
                                />
                            </div>

                            <div className="flex justify-end gap-4 pt-6 border-t border-slate-50 dark:border-slate-800">
                                <Button
                                    onClick={() => { setShowCreateForm(false); }}
                                    variant="outline"
                                >
                                    {t("common.cancel")}
                                </Button>
                                <Button
                                    disabled={
                                        createMutation.isPending ||
                                        !requesterId ||
                                        !targetId ||
                                        !swapDate
                                    }
                                    onClick={handleCreate}
                                >
                                    {t("common.save")}
                                </Button>
                            </div>
                        </div>
                      )}
                </>
            }
            emptyMessage={t("shift_swaps.messages.no_data")}
            headerActions={
                <Button icon={<Plus size={18} />} onClick={() => { setShowCreateForm(!showCreateForm); }}>
                    {t("shift_swaps.create_btn")}
                </Button>
            }
            isEmpty={swaps.length === 0}
            isLoading={isLoading}
            onTabChange={(id) => { setActiveTab(id as TabType); }}
            subtitle={t("shift_swaps.subtitle")}
            tableHeaders={tableHeaders}
            tabs={tabs}
            title={t("shift_swaps.title")}
        >
            {swaps.map((swap) => (
                <tr
                    className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-all group"
                    key={swap.id}
                >
                    {/* Date */}
                    <td className="px-10 py-6">
                        <div className="inline-flex items-center gap-2 bg-slate-50 dark:bg-slate-800 px-4 py-2 rounded-xl border border-slate-100 dark:border-slate-800 shadow-inner">
                            <CalendarDays
                                className="text-primary-600 dark:text-primary-400"
                                size={14}
                            />
                            <span className="text-xs font-bold text-slate-700 dark:text-slate-200 uppercase tracking-tighter">
                                {formatDate(swap.swap_date)}
                            </span>
                        </div>
                    </td>

                    {/* Requester */}
                    <td className="px-8 py-6">
                        <div>
                            <div className="font-bold text-slate-700 dark:text-slate-200 text-sm tracking-tight uppercase leading-none mb-1">
                                {swap.requester_name ?? "—"}
                            </div>
                            <div className="text-[10px] text-primary-600 dark:text-primary-400 font-bold">
                                {swap.requester_shift_name ?? t("shift_swaps.day_off")}
                            </div>
                        </div>
                    </td>

                    {/* Arrow */}
                    <td className="px-4 py-6 text-center">
                        <ArrowRight
                            className="text-slate-300 dark:text-slate-600 mx-auto"
                            size={16}
                        />
                    </td>

                    {/* Target */}
                    <td className="px-8 py-6">
                        <div>
                            <div className="font-bold text-slate-700 dark:text-slate-200 text-sm tracking-tight uppercase leading-none mb-1">
                                {swap.target_name ?? "—"}
                            </div>
                            <div className="text-[10px] text-primary-600 dark:text-primary-400 font-bold">
                                {swap.target_shift_name ?? t("shift_swaps.day_off")}
                            </div>
                        </div>
                    </td>

                    {/* Reason */}
                    <td className="px-8 py-6">
                        <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-tight line-clamp-2 italic opacity-70 leading-relaxed">
                            {swap.reason ?? t("common.no_notes")}
                        </p>
                    </td>

                    {/* Status */}
                    <td className="px-8 py-6 text-center">
                        <StatusBadge variant={
                            swap.status === "pending_admin" ? "warning" :
                            swap.status === "approved" ? "success" : "danger"
                        }>
                            {t(`shift_swaps.status.${swap.status}`)}
                        </StatusBadge>
                    </td>

                    {/* Actions */}
                    <td className="px-10 py-6 text-right">
                        {swap.status === "pending_admin" && (
                            <div className="flex items-center justify-end gap-3 opacity-0 group-hover:opacity-100 transition-all duration-300">
                                <button
                                    className="p-3 bg-emerald-600 text-white hover:bg-emerald-700 rounded-xl shadow-lg shadow-emerald-100 transition-all active:scale-90"
                                    onClick={() =>
                                        { approveMutation.mutate({
                                            id: swap.id,
                                            status: "approved",
                                        }); }
                                    }
                                    title={t("common.approve")}
                                >
                                    <Check size={18} />
                                </button>
                                <button
                                    className="p-3 bg-white dark:bg-slate-900 text-rose-600 dark:text-rose-300 hover:bg-rose-50 dark:hover:bg-rose-950 rounded-xl shadow-md border border-rose-100 dark:border-rose-800 transition-all active:scale-90"
                                    onClick={() =>
                                        { approveMutation.mutate({
                                            id: swap.id,
                                            status: "rejected",
                                        }); }
                                    }
                                    title={t("common.reject")}
                                >
                                    <X size={18} />
                                </button>
                            </div>
                        )}
                    </td>
                </tr>
            ))}
        </ApprovalListLayout>
    );
}

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Link } from "@tanstack/react-router";
import {
  CalendarRange,
  Plus,
  User,
  LayoutGrid,
  List,
  Zap
} from "lucide-react";
import React, { useState } from "react";
import { useTranslation } from "react-i18next";

import { format, addDays } from "date-fns";

import { EmployeeSearch } from "@/components/common/employee-search";
import { useToast } from "@/components/ui/toast";
import {
  fetchEmployees,
  fetchShifts,
  createShift,
  updateShift,
  fetchWorkspaceSchedules,
  fetchAssignmentHistory,
  upsertRoster,
  bulkUpsertRoster,
  deleteRoster,
  getCurrentWorkspaceId,
  fetchWorkingPatterns,
  assignPattern
} from "@/lib/api";
import {
  AssignPatternRequest,
  Shift,
  Employee
} from "@/lib/api/types";
import { ROUTES } from "@/lib/routes";

import { AssignmentHistory } from "../components/shifts/assignment-history";
import { CreateShiftModal } from "../components/shifts/create-shift-modal";
import { EditShiftModal } from "../components/shifts/edit-shift-modal";
import { PatternAssignmentForm } from "../components/shifts/pattern-assignment-form";
import { PriorityLegend } from "../components/shifts/priority-legend";
import { ShiftList } from "../components/shifts/shift-list";
import { ShiftPickerModal } from "../components/shifts/shift-picker-modal";
import { WeeklyRosterGrid } from "../components/shifts/weekly-roster-grid";



type TabType = "weekly-roster" | "assignments" | "directory";

export default function ShiftsPage() {
  const { t } = useTranslation();
  const wsId = getCurrentWorkspaceId() ?? "";
  const queryClient = useQueryClient();
  const toast = useToast();
  const [activeTab, setActiveTab] = useState<TabType>("weekly-roster");

  // Selection states
  const [selectedEmployee, setSelectedEmployee] = useState<Employee | null>(null);
  const [selectedDays, setSelectedDays] = useState<string[]>([]);

  // Shift Picker Modal State
  const [isShiftPickerOpen, setIsShiftPickerOpen] = useState(false);
  const [targetDates, setTargetDates] = useState<string[]>([]);

  // Weekly Roster Navigation
  const [currentDate, setCurrentDate] = useState(new Date());

  // Fixed Assignment Form State
  const [selectedPatternId, setSelectedPatternId] = useState("");
  const [startDate, setStartDate] = useState(format(new Date(), 'yyyy-MM-01'));
  const [endDate, setEndDate] = useState<string>("");
  const [isForever, setIsForever] = useState(true);

  // Create Shift Modal State
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [newShiftName, setNewShiftName] = useState("");
  const [newShiftSymbol, setNewShiftSymbol] = useState("");
  const [newShiftStart, setNewShiftStart] = useState("08:00");
  const [newShiftEnd, setNewShiftEnd] = useState("17:00");
  const [newShiftBreak, setNewShiftBreak] = useState(60);
  const [newShiftGrace, setNewShiftGrace] = useState(15);
  const [newBreakStart, setNewBreakStart] = useState("");
  const [newBreakEnd, setNewBreakEnd] = useState("");
  const [isFixedBreak, setIsFixedBreak] = useState(false);
  const [isAutoDeduct, setIsAutoDeduct] = useState(true);

  // Edit Shift State
  const [editingShift, setEditingShift] = useState<Shift | null>(null);
  const [isCorrection, setIsCorrection] = useState(false);
  const [correctionEffectiveDate, setCorrectionEffectiveDate] = useState(format(new Date(), 'yyyy-MM-dd'));

  // Queries
  const { data: employeesData } = useQuery({
    queryKey: ["employees", wsId],
    queryFn: () => fetchEmployees(wsId, 1, 3000),
    enabled: !!wsId,
  });
  const _employees = employeesData?.data ?? [];

  const { data: shifts } = useQuery({
    queryKey: ["shifts", wsId],
    queryFn: () => fetchShifts(wsId),
    enabled: !!wsId,
  });

  const { data: patterns } = useQuery({
    queryKey: ["working-patterns", wsId],
    queryFn: () => fetchWorkingPatterns(wsId),
    enabled: !!wsId,
  });

  // Weekly Dates Logic
  const startOfWeek = new Date(currentDate);
  startOfWeek.setDate(currentDate.getDate() - currentDate.getDay() + 1); // Monday
  const weekDays = Array.from({ length: 7 }, (_, index) => {
    const d = new Date(startOfWeek);
    d.setDate(startOfWeek.getDate() + index);
    return d;
  });

  // Fetch Effective Schedules (Bulk)
  const { data: allSchedules } = useQuery({
    queryKey: ["schedules", wsId, format(startOfWeek, 'yyyy-MM-dd')],
    queryFn: () => fetchWorkspaceSchedules(
      wsId,
      format(weekDays[0], 'yyyy-MM-dd'),
      format(weekDays[6], 'yyyy-MM-dd')
    ),
    enabled: !!wsId,
  });

  const { data: history } = useQuery({
    queryKey: ["assignment_history", wsId],
    queryFn: () => fetchAssignmentHistory(wsId),
    enabled: !!wsId,
  });

  // Find schedule for selected employee
  const employeeSchedule = allSchedules?.find(s => s.employee_id === selectedEmployee?.id);

  // Mutations
  const assignPatternMutation = useMutation({
    mutationFn: (data: AssignPatternRequest) => assignPattern(wsId, selectedEmployee!.id, data),
    onSuccess: () => {
      toast.success(t("shifts.messages.assign_success"));
      setSelectedPatternId("");
      setEndDate("");
      setIsForever(true);
      void queryClient.invalidateQueries({ queryKey: ["schedules"] });
      void queryClient.invalidateQueries({ queryKey: ["assignment_history"] });
    },
    onError: (error: Error) => { toast.error(error.message, t("shifts.messages.assign_error")); }
  });

  const _rosterMutation = useMutation({
    mutationFn: (data: { date: string; shift_id: string | null; notes?: string }) => upsertRoster(wsId, selectedEmployee!.id, data),
    onSuccess: () => {
      toast.success(t("shifts.messages.update_roster_success"));
      void queryClient.invalidateQueries({ queryKey: ["schedules"] });
      void queryClient.invalidateQueries({ queryKey: ["assignment_history"] });
    },
    onError: (error: Error) => { toast.error(error.message, t("shifts.messages.update_roster_error")); }
  });

  const bulkRosterMutation = useMutation({
    mutationFn: (items: { date: string; shift_id: string | null }[]) => bulkUpsertRoster(wsId, selectedEmployee!.id, items),
    onSuccess: () => {
      toast.success(t("shifts.messages.bulk_update_success"));
      setSelectedDays([]);
      void queryClient.invalidateQueries({ queryKey: ["schedules"] });
      void queryClient.invalidateQueries({ queryKey: ["assignment_history"] });
    },
    onError: (error: Error) => { toast.error(error.message, t("shifts.messages.bulk_update_error")); }
  });

  const deleteRosterMutation = useMutation({
    mutationFn: (date: string) => deleteRoster(wsId, selectedEmployee!.id, date),
    onSuccess: () => {
      toast.success(t("shifts.messages.remove_override_success"));
      void queryClient.invalidateQueries({ queryKey: ["schedules"] });
      void queryClient.invalidateQueries({ queryKey: ["assignment_history"] });
    },
    onError: (error: Error) => { toast.error(error.message, t("shifts.messages.remove_override_error")); }
  });

  const createShiftMutation = useMutation({
    mutationFn: (data: Partial<Shift>) => createShift(wsId, data),
    onSuccess: () => {
      toast.success(t("shifts.messages.create_shift_success", { name: newShiftName }));
      setNewShiftName("");
      setNewShiftSymbol("");
      setNewShiftStart("08:00");
      setNewShiftEnd("17:00");
      setNewShiftBreak(60);
      setNewShiftGrace(15);
      setNewBreakStart("");
      setNewBreakEnd("");
      setIsFixedBreak(false);
      setIsCreateModalOpen(false);
      setActiveTab("directory");
      void queryClient.invalidateQueries({ queryKey: ["shifts", wsId] });
    },
    onError: (error: Error) => { toast.error(error.message, t("shifts.messages.create_shift_error")); }
  });

  const updateShiftMutation = useMutation({
    mutationFn: ({ id, data }: { id: string, data: Partial<Shift> }) => updateShift(wsId, id, data),
    onSuccess: () => {
      toast.success(t("shifts.messages.update_shift_success"));
      setEditingShift(null);
      void queryClient.invalidateQueries({ queryKey: ["shifts", wsId] });
      void queryClient.invalidateQueries({ queryKey: ["schedules"] });
      void queryClient.invalidateQueries({ queryKey: ["assignment_history"] });
    },
    onError: (error: Error) => { toast.error(error.message, t("shifts.messages.update_shift_error")); }
  });

  // Handlers
  const handleAssign = () => {
    if (!selectedEmployee || !selectedPatternId) {
      toast.warning(t("shifts.messages.validation_missing_fields"));
      return;
    }
    assignPatternMutation.mutate({
      pattern_id: selectedPatternId,
      start_date: startDate,
      end_date: isForever ? null : endDate,
    });
  };

  const handleBulkAssign = (shiftId: string | null) => {
    if (!selectedEmployee || selectedDays.length === 0) return;
    const items = selectedDays.map(date => ({ date, shift_id: shiftId }));
    bulkRosterMutation.mutate(items);
  };

  const handleAssignAllWeek = (shiftId: string | null) => {
    if (!selectedEmployee) return;
    const items = weekDays.map(day => ({ date: format(day, 'yyyy-MM-dd'), shift_id: shiftId }));
    bulkRosterMutation.mutate(items);
  };

  const handleCopyPreviousWeek = async () => {
    if (!selectedEmployee || !allSchedules) return;
    const previousWeekStart = addDays(startOfWeek, -7);
    const previousWeekEnd = addDays(startOfWeek, -1);
    try {
      const previousSchedules = await fetchWorkspaceSchedules(wsId, format(previousWeekStart, 'yyyy-MM-dd'), format(previousWeekEnd, 'yyyy-MM-dd'));
      const empPrevious = previousSchedules.find(s => s.employee_id === selectedEmployee.id);
      if (!empPrevious) { toast.warning(t("shifts.messages.no_previous_data")); return; }
      const items = empPrevious.schedules.map((s, index) => ({ date: format(weekDays[index], 'yyyy-MM-dd'), shift_id: s.shift_id }));
      bulkRosterMutation.mutate(items);
    } catch (e: unknown) { toast.error(e instanceof Error ? e.message : String(e)); }
  };

  const handleCreateShift = () => {

    if (!newShiftName || !newShiftStart || !newShiftEnd) return;
    createShiftMutation.mutate({
      name: newShiftName,
      report_symbol: newShiftSymbol || undefined,
      start_time: newShiftStart + ":00",
      end_time: newShiftEnd + ":00",
      break_duration_minutes: newShiftBreak,
      early_punch_in_grace_period_minutes: newShiftGrace,
      is_break_overtime: false,
      ...(isFixedBreak && newBreakStart && newBreakEnd ? {
        break_start: newBreakStart + ":00",
        break_end: newBreakEnd + ":00"
      } : {}),
      is_break_auto_deduct: isAutoDeduct
    });
  };

  const handleUpdateShift = () => {
    if (!editingShift) return;
    updateShiftMutation.mutate({
      id: editingShift.id,
      data: {
        name: newShiftName,
        report_symbol: newShiftSymbol || null,
        start_time: newShiftStart,
        end_time: newShiftEnd,
        break_duration_minutes: newShiftBreak,
        early_punch_in_grace_period_minutes: newShiftGrace,
        is_break_overtime: false,
        ...(isFixedBreak && newBreakStart && newBreakEnd ? {
          break_start: newBreakStart,
          break_end: newBreakEnd
        } : {
          break_start: null,
          break_end: null
        }),
        is_break_auto_deduct: isAutoDeduct,
        is_correction: isCorrection,
        effective_date: isCorrection ? undefined : correctionEffectiveDate
      }
    });
  };

  const openEditModal = (shift: Shift) => {
    setEditingShift(shift);
    setNewShiftName(shift.name);
    setNewShiftSymbol(shift.report_symbol ?? "");
    setNewShiftStart(shift.start_time.substring(0, 5));
    setNewShiftEnd(shift.end_time.substring(0, 5));
    setNewShiftBreak(shift.break_duration_minutes);
    setNewShiftGrace(shift.early_punch_in_grace_period_minutes ?? 15);
    setNewBreakStart(shift.break_start?.substring(0, 5) ?? "");
    setNewBreakEnd(shift.break_end?.substring(0, 5) ?? "");
    setIsFixedBreak(!!shift.break_start);
    setIsAutoDeduct(shift.is_break_auto_deduct ?? true);
    setIsCorrection(false);
    setCorrectionEffectiveDate(format(new Date(), 'yyyy-MM-dd'));
  };

  const handleNavigateWeek = (direction: "prev" | "next") => {
    const d = new Date(currentDate);
    d.setDate(d.getDate() + (direction === "prev" ? -7 : 7));
    setCurrentDate(d);
    setSelectedDays([]);
  };



  return (
    <div className="space-y-6">
      {/* Header section */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-3xl font-bold text-slate-700 dark:text-slate-200 tracking-tight" data-testid="shifts-title">{t("shifts.title")}</h1>
          <p className="text-slate-500 dark:text-slate-400 mt-1">{t("shifts.subtitle")}</p>
        </div>
        <div className="flex items-center gap-3">
          <Link className="bg-white dark:bg-slate-900 hover:bg-slate-50 dark:hover:bg-slate-800 text-slate-700 dark:text-slate-200 font-bold px-4 py-2.5 rounded-2xl flex items-center gap-2 border border-slate-200 dark:border-slate-700 shadow-sm transition-all" search={{ tab: "patterns" } as never} to={ROUTES.SETTINGS.TIME}>
            <CalendarRange className="w-4 h-4" />
            <span className="text-xs uppercase tracking-widest">{t("patterns.manage_btn")}</span>
            { }
          </Link>
          <button className="bg-primary-600 hover:bg-primary-700 text-white font-bold px-6 py-2.5 rounded-2xl flex items-center gap-2 shadow-lg shadow-primary-100 transition-all" onClick={() => { setIsCreateModalOpen(true); }}>
            <Plus className="w-5 h-5" />
            <span className="text-xs uppercase tracking-widest">{t("shifts.create_btn")}</span>
          </button>
        </div>
      </div>

      {/* Tabs Navigation */}
      <div className="flex items-center gap-1 bg-slate-100 dark:bg-slate-700/50 p-1.5 rounded-[22px] w-fit border border-slate-200 dark:border-slate-700/50">
        <button className={`flex items-center gap-2 px-6 py-2.5 rounded-[18px] text-xs font-bold uppercase tracking-widest transition-all ${activeTab === 'weekly-roster' ? 'bg-white dark:bg-slate-900 text-primary-600 dark:text-primary-400 shadow-sm border border-slate-100 dark:border-slate-800' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200 dark:text-slate-700'}`} onClick={() => { setActiveTab("weekly-roster"); }}>
          <LayoutGrid size={14} /> {t("shifts.tabs.weekly_roster")}
        </button>
        <button className={`flex items-center gap-2 px-6 py-2.5 rounded-[18px] text-xs font-bold uppercase tracking-widest transition-all ${activeTab === 'assignments' ? 'bg-white dark:bg-slate-900 text-primary-600 dark:text-primary-400 shadow-sm border border-slate-100 dark:border-slate-800' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200 dark:text-slate-700'}`} onClick={() => { setActiveTab("assignments"); }}>
          <Zap size={14} /> {t("shifts.tabs.fixed_assignments", "Patterns & Rules")}
        </button>
        <button className={`flex items-center gap-2 px-6 py-2.5 rounded-[18px] text-xs font-bold uppercase tracking-widest transition-all ${activeTab === 'directory' ? 'bg-white dark:bg-slate-900 text-primary-600 dark:text-primary-400 shadow-sm border border-slate-100 dark:border-slate-800' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200 dark:text-slate-700'}`} onClick={() => { setActiveTab("directory"); }}>
          <List size={14} /> {t("shifts.tabs.directory")}
        </button>
      </div>

      <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
        {activeTab !== "directory" && (
          <div className="max-w-md mb-8">
            <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest mb-2 block ml-1">{t("common.employees")}</label>
            <EmployeeSearch
              clearOnEscape
              data-testid="employee-select"
              keyboardShortcut={["/", "Enter"]}
              onChange={(id) => { if (!id) setSelectedEmployee(null); }}
              onSelectEmployee={(emp) => { setSelectedEmployee(emp); }}
              placeholder={t("shifts.empty_state.title")}
              value={selectedEmployee?.id ?? ""}
              workspaceId={wsId}
            />
          </div>
        )}

        {!selectedEmployee && activeTab !== "directory" ? (
          <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-[40px] h-[500px] flex flex-col items-center justify-center text-center p-12 shadow-sm">
            <div className="bg-slate-50 dark:bg-slate-800 p-6 rounded-[32px] mb-6 animate-pulse text-slate-300 dark:text-slate-600"><User className="w-12 h-12" /></div>
            <h3 className="text-xl font-bold text-slate-700 dark:text-slate-200">{t("shifts.empty_state.title")}</h3>
            <p className="text-slate-500 dark:text-slate-400 mt-2 max-w-xs mx-auto text-sm">{t("shifts.empty_state.desc")}</p>
          </div>
        ) : activeTab === "weekly-roster" ? (
          /* TAB: WEEKLY ROSTER */
          <div className="space-y-6">
            <WeeklyRosterGrid
              currentDate={currentDate}
              employeeSchedule={employeeSchedule}
              onAssignAllWeek={() => {
                setTargetDates(weekDays.map(d => format(d, 'yyyy-MM-dd')));
                setIsShiftPickerOpen(true);
              }}
              onClearSelection={() => { setSelectedDays([]); }}
              onClearWeek={() => { handleAssignAllWeek(null); }}
              onCopyPreviousWeek={handleCopyPreviousWeek}
              onDeleteRoster={(date) => { deleteRosterMutation.mutate(date); }}
              onNavigateWeek={handleNavigateWeek}
              onOpenShiftPicker={(dates) => {
                setTargetDates(dates);
                setIsShiftPickerOpen(true);
              }}
              onToggleDaySelection={(dateString) => {
                if (selectedDays.includes(dateString)) {
                  setSelectedDays(selectedDays.filter(d => d !== dateString));
                } else {
                  setSelectedDays([...selectedDays, dateString]);
                }
              }}
              selectedDays={selectedDays}
              selectedEmployee={selectedEmployee!}
              weekDays={weekDays}
            />
            <PriorityLegend />
            <AssignmentHistory history={history} selectedEmployee={selectedEmployee} />
          </div>
        ) : activeTab === "assignments" ? (
          /* TAB: ASSIGNMENTS (Patterns & Rules) */
          <PatternAssignmentForm
            endDate={endDate}
            isForever={isForever}
            isLoading={assignPatternMutation.isPending}
            onAssign={handleAssign}
            patterns={patterns}
            selectedEmployee={selectedEmployee!}
            selectedPatternId={selectedPatternId}
            setEndDate={setEndDate}
            setIsForever={setIsForever}
            setSelectedPatternId={setSelectedPatternId}
            setStartDate={setStartDate}
            startDate={startDate}
          />
        ) : (
          /* TAB: DIRECTORY */
          <ShiftList onEdit={openEditModal} shifts={shifts} />
        )}
      </div>

      {/* Modals */}
      <CreateShiftModal
        isAutoDeduct={isAutoDeduct}
        isFixedBreak={isFixedBreak}
        isLoading={createShiftMutation.isPending}
        isOpen={isCreateModalOpen}
        newBreakEnd={newBreakEnd}
        newBreakStart={newBreakStart}
        newShiftBreak={newShiftBreak}
        newShiftEnd={newShiftEnd}
        newShiftName={newShiftName}
        newShiftStart={newShiftStart}
        newShiftSymbol={newShiftSymbol}
        onClose={() => { setIsCreateModalOpen(false); }}
        onCreateShift={handleCreateShift}
        setIsAutoDeduct={setIsAutoDeduct}
        setIsFixedBreak={setIsFixedBreak}
        setNewBreakEnd={setNewBreakEnd}
        setNewBreakStart={setNewBreakStart}
        setNewShiftBreak={setNewShiftBreak}
        setNewShiftEnd={setNewShiftEnd}
        setNewShiftName={setNewShiftName}
        setNewShiftStart={setNewShiftStart}
        setNewShiftSymbol={setNewShiftSymbol}
      />

      <ShiftPickerModal
        isOpen={isShiftPickerOpen}
        onClose={() => {
          setIsShiftPickerOpen(false);
          setTargetDates([]);
        }}
        onSelectShift={handleBulkAssign}
        shifts={shifts}
        targetDates={targetDates}
      />

      <EditShiftModal
        correctionEffectiveDate={correctionEffectiveDate}
        editingShift={editingShift}
        isAutoDeduct={isAutoDeduct}
        isCorrection={isCorrection}
        isFixedBreak={isFixedBreak}
        isLoading={updateShiftMutation.isPending}
        newBreakEnd={newBreakEnd}
        newBreakStart={newBreakStart}
        newShiftBreak={newShiftBreak}
        newShiftEnd={newShiftEnd}
        newShiftGrace={newShiftGrace}
        newShiftName={newShiftName}
        newShiftStart={newShiftStart}
        newShiftSymbol={newShiftSymbol}
        onClose={() => { setEditingShift(null); }}
        onUpdateShift={handleUpdateShift}
        setCorrectionEffectiveDate={setCorrectionEffectiveDate}
        setIsAutoDeduct={setIsAutoDeduct}
        setIsCorrection={setIsCorrection}
        setIsFixedBreak={setIsFixedBreak}
        setNewBreakEnd={setNewBreakEnd}
        setNewBreakStart={setNewBreakStart}
        setNewShiftBreak={setNewShiftBreak}
        setNewShiftEnd={setNewShiftEnd}
        setNewShiftGrace={setNewShiftGrace}
        setNewShiftName={setNewShiftName}
        setNewShiftStart={setNewShiftStart}
        setNewShiftSymbol={setNewShiftSymbol}
      />
    </div>
  );
}

import { ShieldAlert, ShieldCheck, Shield, Users, Plus, Trash2, ShieldHalf } from "lucide-react";
import React, { useState } from "react";
import { useTranslation } from "react-i18next";

import Modal from "@/components/ui/modal";
import PageHeader from "@/components/ui/page-header";
import { useToast } from "@/components/ui/toast";
import { useConfirm } from "@/hooks/use-confirm";
import { useSystemRoles } from "@/hooks/use-system-roles";
const roleDescriptions: Record<string, string> = {
  platform_admin: "system_roles.descriptions.platform_admin",
  support: "system_roles.descriptions.support",
  billing_admin: "system_roles.descriptions.billing_admin",
};

const roleIcons: Record<string, React.ElementType> = {
  platform_admin: ShieldAlert,

  support: ShieldCheck,
  billing_admin: ShieldHalf,
};

export default function SystemRolesPage() {
  const { t } = useTranslation();
  const { roles, isLoading, assignRole, revokeRole, isAssigning, isRevoking } = useSystemRoles();
  const { confirm, ConfirmationDialog } = useConfirm();
  const toast = useToast();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedRole, setSelectedRole] = useState<string | null>(null);
  const [userIdInput, setUserIdInput] = useState("");
  const [assignError, setAssignError] = useState("");

  const handleOpenAssign = (roleName: string) => {
    setSelectedRole(roleName);
    setUserIdInput("");
    setAssignError("");
    setIsModalOpen(true);
  };

  const handleAssignSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedRole || !userIdInput.trim()) return;
    try {
      setAssignError("");
      await assignRole({ userId: userIdInput.trim(), request: { role_name: selectedRole } });
      setIsModalOpen(false);
    } catch (error: unknown) {
      setAssignError(error instanceof Error ? error.message : t("system_roles.messages.assign_error"));

    }
  };

  const handleRevoke = async (userId: string, roleName: string) => {
    const isConfirmed = await confirm({
      title: t("system_roles.confirm.revoke_title"),
      message: t("system_roles.confirm.revoke_message"),
      variant: "danger"
    });
    if (isConfirmed) {
      try {
        await revokeRole({ userId, roleName });
        toast.success(t("system_roles.messages.revoke_success", { role: roleName }));
      } catch (error: unknown) {
        toast.error(error instanceof Error ? error.message : t("system_roles.messages.revoke_error"));

      }
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
