import { 
  KeyRound,
  Save,
  Check,
  Info,
  SlidersHorizontal,
  ChevronLeft,
  ChevronRight
} from "lucide-react";
import React, { useState, useEffect, useRef  } from "react";
import { useTranslation } from "react-i18next";

import PermissionGate from "@/components/common/permission-gate";
import { 
  DropdownMenu, 
  DropdownMenuTrigger, 
  DropdownMenuContent, 
  DropdownMenuCheckboxItem,
  DropdownMenuLabel,
  DropdownMenuSeparator
} from "@/components/ui/dropdown-menu";
import PageHeader from "@/components/ui/page-header";
import { useMyPermissions } from "@/hooks/use-permissions";
import { useWorkspaceRoles, useWorkspacePermissionsMatrix } from "@/hooks/use-workspace";
import { updateRolePermissions, getCurrentWorkspaceId } from "@/lib/api";
import { permissionGroups } from "@/lib/permission-groups";
import { cn } from "@/lib/utils";


export default function WorkspacePermissionsPage() {
  const { t } = useTranslation();
  const wsId = getCurrentWorkspaceId();
  const { roles, isLoading: isRolesLoading } = useWorkspaceRoles(wsId ?? undefined);
  const { matrix, isLoading: isMatrixLoading, refetch } = useWorkspacePermissionsMatrix(wsId ?? undefined);
  const { hasPermission } = useMyPermissions();
  const hasManagePermission = hasPermission("members:roles:manage");

  const [permissions, setPermissions] = useState<Record<string, string[]>>(matrix);
  const [hasChanges, setHasChanges] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [hiddenRoleIds, setHiddenRoleIds] = useState<string[]>([]);

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const [canScrollLeft, setCanScrollLeft] = useState(false);
  const [canScrollRight, setCanScrollRight] = useState(true);

  const visibleRoles = roles.filter(r => !hiddenRoleIds.includes(r.id));

  const handleScroll = () => {
    if (scrollContainerRef.current) {
      const { scrollLeft, scrollWidth, clientWidth } = scrollContainerRef.current;
      setCanScrollLeft(scrollLeft > 0);
      setCanScrollRight(scrollLeft + clientWidth < scrollWidth - 1);
    }
  };

  useEffect(() => {
    handleScroll();
    window.addEventListener("resize", handleScroll);
    return () => { window.removeEventListener("resize", handleScroll); };
  }, [visibleRoles.length, roles.length]);

  const scrollBy = (amount: number) => {
    if (scrollContainerRef.current) {
      scrollContainerRef.current.scrollBy({ left: amount, behavior: "smooth" });
    }
  };

  const [prevMatrix, setPrevMatrix] = useState<Record<string, string[]> | null>(null);

  if (matrix !== prevMatrix) {
    setPrevMatrix(matrix);
    if (Object.keys(matrix).length > 0) {
      setPermissions(matrix);
    }
  }



  const togglePermission = (role: { id: string; is_system: boolean }, permId: string) => {
    if (role.is_system || !hasManagePermission) return; // System permissions cannot be changed

    setPermissions(previous => {
      const rolePerms = previous[role.id] || [];
      const newPerms = rolePerms.includes(permId)
        ? rolePerms.filter(p => p !== permId)
        : [...rolePerms, permId];

      setHasChanges(true);
      return { ...previous, [role.id]: newPerms };
    });
  };

  const handleSave = async () => {
    if (!wsId) return;
    setIsSaving(true);
    try {
      // Find which roles have been modified by comparing with matrix
      const modifiedRoles = roles.filter(role => {
        const initial = matrix[role.id];
        const current = permissions[role.id];
        // simple array equality
        return initial.length !== current.length || !initial.every(p => current.includes(p));
      });

      await Promise.all(modifiedRoles.map(role => 
        updateRolePermissions(wsId, role.id, permissions[role.id])
      ));

      setHasChanges(false);
      void refetch();
    } catch (e) {
      console.error("Failed to save permissions", e);
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-10">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <PageHeader
          subtitle={t('permissions.subtitle', { defaultValue: 'Fine-tune access control for each role across all modules' })}
          title={t('permissions.title', { defaultValue: 'Permission Matrix' })}
        />
        <div className="flex items-center gap-3">
          {!!hasChanges && <span className="text-xs font-bold text-amber-500 animate-pulse">{t('permissions.unsavedChanges', { defaultValue: 'Unsaved changes' })}</span>}

          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <button className="flex items-center gap-2 px-4 py-2.5 rounded-2xl font-bold text-sm bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-slate-700 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors shadow-sm">
                <SlidersHorizontal className="text-slate-500" size={16} />
                {t('common.columns', { defaultValue: 'Columns' })}
              </button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-56">
              <DropdownMenuLabel>{t('permissions.visibleRoles', { defaultValue: 'Visible Roles' })}</DropdownMenuLabel>
              <DropdownMenuSeparator />
              {roles.map(role => (
                  <DropdownMenuCheckboxItem
                  checked={!hiddenRoleIds.includes(role.id)}
                  key={role.id}
                  onCheckedChange={(checked) => {
                    setHiddenRoleIds(previous => 
                      checked ? previous.filter(id => id !== role.id) : [...previous, role.id]
                    );
                  }}
                >
                  {t(`roles.${role.name}`, { defaultValue: role.name })}
                  {!!role.is_system && <span className="ml-2 text-[9px] text-slate-400 font-normal uppercase tracking-widest bg-slate-100 dark:bg-slate-800 px-1.5 py-0.5 rounded">{t('common.system', { defaultValue: 'System' })}</span>}
                </DropdownMenuCheckboxItem>
              ))}
            </DropdownMenuContent>
          </DropdownMenu>

          <PermissionGate permission="members:roles:manage">
            <button 
              className={cn(
                "flex items-center gap-2 px-5 py-2.5 rounded-2xl font-bold text-sm transition-all",
                hasChanges 
                  ? "bg-indigo-600 hover:bg-indigo-700 text-white shadow-lg shadow-indigo-200 dark:shadow-indigo-900/20 hover:-translate-y-0.5" 
                  : "bg-slate-100 dark:bg-slate-800 text-slate-400 cursor-not-allowed"
              )}
              disabled={!hasChanges || isSaving}
              onClick={handleSave}
            >
              {isSaving ? (
                <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
              ) : (
                <Save size={18} />
              )}
              {t('permissions.saveMatrix', { defaultValue: 'Save Matrix' })}
            </button>
          </PermissionGate>
        </div>
      </div>

      <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-sm overflow-hidden">
        {isRolesLoading || isMatrixLoading ? (
          <div className="flex justify-center p-20">
            <div className="w-10 h-10 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
          </div>
        ) : (
        <div className="relative group/table">
          {/* Scroll Visual Cues */}
          <div className={cn("absolute left-[280px] top-0 bottom-0 w-12 bg-gradient-to-r from-slate-200/50 dark:from-slate-950/50 to-transparent z-10 pointer-events-none transition-opacity duration-300", canScrollLeft ? "opacity-100" : "opacity-0")} />
          <div className={cn("absolute right-0 top-0 bottom-0 w-12 bg-gradient-to-l from-slate-200/50 dark:from-slate-950/50 to-transparent z-10 pointer-events-none transition-opacity duration-300", canScrollRight ? "opacity-100" : "opacity-0")} />

          {/* Scroll Buttons - Sticky to viewport */}
          <div className="sticky top-[30vh] z-30 h-0 w-full pointer-events-none">
            <button 
              className={cn("absolute left-[265px] top-0 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 shadow-lg text-slate-700 dark:text-slate-300 rounded-full p-2.5 transition-all hover:scale-110 pointer-events-auto", canScrollLeft ? "opacity-0 group-hover/table:opacity-100" : "opacity-0 pointer-events-none")}
              onClick={() => { scrollBy(-300); }}
            >
              <ChevronLeft size={20} />
            </button>

            <button 
              className={cn("absolute right-4 top-0 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 shadow-lg text-slate-700 dark:text-slate-300 rounded-full p-2.5 transition-all hover:scale-110 pointer-events-auto", canScrollRight ? "opacity-0 group-hover/table:opacity-100" : "opacity-0 pointer-events-none")}
              onClick={() => { scrollBy(300); }}
            >
              <ChevronRight size={20} />
            </button>
          </div>

          <div 
            className="overflow-x-auto custom-scrollbar relative z-0"
            onScroll={handleScroll}
            ref={scrollContainerRef}
          >
            <table className="w-full text-left border-collapse min-w-[800px]">
              <thead>
              <tr>
                <th className="sticky left-0 z-20 bg-slate-50 dark:bg-slate-900 border-b border-r border-slate-100 dark:border-slate-800 p-6 min-w-[280px]">
                  <div className="flex items-center gap-3">
                    <div className="p-2 bg-indigo-50 dark:bg-indigo-900/30 rounded-xl">
                      <KeyRound className="w-5 h-5 text-indigo-500" />
                    </div>
                    <div>
                      <h3 className="font-bold text-slate-800 dark:text-slate-200">{t('permissions.modules', { defaultValue: 'Modules' })}</h3>
                      <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mt-0.5">{t('permissions.permissionsLabel', { defaultValue: 'Permissions' })}</p>
                    </div>
                  </div>
                </th>
                {visibleRoles.map(role => (
                  <th className="bg-white dark:bg-slate-900 border-b border-slate-100 dark:border-slate-800 p-6 text-center min-w-[140px]" key={role.id}>
                    <div className="flex flex-col items-center justify-center gap-2">
                      <h4 className="font-bold text-sm text-slate-800 dark:text-slate-200 truncate w-full px-2" title={t(`roles.${role.name}`, { defaultValue: role.name })}>
                        {t(`roles.${role.name}`, { defaultValue: role.name })}
                      </h4>
                      {role.is_system ? (
                        <span className="px-2 py-0.5 rounded-lg text-[10px] font-bold uppercase tracking-wider bg-slate-100 dark:bg-slate-800 text-slate-500">{t('common.system', { defaultValue: 'System' })}</span>
                      ) : (
                        <span className="px-2 py-0.5 rounded-lg text-[10px] font-bold uppercase tracking-wider bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400">{t('common.custom', { defaultValue: 'Custom' })}</span>
                      )}
                    </div>
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {permissionGroups.map((group, _groupIndex) => (
                <React.Fragment key={group.id}>
                  {/* Group Header */}
                  <tr>
                    <td 
                      className="bg-slate-50/50 dark:bg-slate-800/20 border-b border-slate-100 dark:border-slate-800 py-3 px-6" 
                      colSpan={visibleRoles.length + 1}
                    >
                      <div className="flex items-center gap-2">
                        <group.icon className="w-4 h-4 text-slate-400" />
                        <span className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest">{t(`permissions.groups.${group.id}`, { defaultValue: group.name })}</span>
                      </div>
                    </td>
                  </tr>

                  {/* Permissions Rows */}
                  {group.permissions.map((perm, _permIndex) => (
                    <tr className="group hover:bg-slate-50 dark:hover:bg-slate-800/30 transition-colors" key={perm.id}>
                      <td className="sticky left-0 z-10 bg-white dark:bg-slate-900 group-hover:bg-slate-50 dark:group-hover:bg-slate-800 border-b border-r border-slate-100 dark:border-slate-800 p-4 pl-6">
                        <div className="flex items-start gap-2">
                          <div>
                            <p className="text-sm font-bold text-slate-700 dark:text-slate-300">{t(`permissions.items.${perm.id}.name`, { defaultValue: perm.name })}</p>
                            <p className="text-xs text-slate-500 mt-0.5">{t(`permissions.items.${perm.id}.desc`, { defaultValue: perm.desc })}</p>
                          </div>
                        </div>
                      </td>

                      {visibleRoles.map(role => {
                        const isChecked = permissions[role.id].includes(perm.id);
                        const isSystem = role.is_system;

                        return (
                          <td className="border-b border-slate-100 dark:border-slate-800 p-4 text-center" key={`${role.id}-${perm.id}`}>
                            <label className={cn(
                              "relative inline-flex items-center justify-center w-6 h-6 rounded-lg border-2 transition-all",
                              isSystem || !hasManagePermission ? "cursor-not-allowed opacity-60" : "cursor-pointer hover:border-indigo-400",
                              isChecked 
                                ? "bg-indigo-500 border-indigo-500 text-white" 
                                : "bg-transparent border-slate-200 dark:border-slate-700 text-transparent"
                            )}>
                              <input 
                                checked={isChecked} 
                                className="sr-only"
                                disabled={isSystem || !hasManagePermission}
                                onChange={() => { togglePermission(role, perm.id); }}
                                type="checkbox"
                              />
                              <Check className="w-4 h-4" strokeWidth={3} />
                            </label>
                          </td>
                        );
                      })}
                    </tr>
                  ))}
                </React.Fragment>
              ))}
            </tbody>
          </table>
          </div>
        </div>
        )}

        <div className="bg-slate-50 dark:bg-slate-800/50 p-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-center gap-2">
          <Info className="w-4 h-4 text-slate-400" />
          <p className="text-xs font-medium text-slate-500">{t('permissions.systemRoleInfo', { defaultValue: 'System roles (like Admin) have fixed permissions that cannot be modified.' })}</p>
        </div>
      </div>
    </div>
  );
}

import { Link } from "@tanstack/react-router";
import { 
  ShieldAlert, 
  Shield, 
  ShieldCheck, 
  User, 
  Plus, 
  MoreVertical, 
  Edit2, 
  Trash2,
  Users,
  CheckCircle2,
  ChevronRight,
} from "lucide-react";
import React, { useState } from "react";
import { useTranslation } from "react-i18next";

import PermissionGate from "@/components/common/permission-gate";
import RoleFormModal from "@/components/features/settings/role-form-modal";
import PageHeader from "@/components/ui/page-header";
import { useConfirm } from "@/hooks/use-confirm";
import { useWorkspaceRoles } from "@/hooks/use-workspace";
import { cn } from "@/lib/utils";

// No mock roles needed

const colorMap: Record<string, string> = {
  rose: "bg-rose-50 text-rose-600 dark:bg-rose-500/10 dark:text-rose-400 border-rose-200/50 dark:border-rose-500/20",
  indigo: "bg-indigo-50 text-indigo-600 dark:bg-indigo-500/10 dark:text-indigo-400 border-indigo-200/50 dark:border-indigo-500/20",
  emerald: "bg-emerald-50 text-emerald-600 dark:bg-emerald-500/10 dark:text-emerald-400 border-emerald-200/50 dark:border-emerald-500/20",
  slate: "bg-slate-50 text-slate-600 dark:bg-slate-500/10 dark:text-slate-400 border-slate-200/50 dark:border-slate-500/20"
};

const iconColorMap: Record<string, string> = {
  rose: "text-rose-500 dark:text-rose-400",
  indigo: "text-indigo-500 dark:text-indigo-400",
  emerald: "text-emerald-500 dark:text-emerald-400",
  slate: "text-slate-500 dark:text-slate-400"
};

export default function WorkspaceRolesPage() {
  const { t } = useTranslation();
  const { confirm, ConfirmationDialog } = useConfirm();
  const { roles, isLoading, deleteRole } = useWorkspaceRoles();
  const [activeMenu, setActiveMenu] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingRole, setEditingRole] = useState<{ id: string; name: string; description: string; color: string } | null>(null);

  const handleCreate = () => {
    setEditingRole(null);
    setIsModalOpen(true);
  };


  const handleEdit = (role: { id: string; name: string; description?: string; color: string }) => {
    setEditingRole({
      id: role.id,
      name: role.name,
      description: role.description ?? "",
      color: role.color
    });
    setIsModalOpen(true);
    setActiveMenu(null);
  };

  const handleDelete = async (roleId: string) => {
    const isConfirmed = await confirm({
      title: t('rolesPage.deleteTitle', { defaultValue: 'Delete Role' }),
      message: t('rolesPage.confirmDelete', { defaultValue: "Are you sure you want to delete this role?" }),
      variant: 'danger',
    });
    if (isConfirmed) {
      await deleteRole(roleId);
    }
    setActiveMenu(null);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <PageHeader
          subtitle={t('rolesPage.subtitle', { defaultValue: 'Define custom roles and manage access levels across the workspace' })}
          title={t('rolesPage.title', { defaultValue: 'Role Management' })}
        />
        <PermissionGate permission="members:roles:manage">
          <button className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-5 py-2.5 rounded-2xl font-bold text-sm transition-all shadow-lg shadow-indigo-200 dark:shadow-indigo-900/20 hover:shadow-xl hover:-translate-y-0.5 active:translate-y-0" onClick={handleCreate}>
            <Plus size={18} />
            {t('rolesPage.createRole', { defaultValue: 'Create Role' })}
          </button>
        </PermissionGate>
      </div>

      {isLoading ? (
        <div className="flex justify-center p-20">
          <div className="w-10 h-10 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
        </div>
      ) : (
      <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
        {roles.map((role) => {
          const Icon = role.is_system && role.name.toLowerCase() === 'admin' ? ShieldAlert 
                    : role.is_system && role.name.toLowerCase() === 'owner' ? ShieldCheck
                    : role.is_system ? User : Shield;
          const bgColors = colorMap[role.color] || colorMap.slate;
          const iconColors = iconColorMap[role.color] || iconColorMap.slate;

          return (
            <div 
              className="bg-white dark:bg-slate-900 rounded-[2rem] border border-slate-100 dark:border-slate-800 p-6 shadow-sm hover:shadow-xl hover:shadow-slate-200/50 dark:hover:shadow-black/20 transition-all duration-300 group"
              key={role.id}
            >
              <div className="flex items-start justify-between mb-4">
                <div className="flex items-center gap-4">
                  <div className={cn("w-14 h-14 rounded-2xl flex items-center justify-center border", bgColors)}>
                    <Icon className={iconColors} size={24} />
                  </div>
                  <div>
                    <div className="flex items-center gap-2">
                      <h3 className="text-lg font-bold text-slate-800 dark:text-slate-200">
                        {role.name}
                      </h3>
                      {!!role.is_system && (
                        <span className="px-2 py-0.5 rounded-lg text-[10px] font-bold uppercase tracking-wider bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400">
                          {t('common.system', { defaultValue: 'System' })}
                        </span>
                      )}
                    </div>
                    <div className="flex items-center gap-1.5 text-sm font-medium text-slate-500 mt-1">
                      <Users size={14} />
                      <span>{t('rolesPage.roleId', { defaultValue: 'Role ID:' })} {role.id.split('-')[0]}...</span>
                    </div>
                  </div>
                </div>

                {/* Action Menu */}
                <PermissionGate permission="members:roles:manage">
                  <div className="relative">
